import type { Question } from "./theoryQuestions";

export const theoryQuestionsExtra: Question[] = [
  // ===== ALERTNESS (101–140) =====
  { id: 101, question: "What should you do before moving off from the side of the road?", options: ["Sound your horn", "Check mirrors and look over your shoulder", "Switch on your headlights", "Rev the engine"], correctAnswer: 1, explanation: "Before moving off, always check your mirrors and blind spot by looking over your shoulder to ensure it is safe.", category: "Alertness" },
  { id: 102, question: "What could happen if you use a mobile phone while driving?", options: ["Nothing if you drive slowly", "You could fail to see hazards", "It improves multitasking", "It is legal on quiet roads"], correctAnswer: 1, explanation: "Using a mobile phone while driving is illegal and distracts you from seeing hazards and reacting in time.", category: "Alertness" },
  { id: 103, question: "When driving, where should you mainly look?", options: ["At the speedometer", "Well ahead along the road", "At the rear-view mirror", "At the road surface immediately in front"], correctAnswer: 1, explanation: "Look well ahead to spot hazards early. This gives you more time to react and plan your driving.", category: "Alertness" },
  { id: 104, question: "What is the main cause of distraction-related accidents?", options: ["Weather conditions", "Using in-car technology", "Road surface", "Other drivers"], correctAnswer: 1, explanation: "In-car technology such as phones, sat navs, and entertainment systems are a leading cause of driver distraction.", category: "Alertness" },
  { id: 105, question: "How can you avoid being distracted by a sat nav?", options: ["Programme it while driving slowly", "Set your destination before starting your journey", "Have a passenger hold it", "Turn the volume up loud"], correctAnswer: 1, explanation: "Always programme your sat nav before setting off. Adjusting it while driving takes your eyes off the road.", category: "Alertness" },
  { id: 106, question: "What should you do if you are dazzled by oncoming headlights?", options: ["Flash your headlights back", "Slow down and stop if necessary", "Close your eyes briefly", "Stare at the lights to adjust"], correctAnswer: 1, explanation: "If dazzled, slow down and if necessary stop. Avoid looking directly at the oncoming lights.", category: "Alertness" },
  { id: 107, question: "A bus has stopped at a bus stop ahead of you. What should you be aware of?", options: ["The bus may indicate to pull out", "Pedestrians may cross from behind the bus", "Both of these", "Neither of these"], correctAnswer: 2, explanation: "Watch for the bus pulling out and for pedestrians, especially children, crossing from behind the bus.", category: "Alertness" },
  { id: 108, question: "What should you do when approaching a blind junction?", options: ["Speed up to get through quickly", "Stop, look, and listen carefully", "Sound your horn and proceed", "Flash your headlights"], correctAnswer: 1, explanation: "At a blind junction, stop and lean forward to get the best view. Listen for approaching traffic.", category: "Alertness" },
  { id: 109, question: "Why is it important to check your mirrors regularly?", options: ["To keep the mirrors clean", "To be aware of traffic behind you", "It is not important", "Only before turning"], correctAnswer: 1, explanation: "Regular mirror checks keep you aware of the traffic situation around you, helping you make safe decisions.", category: "Alertness" },
  { id: 110, question: "What should you do if your windscreen becomes covered with insects?", options: ["Use your windscreen washers and wipers", "Open the window and wipe by hand", "Wait until you stop", "Ignore it"], correctAnswer: 0, explanation: "Use your windscreen washers and wipers to clear any obstruction to your view as soon as possible.", category: "Alertness" },
  { id: 111, question: "You are driving in heavy traffic and the vehicle in front brakes suddenly. What should you do?", options: ["Swerve to avoid it", "Brake firmly and keep control", "Sound your horn", "Change gear quickly"], correctAnswer: 1, explanation: "Apply the brakes firmly and progressively. Keep both hands on the steering wheel to maintain control.", category: "Alertness" },
  { id: 112, question: "What should you do if you feel drowsy while driving?", options: ["Open the window for fresh air", "Turn up the radio", "Stop in a safe place and rest", "Drink an energy drink and continue"], correctAnswer: 2, explanation: "If drowsy, stop at a safe place and rest. Fresh air or caffeine are only temporary solutions.", category: "Alertness" },
  { id: 113, question: "What should you watch for when driving past a line of parked cars?", options: ["Doors opening suddenly", "Children running out", "Vehicles pulling away", "All of these"], correctAnswer: 3, explanation: "Be alert for all these hazards when passing parked cars: doors opening, pedestrians stepping out, and cars pulling away.", category: "Alertness" },
  { id: 114, question: "How can loud music in the car affect your driving?", options: ["It helps you concentrate", "It can prevent you from hearing sirens", "It has no effect", "It makes you more alert"], correctAnswer: 1, explanation: "Loud music can prevent you from hearing emergency sirens, horns, or other important sounds.", category: "Alertness" },
  { id: 115, question: "What does MSM stand for in driving?", options: ["Motor, Speed, Move", "Mirror, Signal, Manoeuvre", "Move, Steer, Monitor", "Mirror, Steer, Move"], correctAnswer: 1, explanation: "MSM stands for Mirror, Signal, Manoeuvre — the routine you should follow before any driving manoeuvre.", category: "Alertness" },

  // ===== ATTITUDE (116–155) =====
  { id: 116, question: "What should you do if an aggressive driver is tailgating you?", options: ["Brake sharply to warn them", "Speed up to create a gap", "Stay calm and let them pass when safe", "Gesture at them to back off"], correctAnswer: 2, explanation: "Stay calm and don't react aggressively. Ease off the accelerator and let them pass when it is safe.", category: "Attitude" },
  { id: 117, question: "How should you drive near horse riders?", options: ["Sound your horn to alert them", "Pass quickly to reduce the time near them", "Drive slowly and give plenty of room", "Flash your headlights"], correctAnswer: 2, explanation: "Slow down, give plenty of room, and be patient. Horses can be startled by sudden noise or fast-moving vehicles.", category: "Attitude" },
  { id: 118, question: "You are in a traffic queue. What should you NOT do?", options: ["Wait patiently", "Keep a safe distance from the vehicle ahead", "Rev your engine impatiently", "Use the time to check mirrors"], correctAnswer: 2, explanation: "Revving your engine wastes fuel, increases pollution, and can cause distress to others. Be patient in queues.", category: "Attitude" },
  { id: 119, question: "What is tailgating?", options: ["Driving with your boot open", "Following too closely behind another vehicle", "Driving too slowly", "Reversing into a parking space"], correctAnswer: 1, explanation: "Tailgating means following the vehicle ahead too closely. It is dangerous as it reduces your stopping distance.", category: "Attitude" },
  { id: 120, question: "How should you react to an emergency vehicle with flashing lights behind you?", options: ["Speed up to get out of the way", "Stop immediately wherever you are", "Pull over safely when you can", "Ignore it if you're nearly at your destination"], correctAnswer: 2, explanation: "Check your mirrors, signal left, and pull over safely when there is a suitable place. Don't panic or stop suddenly.", category: "Attitude" },
  { id: 121, question: "A learner driver stalls at a junction. What should you do?", options: ["Sound your horn repeatedly", "Overtake them immediately", "Be patient and give them time", "Flash your headlights"], correctAnswer: 2, explanation: "Be patient. Everyone was a learner once. Allow them time to restart without adding pressure.", category: "Attitude" },
  { id: 122, question: "What is road rage?", options: ["A type of road surface", "Aggressive or violent behaviour by a driver", "Driving quickly on open roads", "Using your horn correctly"], correctAnswer: 1, explanation: "Road rage is aggressive or violent behaviour triggered by driving incidents. It is dangerous and illegal.", category: "Attitude" },
  { id: 123, question: "How should you treat pedestrians who are slow to cross the road?", options: ["Sound your horn to hurry them", "Rev your engine", "Be patient and allow them to cross", "Edge forward slowly"], correctAnswer: 2, explanation: "Be patient, especially with elderly or disabled pedestrians. They may need more time to cross safely.", category: "Attitude" },
  { id: 124, question: "When should you flash your headlights at other drivers?", options: ["To tell them to go", "To thank them", "Only to let others know you are there", "To show you are angry"], correctAnswer: 2, explanation: "The Highway Code states you should only flash headlights to let others know you are there, not to convey any other message.", category: "Attitude" },
  { id: 125, question: "You want to turn right at a junction but an oncoming vehicle is also turning right. What is the safest method?", options: ["Turn behind the oncoming vehicle (offside to offside)", "Turn in front of the oncoming vehicle", "Wait until the road is completely clear", "Sound your horn and proceed"], correctAnswer: 0, explanation: "Turning offside to offside (behind each other) is generally safer as it gives you a clearer view of oncoming traffic.", category: "Attitude" },
  { id: 126, question: "What is the best way to avoid road rage in yourself?", options: ["Allow plenty of time for your journey", "Drive as fast as possible", "Tailgate slow drivers", "Use your horn frequently"], correctAnswer: 0, explanation: "Planning ahead and allowing plenty of time reduces stress and the temptation to drive aggressively.", category: "Attitude" },
  { id: 127, question: "How should you behave at a pelican crossing when the amber light is flashing?", options: ["Speed up to clear the crossing", "Give way to pedestrians still crossing", "Sound your horn to clear pedestrians", "Stop and wait for green"], correctAnswer: 1, explanation: "A flashing amber means give way to pedestrians on the crossing. If clear, you may proceed.", category: "Attitude" },
  { id: 128, question: "You are driving behind a cyclist on a narrow road. What should you do?", options: ["Sound your horn to warn them", "Overtake as soon as possible", "Stay behind until it is safe to pass with plenty of room", "Drive very close behind them"], correctAnswer: 2, explanation: "Stay well back and wait until you can pass safely with at least 1.5 metres of space.", category: "Attitude" },

  // ===== SAFETY AND YOUR VEHICLE (129–175) =====
  { id: 129, question: "What is the purpose of a catalytic converter?", options: ["To increase engine power", "To reduce harmful exhaust emissions", "To improve fuel economy", "To reduce engine noise"], correctAnswer: 1, explanation: "A catalytic converter reduces harmful gases in the exhaust, helping to reduce air pollution.", category: "Vehicle Safety" },
  { id: 130, question: "When should you check your vehicle's engine oil level?", options: ["Only during an MOT", "Regularly, ideally weekly", "Only when the warning light comes on", "Once a year"], correctAnswer: 1, explanation: "Check your oil level regularly, at least weekly, and before long journeys. Low oil can cause engine damage.", category: "Vehicle Safety" },
  { id: 131, question: "What is the legal minimum depth of tread on a motorcycle tyre?", options: ["0.5 mm", "1.0 mm", "1.6 mm", "2.0 mm"], correctAnswer: 1, explanation: "The legal minimum tread depth for motorcycle tyres over 50cc is 1.0 mm across three-quarters of the width.", category: "Vehicle Safety" },
  { id: 132, question: "What colour is the coolant level warning light?", options: ["Green", "Blue", "Red", "Amber"], correctAnswer: 2, explanation: "The coolant temperature warning light is red. If it comes on while driving, stop as soon as it's safe.", category: "Vehicle Safety" },
  { id: 133, question: "How can you check that your indicators are working?", options: ["Ask a passenger to check", "Walk around the car with them switched on", "Check only at MOT time", "Listen for the clicking sound"], correctAnswer: 1, explanation: "The most reliable way is to switch them on and walk around the vehicle to check all indicator lights.", category: "Vehicle Safety" },
  { id: 134, question: "What should you do if your vehicle pulls to one side when braking?", options: ["Continue driving carefully", "Have the brakes checked immediately", "Only use the handbrake", "Pump the brake pedal"], correctAnswer: 1, explanation: "Pulling to one side under braking indicates a brake fault. Have it checked immediately by a mechanic.", category: "Vehicle Safety" },
  { id: 135, question: "What is the purpose of ABS (Anti-lock Braking System)?", options: ["To make the car stop faster", "To prevent the wheels from locking under heavy braking", "To apply the handbrake automatically", "To reduce tyre wear"], correctAnswer: 1, explanation: "ABS prevents wheels from locking, allowing you to maintain steering control during emergency braking.", category: "Vehicle Safety" },
  { id: 136, question: "What is the correct way to adjust your head restraint?", options: ["Level with the bottom of your ears", "The rigid part should be at least as high as the eyes or top of the ears", "As low as possible for comfort", "It doesn't matter"], correctAnswer: 1, explanation: "The head restraint should be adjusted so the rigid part is at least as high as your eyes or the top of your ears to protect against whiplash.", category: "Vehicle Safety" },
  { id: 137, question: "What should you check before driving someone else's vehicle?", options: ["That the radio works", "That you are insured to drive it", "That the colour matches your preference", "Nothing, if you have a licence"], correctAnswer: 1, explanation: "Always check that you have valid insurance to drive the vehicle. Driving without insurance is illegal.", category: "Vehicle Safety" },
  { id: 138, question: "Why is it important to keep your vehicle well-maintained?", options: ["To keep its resale value", "To keep it looking clean", "To ensure it is safe and roadworthy", "To avoid parking tickets"], correctAnswer: 2, explanation: "Regular maintenance ensures your vehicle is safe, reliable, and meets legal requirements for roadworthiness.", category: "Vehicle Safety" },
  { id: 139, question: "What is the purpose of engine coolant?", options: ["To clean the engine", "To keep the engine at its correct working temperature", "To lubricate the engine", "To reduce fuel consumption"], correctAnswer: 1, explanation: "Engine coolant absorbs heat from the engine and dissipates it through the radiator, preventing overheating.", category: "Vehicle Safety" },
  { id: 140, question: "What should you do if your oil pressure warning light comes on while driving?", options: ["Continue to your destination", "Stop as soon as it is safe and check the oil level", "Drive faster to build pressure", "Turn off the engine immediately"], correctAnswer: 1, explanation: "Stop as soon as it's safe and check the oil level. Driving with low oil pressure can cause severe engine damage.", category: "Vehicle Safety" },
  { id: 141, question: "Why should you carry a first-aid kit in your vehicle?", options: ["It is a legal requirement", "To help at the scene of an accident", "To pass your MOT", "To get cheaper insurance"], correctAnswer: 1, explanation: "While not a legal requirement in the UK, a first-aid kit can be vital for providing initial treatment at an accident scene.", category: "Vehicle Safety" },
  { id: 142, question: "What is the recommended way to demist your windscreen quickly?", options: ["Open all windows", "Use the heater on a cold setting", "Use air conditioning directed at the windscreen", "Wipe it with a cloth while driving"], correctAnswer: 2, explanation: "Air conditioning removes moisture from the air, making it the most effective way to demist your windscreen.", category: "Vehicle Safety" },
  { id: 143, question: "What is coasting and why should you avoid it?", options: ["Driving in neutral or with the clutch pressed down", "Driving uphill in a high gear", "Driving too slowly", "Using cruise control"], correctAnswer: 0, explanation: "Coasting reduces your control of the vehicle because there is no engine braking. Keep the car in the appropriate gear.", category: "Vehicle Safety" },

  // ===== SAFETY MARGINS (144–180) =====
  { id: 144, question: "What is the overall stopping distance at 30 mph?", options: ["12 metres (40 feet)", "23 metres (75 feet)", "36 metres (120 feet)", "53 metres (175 feet)"], correctAnswer: 1, explanation: "At 30 mph, the overall stopping distance is 23 metres (75 feet) — 9m thinking + 14m braking.", category: "Safety Margins" },
  { id: 145, question: "What is the overall stopping distance at 60 mph?", options: ["36 metres", "53 metres", "73 metres (240 feet)", "96 metres"], correctAnswer: 2, explanation: "At 60 mph, the overall stopping distance is 73 metres (240 feet) — 18m thinking + 55m braking.", category: "Safety Margins" },
  { id: 146, question: "What is the overall stopping distance at 70 mph?", options: ["53 metres", "73 metres", "96 metres (315 feet)", "112 metres"], correctAnswer: 2, explanation: "At 70 mph, the overall stopping distance is 96 metres (315 feet) — 21m thinking + 75m braking.", category: "Safety Margins" },
  { id: 147, question: "In wet conditions, how much more stopping distance should you allow?", options: ["The same distance", "Twice the normal distance", "Three times the normal distance", "Half the normal distance"], correctAnswer: 1, explanation: "In wet conditions, your stopping distance can double because tyres have less grip on the wet road surface.", category: "Safety Margins" },
  { id: 148, question: "In icy conditions, how much more stopping distance should you allow?", options: ["Twice the normal distance", "Five times the normal distance", "Up to ten times the normal distance", "Three times the normal distance"], correctAnswer: 2, explanation: "In icy conditions, stopping distances can be up to ten times greater than on a dry road.", category: "Safety Margins" },
  { id: 149, question: "What is the two-second rule?", options: ["Wait two seconds after a traffic light turns green", "Keep at least a two-second gap from the vehicle ahead", "Check mirrors every two seconds", "Signal two seconds before turning"], correctAnswer: 1, explanation: "The two-second rule helps you maintain a safe following distance. In wet weather, double it to four seconds.", category: "Safety Margins" },
  { id: 150, question: "What is aquaplaning?", options: ["Driving through deep water", "When tyres lose contact with the road due to water", "Washing your car", "Driving in heavy rain"], correctAnswer: 1, explanation: "Aquaplaning occurs when a layer of water builds up between the tyres and the road surface, causing loss of steering and braking.", category: "Safety Margins" },
  { id: 151, question: "What should you do if your vehicle starts to aquaplane?", options: ["Brake hard", "Steer sharply", "Ease off the accelerator and don't brake", "Accelerate out of it"], correctAnswer: 2, explanation: "Ease off the accelerator and allow the vehicle to slow down gradually. Do not brake or steer sharply.", category: "Safety Margins" },
  { id: 152, question: "What is black ice?", options: ["Ice that has been gritted", "A thin, transparent layer of ice on the road", "Dark-coloured road surface", "Ice only found at night"], correctAnswer: 1, explanation: "Black ice is a thin, transparent layer of ice on the road that is very difficult to see, making it extremely dangerous.", category: "Safety Margins" },
  { id: 153, question: "How can you tell if you might be driving on black ice?", options: ["The road looks wet but your tyres make little noise", "The road looks dry", "You can see ice crystals", "Your steering feels heavy"], correctAnswer: 0, explanation: "If the road looks wet but your tyres make very little noise, you may be driving on black ice.", category: "Safety Margins" },
  { id: 154, question: "What should you do when driving in fog?", options: ["Use full beam headlights", "Stay close to the vehicle ahead for guidance", "Use dipped headlights and reduce speed", "Drive at the normal speed limit"], correctAnswer: 2, explanation: "In fog, use dipped headlights, reduce speed, and increase your following distance. Use fog lights if visibility is below 100 metres.", category: "Safety Margins" },
  { id: 155, question: "Why should you reduce speed when driving in heavy rain?", options: ["To save fuel", "Because stopping distances increase and visibility is reduced", "Because the speed limit changes", "To avoid splashing pedestrians only"], correctAnswer: 1, explanation: "Heavy rain increases stopping distances and reduces visibility. Reduce speed to maintain control.", category: "Safety Margins" },
  { id: 156, question: "What should you do when driving through flood water?", options: ["Drive through as quickly as possible", "Drive slowly in a low gear", "Switch off the engine and coast through", "Reverse through it"], correctAnswer: 1, explanation: "Drive slowly in a low gear to avoid creating a bow wave. Test your brakes afterwards.", category: "Safety Margins" },
  { id: 157, question: "What should you do after driving through deep water?", options: ["Continue driving normally", "Test your brakes", "Switch off the engine", "Increase speed to dry the brakes"], correctAnswer: 1, explanation: "After driving through water, test your brakes gently to check they are working properly. Water can reduce braking efficiency.", category: "Safety Margins" },
  { id: 158, question: "What effect does a strong crosswind have on your vehicle?", options: ["It slows you down", "It can push you off course", "It improves fuel economy", "No effect on modern cars"], correctAnswer: 1, explanation: "Strong crosswinds can push your vehicle off course, especially on exposed roads, bridges, and when passing high-sided vehicles.", category: "Safety Margins" },
  { id: 159, question: "When is a road surface most likely to be slippery?", options: ["In heavy rain", "After a long dry spell followed by light rain", "In strong wind", "At night"], correctAnswer: 1, explanation: "After a dry spell, oil and rubber build up on the road. Light rain mixes with this, creating a very slippery surface.", category: "Safety Margins" },

  // ===== HAZARD AWARENESS (160–205) =====
  { id: 160, question: "You see a pedestrian with a white stick and red band. What does this mean?", options: ["They are deaf", "They are blind and deaf", "They are elderly", "They are a crossing patrol"], correctAnswer: 1, explanation: "A white stick with a red band indicates that the person is both deaf and blind. Give them plenty of time and space.", category: "Hazard Perception" },
  { id: 161, question: "What hazard should you be aware of when driving past a row of shops?", options: ["Shoppers stepping into the road", "Delivery vehicles stopping suddenly", "Doors opening on parked cars", "All of these"], correctAnswer: 3, explanation: "Near shops, be aware of pedestrians stepping out, delivery vehicles, car doors opening, and vehicles reversing out of spaces.", category: "Hazard Perception" },
  { id: 162, question: "You see children on the pavement ahead. What should you expect?", options: ["They will stay on the pavement", "They may run into the road", "They will use the crossing", "Nothing, they are supervised"], correctAnswer: 1, explanation: "Children are unpredictable. Always expect them to run into the road without looking.", category: "Hazard Perception" },
  { id: 163, question: "What does a flashing amber beacon on a vehicle indicate?", options: ["Emergency vehicle", "Doctor on call", "Slow-moving or stationary vehicle that could be a hazard", "Breakdown vehicle only"], correctAnswer: 2, explanation: "Amber beacons warn of a slow-moving or stationary vehicle, such as a gritting lorry, road maintenance, or breakdown vehicle.", category: "Hazard Perception" },
  { id: 164, question: "What should you be aware of when following a large vehicle?", options: ["Your view ahead is reduced", "They can stop quicker than you", "They always drive in the left lane", "Nothing different from a car"], correctAnswer: 0, explanation: "Large vehicles block your view ahead. Keep well back to increase your view and give yourself more time to react.", category: "Hazard Perception" },
  { id: 165, question: "Why are motorcyclists particularly vulnerable?", options: ["They can't go as fast as cars", "They are less visible and less protected", "They always ride in groups", "They don't have mirrors"], correctAnswer: 1, explanation: "Motorcyclists are less visible than cars and have no protection around them. Always look out for them, especially at junctions.", category: "Hazard Perception" },
  { id: 166, question: "What is a blind spot?", options: ["An area on the road with no markings", "An area you cannot see in your mirrors", "A junction with no road signs", "A parking space you can't see into"], correctAnswer: 1, explanation: "Blind spots are areas around your vehicle that cannot be seen in your mirrors. Always check by looking over your shoulder.", category: "Hazard Perception" },
  { id: 167, question: "What should you do if an ice cream van stops on the road ahead?", options: ["Overtake it quickly", "Slow down and watch for children", "Sound your horn to warn children", "Flash your headlights"], correctAnswer: 1, explanation: "Children are often excited and may run into the road without looking. Slow down and be prepared to stop.", category: "Hazard Perception" },
  { id: 168, question: "When are roads most likely to be icy?", options: ["In heavy rain", "On sheltered roads", "On exposed roads, bridges, and overpasses", "Only on motorways"], correctAnswer: 2, explanation: "Exposed roads, bridges, and overpasses freeze first because cold air circulates above and below them.", category: "Hazard Perception" },
  { id: 169, question: "You see a vehicle with a green flashing beacon. What does this mean?", options: ["Police vehicle", "Fire engine", "Doctor on an emergency call", "Recovery vehicle"], correctAnswer: 2, explanation: "A green flashing beacon indicates a doctor on an emergency call. Give way to them if safe to do so.", category: "Hazard Perception" },
  { id: 170, question: "What hazard is presented by a cyclist turning right at a roundabout?", options: ["They will be in the left lane", "They may need to move across your path", "They will signal clearly", "No particular hazard"], correctAnswer: 1, explanation: "Cyclists turning right may need to cross lanes. Be patient and give them plenty of room.", category: "Hazard Perception" },
  { id: 171, question: "What does a blue flashing light on a vehicle mean?", options: ["Breakdown service", "Slow-moving vehicle", "Emergency vehicle — give way", "Courtesy vehicle"], correctAnswer: 2, explanation: "Blue flashing lights indicate an emergency vehicle. You should give way to them safely.", category: "Hazard Perception" },
  { id: 172, question: "You are approaching a hump bridge. What hazard should you expect?", options: ["Speed cameras", "Oncoming vehicles in your lane", "Traffic lights", "Pedestrians with prams"], correctAnswer: 1, explanation: "On a hump bridge, your view ahead is very limited. Slow down — there could be oncoming vehicles, pedestrians, or cyclists.", category: "Hazard Perception" },

  // ===== VULNERABLE ROAD USERS (173–215) =====
  { id: 173, question: "What does this sign mean: a triangle with a bicycle?", options: ["No cycling allowed", "Cycle lane ahead", "Warning: cyclists ahead", "Bicycle parking"], correctAnswer: 2, explanation: "A triangular warning sign showing a bicycle warns you to watch out for cyclists ahead.", category: "Vulnerable Road Users" },
  { id: 174, question: "Why should you give extra room to cyclists in windy conditions?", options: ["They ride faster in wind", "Wind may blow them into your path", "They need space to signal", "No extra room is needed"], correctAnswer: 1, explanation: "Strong winds can blow cyclists off course. Give them extra room in case they wobble or swerve.", category: "Vulnerable Road Users" },
  { id: 175, question: "What should you do when overtaking a cyclist?", options: ["Pass as close as possible to save time", "Give them at least 1.5 metres of space", "Sound your horn before passing", "Overtake only on dual carriageways"], correctAnswer: 1, explanation: "Give cyclists at least 1.5 metres of space when overtaking. More space at higher speeds.", category: "Vulnerable Road Users" },
  { id: 176, question: "What is the main danger of driving near schools at drop-off time?", options: ["Traffic jams", "Parked cars blocking your view", "Children running across the road unexpectedly", "All of these"], correctAnswer: 3, explanation: "School zones at drop-off/pick-up times present multiple hazards including unpredictable children, parked cars, and congestion.", category: "Vulnerable Road Users" },
  { id: 177, question: "How should you approach a person in a powered wheelchair on the road?", options: ["Sound your horn to alert them", "Treat them as a pedestrian and give plenty of room", "Overtake quickly", "Flash your headlights"], correctAnswer: 1, explanation: "Treat powered wheelchair users as you would pedestrians. Be patient and give them plenty of room.", category: "Vulnerable Road Users" },
  { id: 178, question: "What does a school crossing patrol sign look like?", options: ["A red circle", "A blue square", "Two amber flashing lights", "A triangular warning sign with children"], correctAnswer: 2, explanation: "School crossing patrols are indicated by amber flashing lights. You must stop when the patrol holds up their sign.", category: "Vulnerable Road Users" },
  { id: 179, question: "When should you be especially careful of elderly pedestrians?", options: ["Only at crossings", "Near shops and bus stops", "At all times — they may misjudge speed and distance", "Only at night"], correctAnswer: 2, explanation: "Elderly pedestrians may have difficulty judging speed and distance, and may move slowly. Be patient and give them time.", category: "Vulnerable Road Users" },
  { id: 180, question: "Why are young children particularly at risk near roads?", options: ["They are small and hard to see", "They may not understand traffic dangers", "They may act unpredictably", "All of these reasons"], correctAnswer: 3, explanation: "Young children are small, unpredictable, and may not understand traffic dangers. Always be extra cautious around them.", category: "Vulnerable Road Users" },
  { id: 181, question: "What should you do when you see a guide dog with its owner?", options: ["Sound your horn to let them know you're there", "Drive past slowly and give them plenty of room", "Flash your headlights", "Drive normally"], correctAnswer: 1, explanation: "Drive slowly and quietly past guide dog users. Avoid sounding your horn as this could disorient the dog.", category: "Vulnerable Road Users" },
  { id: 182, question: "How should you treat a horse-drawn vehicle on the road?", options: ["The same as any other slow vehicle", "Give it as much room as a car", "Give extra room and pass slowly", "Overtake it as quickly as possible"], correctAnswer: 2, explanation: "Horses can be frightened by vehicles. Pass slowly with plenty of room, and avoid sudden movements or loud noises.", category: "Vulnerable Road Users" },
  { id: 183, question: "When must you stop for a school crossing patrol?", options: ["Only when children are crossing", "Whenever the patrol displays their sign", "Only during term time", "Only if the road is busy"], correctAnswer: 1, explanation: "You MUST stop when a school crossing patrol displays their sign, regardless of whether anyone is crossing.", category: "Vulnerable Road Users" },

  // ===== MOTORWAY RULES (184–225) =====
  { id: 184, question: "What is the minimum age to drive on a motorway?", options: ["16", "17", "18", "21"], correctAnswer: 1, explanation: "You must be at least 17 and hold a valid full driving licence (or provisional with an approved instructor) to drive on a motorway.", category: "Motorway Rules" },
  { id: 185, question: "When may you stop on the hard shoulder of a motorway?", options: ["To check your map", "In an emergency or breakdown", "To make a phone call", "When you feel tired"], correctAnswer: 1, explanation: "The hard shoulder is for emergencies only. Do not stop to rest, make calls, or check directions.", category: "Motorway Rules" },
  { id: 186, question: "What colour are motorway signs?", options: ["Green", "Blue", "White", "Brown"], correctAnswer: 1, explanation: "Motorway signs have a blue background. Primary route signs are green and non-primary route signs are white.", category: "Motorway Rules" },
  { id: 187, question: "What is the national speed limit on a motorway for cars?", options: ["50 mph", "60 mph", "70 mph", "80 mph"], correctAnswer: 2, explanation: "The national speed limit for cars on motorways is 70 mph unless signs show a lower limit.", category: "Motorway Rules" },
  { id: 188, question: "How should you join a motorway from a slip road?", options: ["Stop at the end of the slip road", "Match the speed of traffic on the motorway", "Always drive onto the motorway at 30 mph", "Force your way into traffic"], correctAnswer: 1, explanation: "Use the slip road to build up speed to match motorway traffic. Merge into a safe gap without forcing other drivers to slow down.", category: "Motorway Rules" },
  { id: 189, question: "What should you do if you miss your exit on a motorway?", options: ["Reverse back to the exit", "Stop on the hard shoulder", "Continue to the next exit", "Do a U-turn"], correctAnswer: 2, explanation: "Never reverse, stop, or do a U-turn on a motorway. Continue to the next exit and find an alternative route.", category: "Motorway Rules" },
  { id: 190, question: "What do red flashing lights above a motorway lane mean?", options: ["Lane is open but proceed with caution", "You must not go beyond the signal in that lane", "Speed limit ahead", "Accident cleared"], correctAnswer: 1, explanation: "Red flashing lights above a lane mean you MUST NOT use that lane. It may be closed due to an incident.", category: "Motorway Rules" },
  { id: 191, question: "Who is NOT allowed on a motorway?", options: ["Cars towing caravans", "Motorcycles over 50cc", "Learner drivers on their own", "Vehicles with trailers"], correctAnswer: 2, explanation: "Learner drivers not accompanied by an approved instructor, cyclists, pedestrians, and some slow vehicles are banned from motorways.", category: "Motorway Rules" },
  { id: 192, question: "What is a smart motorway?", options: ["A motorway with electric vehicle charging", "A motorway where the hard shoulder can be used as a running lane", "A motorway with no speed limit", "A motorway with toll booths"], correctAnswer: 1, explanation: "Smart motorways use technology to manage traffic flow. The hard shoulder may be used as a running lane and variable speed limits are displayed.", category: "Motorway Rules" },
  { id: 193, question: "What should you do if your vehicle breaks down on a smart motorway with no hard shoulder?", options: ["Stop in the left lane", "Try to reach an Emergency Refuge Area", "Stop in any lane and put hazards on", "Walk to the nearest phone"], correctAnswer: 1, explanation: "If possible, reach an Emergency Refuge Area (ERA). If you can't, stop as far left as possible with hazards on and call 999.", category: "Motorway Rules" },
  { id: 194, question: "What does an amber flashing light on a motorway signal mean?", options: ["Change lane", "A hazard ahead — adjust your speed", "Lane closed ahead", "All clear"], correctAnswer: 1, explanation: "Amber flashing lights on motorway signals warn of a hazard ahead. Adjust your speed and look for further signals.", category: "Motorway Rules" },
  { id: 195, question: "Where would you find a crawler lane on a motorway?", options: ["At every junction", "On steep uphill gradients", "On the approach to services", "Near motorway interchanges"], correctAnswer: 1, explanation: "Crawler lanes are provided on steep uphill sections for slow-moving vehicles so they don't hold up other traffic.", category: "Motorway Rules" },
  { id: 196, question: "What should you do before leaving the motorway?", options: ["Move into the left lane well before your exit", "Stay in the right lane until the exit", "Speed up to overtake before the exit", "Brake sharply at the slip road"], correctAnswer: 0, explanation: "Move into the left lane well before your exit. Use the slip road to reduce speed, not the main carriageway.", category: "Motorway Rules" },
  { id: 197, question: "What is the purpose of chevron markings on a motorway?", options: ["To mark parking areas", "To help you keep a safe following distance", "To indicate a speed limit change", "To mark the edge of the carriageway"], correctAnswer: 1, explanation: "Chevron markings help you maintain a safe distance. Keep at least two chevrons between you and the vehicle ahead.", category: "Motorway Rules" },
  { id: 198, question: "What should you do if fog closes in while driving on a motorway?", options: ["Put on full beam headlights", "Pull onto the hard shoulder and wait", "Slow down, use dipped headlights and fog lights", "Maintain your speed and follow the vehicle ahead"], correctAnswer: 2, explanation: "Slow down, use dipped headlights and fog lights if visibility is below 100m. Increase your following distance.", category: "Motorway Rules" },
  { id: 199, question: "What lane should you normally drive in on a three-lane motorway?", options: ["The middle lane", "The left lane", "Any lane you prefer", "The right lane"], correctAnswer: 1, explanation: "Drive in the left lane unless overtaking. The middle and right lanes are for overtaking only.", category: "Motorway Rules" },

  // ===== RULES OF THE ROAD (200–245) =====
  { id: 200, question: "What shape is a STOP sign?", options: ["Circular", "Triangular", "Octagonal", "Square"], correctAnswer: 2, explanation: "The STOP sign is the only octagonal (8-sided) road sign. You must stop completely at the line.", category: "Traffic Signs" },
  { id: 201, question: "What does a broken white line in the centre of the road mean?", options: ["No overtaking", "You may cross it if safe to do so", "Bus lane", "Edge of the road"], correctAnswer: 1, explanation: "A broken white centre line can be crossed for overtaking if it is safe to do so.", category: "Traffic Signs" },
  { id: 202, question: "What do double yellow lines at the edge of a road mean?", options: ["Parking allowed for 30 minutes", "No waiting at any time", "Parking allowed at night only", "Loading zone"], correctAnswer: 1, explanation: "Double yellow lines mean no waiting at any time. You may stop briefly to set down or pick up passengers.", category: "Traffic Signs" },
  { id: 203, question: "What does a single yellow line mean?", options: ["No parking at any time", "No waiting during the times shown on nearby signs", "Parking allowed", "Bus stop"], correctAnswer: 1, explanation: "A single yellow line means no waiting during the times shown on nearby plates or signs.", category: "Traffic Signs" },
  { id: 204, question: "When can you drive in a bus lane?", options: ["Never", "At any time if the road is quiet", "During the times shown on the signs, only permitted vehicles can use it", "Whenever there are no buses"], correctAnswer: 2, explanation: "Bus lanes have operating times shown on signs. Outside those times, other vehicles may use the lane.", category: "Traffic Signs" },
  { id: 205, question: "What does a red route (red line at the road edge) mean?", options: ["Parking is free", "No stopping at any time (double red) or during certain times (single red)", "Bus route only", "One-way street"], correctAnswer: 1, explanation: "Red routes prohibit stopping. Double red lines mean no stopping at any time; single red lines show restricted times.", category: "Traffic Signs" },
  { id: 206, question: "What is the speed limit on a single carriageway for a car towing a trailer?", options: ["60 mph", "50 mph", "40 mph", "70 mph"], correctAnswer: 1, explanation: "Cars towing trailers are limited to 50 mph on single carriageways and 60 mph on dual carriageways and motorways.", category: "Speed Limits" },
  { id: 207, question: "What does a circular sign with a blue background and white arrow mean?", options: ["Ahead only (mandatory direction)", "No entry", "One-way street", "Give way"], correctAnswer: 0, explanation: "A circular blue sign with a white arrow gives a mandatory instruction — in this case, 'ahead only'.", category: "Traffic Signs" },
  { id: 208, question: "What do zigzag white lines at a pedestrian crossing mean?", options: ["Parking allowed for disabled drivers", "No parking or overtaking in this area", "School zone", "Speed bumps ahead"], correctAnswer: 1, explanation: "Zigzag lines at crossings mean you must not park or overtake in this area as it would block the view for pedestrians and drivers.", category: "Traffic Signs" },
  { id: 209, question: "On a roundabout, who has priority?", options: ["Traffic approaching from the right", "Traffic already on the roundabout", "Traffic approaching from the left", "The largest vehicle"], correctAnswer: 1, explanation: "Give way to traffic already on the roundabout from your right. Traffic already on the roundabout has priority.", category: "Roundabouts" },
  { id: 210, question: "When can you use the right-hand lane of a dual carriageway?", options: ["For normal driving", "Only for overtaking", "Only when turning right or overtaking", "At any time"], correctAnswer: 2, explanation: "Use the right-hand lane only for overtaking or when turning right. Return to the left lane after overtaking.", category: "Lane Discipline" },
  { id: 211, question: "What is the rule at a box junction (yellow criss-cross lines)?", options: ["Stop in the box if traffic is moving slowly", "You may enter only if your exit is clear", "Give way to traffic from the right", "No stopping at any time"], correctAnswer: 1, explanation: "Do not enter a box junction unless your exit is clear. The exception is when turning right and only oncoming traffic is blocking you.", category: "Traffic Signs" },
  { id: 212, question: "What does a national speed limit sign look like?", options: ["A white circle with a number", "A white circle with a black diagonal line", "A blue circle", "A red circle"], correctAnswer: 1, explanation: "The national speed limit sign is a white circle with a black diagonal line through it.", category: "Speed Limits" },
  { id: 213, question: "What does a green traffic light mean?", options: ["Go without checking", "Proceed if the way is clear", "Speed up", "Pedestrians are crossing"], correctAnswer: 1, explanation: "A green light means you may go if the way is clear. Always check the junction is clear before proceeding.", category: "Traffic Signs" },
  { id: 214, question: "What must you do at a red traffic light?", options: ["Proceed with caution", "Stop and wait behind the stop line", "Stop only if there is traffic", "Slow down and proceed if clear"], correctAnswer: 1, explanation: "You MUST stop at a red traffic light and wait behind the stop line until the light changes to green.", category: "Traffic Signs" },
  { id: 215, question: "What does a flashing green arrow at traffic lights mean?", options: ["Proceed with caution in the direction of the arrow", "Stop and wait", "You may proceed in the direction of the arrow", "Emergency vehicle approaching"], correctAnswer: 2, explanation: "A green filter arrow means you may proceed in the direction shown, regardless of other lights.", category: "Traffic Signs" },

  // ===== ROAD AND TRAFFIC SIGNS (216–260) =====
  { id: 216, question: "What does a sign showing 'End of motorway restrictions' look like?", options: ["Blue sign with white line through it", "White sign with black diagonal stripes", "Green sign with white text", "Red circle with diagonal line"], correctAnswer: 0, explanation: "End of motorway restrictions is shown on a blue sign with markings crossed through.", category: "Traffic Signs" },
  { id: 217, question: "What does a circular sign with a red border and a bicycle mean?", options: ["Cycle route ahead", "No cycling", "Cycle lane", "Shared path"], correctAnswer: 1, explanation: "A circular sign with a red border means prohibition. With a bicycle symbol, it means no cycling.", category: "Traffic Signs" },
  { id: 218, question: "What information does a green road sign give?", options: ["Motorway information", "Primary route directions", "Tourist information", "Speed limit changes"], correctAnswer: 1, explanation: "Green road signs indicate primary route directions. Motorway signs are blue and tourist signs are brown.", category: "Traffic Signs" },
  { id: 219, question: "What does a 'No U-turn' sign look like?", options: ["Circular with red border showing U-turn arrow crossed out", "Triangle with U-turn symbol", "Blue circle with U-turn arrow", "Square white sign"], correctAnswer: 0, explanation: "The 'No U-turn' sign is circular with a red border, showing a U-turn arrow with a red line through it.", category: "Traffic Signs" },
  { id: 220, question: "What does a triangular sign with an exclamation mark mean?", options: ["No entry", "Give way", "Other danger — a plate beneath will explain", "Speed camera ahead"], correctAnswer: 2, explanation: "A triangle with an exclamation mark warns of a danger not covered by other signs. A plate below explains the hazard.", category: "Traffic Signs" },
  { id: 221, question: "What does a speed limit sign in a red circle mean?", options: ["Recommended speed", "Maximum speed allowed", "Minimum speed", "Average speed"], correctAnswer: 1, explanation: "A speed limit in a red circle is a mandatory maximum speed. You must not exceed this limit.", category: "Speed Limits" },
  { id: 222, question: "What does a blue circular sign with a number mean?", options: ["Maximum speed", "Minimum speed", "Recommended speed", "Speed camera threshold"], correctAnswer: 1, explanation: "A blue circular sign with a number shows the minimum speed. You must not drive slower than the speed shown.", category: "Speed Limits" },
  { id: 223, question: "What is the purpose of countdown markers on a motorway?", options: ["To show distance to services", "To warn of the approach to a motorway exit", "To indicate speed limit changes", "To mark emergency phone locations"], correctAnswer: 1, explanation: "Countdown markers (3 bars, 2 bars, 1 bar) help you prepare for a motorway exit by showing the distance to the exit.", category: "Traffic Signs" },
  { id: 224, question: "What does a white circular sign with a red border and no symbol mean?", options: ["No vehicles allowed", "National speed limit applies", "No parking", "Road closed"], correctAnswer: 0, explanation: "A white circle with a red border and no symbol means no vehicles (except bicycles pushed by hand).", category: "Traffic Signs" },
  { id: 225, question: "What does a 'clearway' sign mean?", options: ["The road is clear of hazards", "No stopping on the main carriageway", "You have priority", "Free parking available"], correctAnswer: 1, explanation: "A clearway sign means you must not stop on the main carriageway except in an emergency.", category: "Traffic Signs" },

  // ===== DOCUMENTS (226–250) =====
  { id: 226, question: "What is the minimum age for driving a car on public roads?", options: ["15", "16", "17", "18"], correctAnswer: 2, explanation: "You must be at least 17 years old to drive a car on public roads in the UK.", category: "Documents" },
  { id: 227, question: "How long is a provisional driving licence valid for?", options: ["5 years", "10 years", "Until you pass your test", "Until age 70"], correctAnswer: 1, explanation: "A provisional driving licence is valid for 10 years and must be renewed.", category: "Documents" },
  { id: 228, question: "When must you notify the DVLA?", options: ["Only when selling a car", "When your health or personal details change", "Only when changing address", "Only when your licence expires"], correctAnswer: 1, explanation: "You must notify the DVLA of changes to your name, address, or any medical condition that may affect your driving.", category: "Documents" },
  { id: 229, question: "How old must a car be before it needs its first MOT?", options: ["1 year", "2 years", "3 years", "5 years"], correctAnswer: 2, explanation: "A new car needs its first MOT when it is 3 years old. After that, it must be tested every year.", category: "Documents" },
  { id: 230, question: "What is the maximum fine for driving without insurance?", options: ["£100", "£300", "£1,000", "Unlimited"], correctAnswer: 3, explanation: "Driving without insurance can lead to an unlimited fine, 6-8 penalty points, and your vehicle could be seized.", category: "Documents" },
  { id: 231, question: "What document must you have to drive on public roads?", options: ["A passport", "A valid driving licence", "An MOT certificate only", "A birth certificate"], correctAnswer: 1, explanation: "You must have a valid driving licence to drive on public roads. You also need insurance and, if required, a valid MOT.", category: "Documents" },
  { id: 232, question: "When must you renew your photo driving licence?", options: ["Every 5 years", "Every 10 years", "Every 15 years", "Never"], correctAnswer: 1, explanation: "The photo on your driving licence must be renewed every 10 years to keep it up to date.", category: "Documents" },
  { id: 233, question: "What happens if you accumulate 12 or more penalty points within 3 years?", options: ["A warning letter", "A fine only", "Disqualification from driving", "Points are automatically removed"], correctAnswer: 2, explanation: "If you get 12 or more points within 3 years, you will usually be disqualified from driving for a minimum of 6 months.", category: "Documents" },
  { id: 234, question: "New drivers who accumulate 6 or more points within 2 years of passing their test face what?", options: ["A warning", "Automatic licence revocation", "A fine only", "Mandatory retraining"], correctAnswer: 1, explanation: "New drivers (within 2 years of passing) who get 6 or more points have their licence revoked and must retake both theory and practical tests.", category: "Documents" },
  { id: 235, question: "What is SORN?", options: ["A type of insurance", "Statutory Off Road Notification", "A type of MOT", "Speed On Road Notification"], correctAnswer: 1, explanation: "SORN (Statutory Off Road Notification) declares that your vehicle is not being used or kept on public roads.", category: "Documents" },

  // ===== INCIDENTS, ACCIDENTS AND EMERGENCIES (236–275) =====
  { id: 236, question: "What is the first thing you should do at the scene of an accident where someone is injured?", options: ["Move the injured person", "Call your insurance company", "Make the scene safe and call emergency services", "Take photographs"], correctAnswer: 2, explanation: "First make the area safe (hazard lights, warning triangle), then call 999/112 for emergency services.", category: "Accidents" },
  { id: 237, question: "What should you NOT do when helping a casualty who is bleeding heavily?", options: ["Apply pressure to the wound", "Raise the injured limb", "Remove objects embedded in the wound", "Keep the person warm"], correctAnswer: 2, explanation: "Do NOT remove objects embedded in a wound as they may be stopping more severe bleeding. Apply pressure around the object.", category: "Accidents" },
  { id: 238, question: "What should you do if a casualty is unconscious but breathing?", options: ["Give them water", "Place them in the recovery position", "Leave them on their back", "Shake them to wake them up"], correctAnswer: 1, explanation: "Place an unconscious but breathing casualty in the recovery position to keep their airway clear.", category: "Accidents" },
  { id: 239, question: "How should you deal with a vehicle fire?", options: ["Open the bonnet to check", "Get everyone out of the vehicle and call 999", "Try to extinguish it with a coat", "Drive to the nearest garage"], correctAnswer: 1, explanation: "Get all occupants out of and away from the vehicle immediately. Call 999. Do not open the bonnet.", category: "Accidents" },
  { id: 240, question: "What should you do if you break down on a railway level crossing?", options: ["Stay in the car and call for help", "Get everyone out and clear of the crossing, then call the signal operator", "Push the car off the crossing", "Wait for the next train to pass"], correctAnswer: 1, explanation: "Get everyone out and well clear of the crossing immediately. Use the railway phone to contact the signal operator.", category: "Accidents" },
  { id: 241, question: "What number should you call for non-emergency police matters?", options: ["999", "112", "101", "111"], correctAnswer: 2, explanation: "Call 101 for non-emergency police matters. Use 999 or 112 for emergencies only.", category: "Accidents" },
  { id: 242, question: "What is the recovery position used for?", options: ["To treat broken bones", "To keep an unconscious person's airway open", "To treat burns", "To stop bleeding"], correctAnswer: 1, explanation: "The recovery position keeps the airway clear and allows fluids to drain from the mouth, preventing choking.", category: "Accidents" },
  { id: 243, question: "At an accident scene, what should you do to reduce the risk of fire?", options: ["Pour water on the engine", "Switch off the engine and don't smoke", "Cover the vehicle with a blanket", "Spray air freshener"], correctAnswer: 1, explanation: "Switch off the engine to reduce fire risk. Do not smoke near the vehicles and be aware of fuel spillage.", category: "Accidents" },
  { id: 244, question: "What is the purpose of a warning triangle?", options: ["To mark a parking space", "To alert other road users to an obstruction ahead", "To indicate a diversion", "To mark a construction zone"], correctAnswer: 1, explanation: "Place a warning triangle at least 45 metres behind your vehicle on the same side of the road to warn approaching traffic.", category: "Accidents" },
  { id: 245, question: "If a person has a burn, what should you do?", options: ["Apply butter to the burn", "Cool the burn with cold water for at least 20 minutes", "Pop any blisters", "Cover it with a fluffy dressing"], correctAnswer: 1, explanation: "Cool the burn with cold running water for at least 20 minutes. Do not apply creams, butter, or pop blisters.", category: "Accidents" },

  // ===== VEHICLE HANDLING (246–290) =====
  { id: 246, question: "When should you use your vehicle's horn?", options: ["To greet someone you know", "To alert other road users of your presence", "To show anger at another driver", "To speed up traffic"], correctAnswer: 1, explanation: "Use your horn only to warn other road users of your presence. Never use it aggressively or in a built-up area at night (11:30pm–7am) while stationary.", category: "Signalling" },
  { id: 247, question: "What should you do when driving on an icy road?", options: ["Brake firmly", "Drive at a slow speed in the highest gear possible", "Use the lowest gear at all times", "Drive normally"], correctAnswer: 1, explanation: "In icy conditions, drive slowly in a higher gear to reduce wheel spin. Brake gently and steer smoothly.", category: "Vehicle Handling" },
  { id: 248, question: "What is engine braking?", options: ["Using the parking brake while driving", "Slowing down by changing to a lower gear", "Pressing the brake pedal firmly", "Switching off the engine"], correctAnswer: 1, explanation: "Engine braking is using lower gears to slow the vehicle. It helps maintain control on hills and reduces brake wear.", category: "Vehicle Handling" },
  { id: 249, question: "How should you drive through a bend?", options: ["Accelerate through the bend", "Brake hard in the bend", "Slow down before the bend, accelerate gently through it", "Maintain the same speed throughout"], correctAnswer: 2, explanation: "Reduce speed before entering a bend. Accelerate gently once you can see the road ahead clearing.", category: "Vehicle Handling" },
  { id: 250, question: "What should you do if your vehicle starts to skid?", options: ["Brake harder", "Steer into the skid and ease off the accelerator", "Steer in the opposite direction", "Accelerate"], correctAnswer: 1, explanation: "Steer into the direction of the skid (where you want the front to go) and ease off the accelerator. Don't brake harshly.", category: "Vehicle Handling" },
  { id: 251, question: "When driving downhill, what should you do?", options: ["Coast in neutral", "Use a lower gear and brake gently", "Use the handbrake to slow down", "Stay in the highest gear"], correctAnswer: 1, explanation: "Use a lower gear to help control your speed going downhill. This reduces the need for constant braking.", category: "Vehicle Handling" },
  { id: 252, question: "What gear should you use when driving uphill?", options: ["The highest gear possible", "A lower gear to maintain power", "Neutral", "Reverse"], correctAnswer: 1, explanation: "Use a lower gear when going uphill to maintain engine power and avoid stalling.", category: "Vehicle Handling" },
  { id: 253, question: "What is cadence braking?", options: ["Braking while turning", "Rapid on-off brake application in vehicles without ABS", "Using engine braking only", "Braking with one foot"], correctAnswer: 1, explanation: "Cadence braking involves rapidly pressing and releasing the brake pedal to prevent wheel lock-up in vehicles without ABS.", category: "Vehicle Handling" },
  { id: 254, question: "How does carrying a heavy load affect your vehicle?", options: ["It improves stability", "It increases braking distance and affects handling", "It has no effect", "It improves fuel economy"], correctAnswer: 1, explanation: "A heavy load increases braking distance, changes the centre of gravity, and can affect steering and handling.", category: "Vehicle Handling" },
  { id: 255, question: "What should you do if a front tyre blows out while driving?", options: ["Brake sharply", "Hold the steering wheel firmly and slow down gradually", "Accelerate briefly", "Take your hands off the wheel"], correctAnswer: 1, explanation: "Hold the steering wheel firmly, take your foot off the accelerator, and slow down gradually. Don't brake suddenly.", category: "Vehicle Handling" },
  { id: 256, question: "When should you use the parking brake?", options: ["To slow down on a motorway", "When parked or stopped on a hill", "While reversing", "At all traffic lights"], correctAnswer: 1, explanation: "Use the parking brake when you park your vehicle, especially on hills, to prevent it from rolling.", category: "Vehicle Handling" },
  { id: 257, question: "What is the correct technique for an emergency stop?", options: ["Brake and steer at the same time", "Apply maximum braking force quickly and firmly", "Pump the brakes rapidly", "Turn the steering wheel first"], correctAnswer: 1, explanation: "In an emergency stop, apply the brakes firmly and quickly. In a car with ABS, press the pedal down hard and hold it.", category: "Vehicle Handling" },
  { id: 258, question: "How should you pass through a ford (shallow river crossing)?", options: ["At high speed to avoid getting stuck", "Slowly in a low gear", "In neutral", "Only in reverse"], correctAnswer: 1, explanation: "Drive through a ford slowly in a low gear. Check the depth first and test your brakes after crossing.", category: "Vehicle Handling" },
  { id: 259, question: "What effect does towing a trailer have on your fuel consumption?", options: ["No effect", "Reduces it", "Increases it significantly", "Only affects diesel vehicles"], correctAnswer: 2, explanation: "Towing a trailer significantly increases fuel consumption due to added weight and wind resistance.", category: "Vehicle Handling" },
  { id: 260, question: "What should you do when driving on a wet, muddy road?", options: ["Accelerate to maintain momentum", "Drive slowly and avoid sudden steering or braking", "Use full beam headlights", "Drive in the middle of the road"], correctAnswer: 1, explanation: "On slippery surfaces, drive slowly with smooth steering and braking inputs to maintain grip.", category: "Vehicle Handling" },

  // ===== OTHER TYPES OF VEHICLE (261–295) =====
  { id: 261, question: "What should you be aware of when driving behind a large lorry?", options: ["They have excellent visibility", "Their spray can reduce your visibility in wet weather", "They can stop very quickly", "Nothing different from a car"], correctAnswer: 1, explanation: "Large vehicles throw up a lot of spray in wet conditions, severely reducing your visibility. Keep well back.", category: "Other Vehicles" },
  { id: 262, question: "Why might a long vehicle need to straddle lanes at a roundabout?", options: ["The driver is lost", "To make the turn without mounting the kerb", "To block other traffic", "Long vehicles don't use roundabouts"], correctAnswer: 1, explanation: "Long vehicles may need to use more than one lane to make turns. Give them plenty of room and don't try to overtake.", category: "Other Vehicles" },
  { id: 263, question: "What does a vehicle with flashing amber beacons indicate?", options: ["Emergency vehicle", "Slow-moving vehicle", "Vehicle carrying hazardous materials", "Breakdown service only"], correctAnswer: 1, explanation: "Amber flashing beacons indicate a slow-moving vehicle, such as a gritting lorry, tractor, or road maintenance vehicle.", category: "Other Vehicles" },
  { id: 264, question: "When following a bus that signals to pull away from a bus stop, what should you do?", options: ["Speed up to pass it", "Give way to it if safe to do so", "Sound your horn", "Flash your headlights"], correctAnswer: 1, explanation: "If safe to do so, give way to buses pulling away from bus stops. They are providing a public service.", category: "Other Vehicles" },
  { id: 265, question: "What should you do when approaching a tram?", options: ["Treat it like any other vehicle", "Be aware that trams cannot steer to avoid you", "Overtake it on the right", "Sound your horn"], correctAnswer: 1, explanation: "Trams run on fixed tracks and cannot steer to avoid you. Give them priority and watch for passengers.", category: "Other Vehicles" },
  { id: 266, question: "What orange diamond-shaped sign on a lorry indicates?", options: ["Oversized load", "The vehicle is carrying hazardous goods", "Slow vehicle", "Foreign vehicle"], correctAnswer: 1, explanation: "An orange diamond-shaped hazard warning plate indicates the vehicle is carrying dangerous or hazardous goods.", category: "Other Vehicles" },
  { id: 267, question: "Why should you be careful when overtaking a cyclist just before a left turn?", options: ["Cyclists always turn left", "You might cut across their path", "Cyclists cannot signal", "No need to be careful"], correctAnswer: 1, explanation: "If you overtake a cyclist and then turn left, you risk cutting across their path. Let them go first or wait behind them.", category: "Other Vehicles" },
  { id: 268, question: "What should you do if you are behind a tractor on a narrow country road?", options: ["Overtake immediately", "Sound your horn and flash your lights", "Stay well back and wait for a safe place to pass", "Drive very close behind to be seen"], correctAnswer: 2, explanation: "Stay well back from a tractor and wait for a safe, clear place to overtake. Never overtake on a bend or near a junction.", category: "Other Vehicles" },

  // ===== ENVIRONMENTAL ISSUES (269–310) =====
  { id: 269, question: "How can eco-driving save fuel?", options: ["By driving in low gears", "By accelerating sharply", "By planning ahead, driving smoothly, and maintaining steady speeds", "By driving with windows open"], correctAnswer: 2, explanation: "Eco-driving involves smooth acceleration, reading the road ahead, maintaining steady speeds, and avoiding unnecessary braking.", category: "Environmental Issues" },
  { id: 270, question: "What is the effect of roof racks on fuel consumption?", options: ["No effect", "They reduce consumption", "They increase fuel consumption due to wind resistance", "They improve aerodynamics"], correctAnswer: 2, explanation: "Roof racks increase wind resistance, which increases fuel consumption. Remove them when not in use.", category: "Environmental Issues" },
  { id: 271, question: "How does air conditioning affect fuel consumption?", options: ["It reduces it", "It increases it", "No effect", "Only affects diesel vehicles"], correctAnswer: 1, explanation: "Air conditioning puts extra load on the engine, increasing fuel consumption. Use it only when necessary.", category: "Environmental Issues" },
  { id: 272, question: "What should you do to reduce pollution when stuck in a traffic jam?", options: ["Rev the engine to keep it warm", "Switch off the engine if stationary for a long time", "Use air conditioning", "Keep the windows closed"], correctAnswer: 1, explanation: "Switch off your engine if you're likely to be stationary for more than a minute. This reduces emissions and saves fuel.", category: "Environmental Issues" },
  { id: 273, question: "What is the benefit of regular vehicle servicing for the environment?", options: ["It makes the car look better", "A well-maintained engine runs more efficiently and produces fewer emissions", "It has no environmental benefit", "It only benefits the engine"], correctAnswer: 1, explanation: "Regular servicing keeps your engine running efficiently, which reduces harmful emissions and improves fuel economy.", category: "Environmental Issues" },
  { id: 274, question: "How does under-inflated tyres affect fuel consumption?", options: ["No effect", "Reduces it", "Increases it due to increased rolling resistance", "Only affects braking"], correctAnswer: 2, explanation: "Under-inflated tyres have greater rolling resistance, which means the engine has to work harder, using more fuel.", category: "Environmental Issues" },
  { id: 275, question: "What speed is generally most fuel-efficient for most cars?", options: ["30 mph", "45–50 mph", "70 mph", "80 mph"], correctAnswer: 1, explanation: "Most cars are most fuel-efficient at around 45–50 mph in their highest gear. Fuel consumption rises sharply above 60 mph.", category: "Environmental Issues" },
  { id: 276, question: "What is the purpose of an MOT emissions test?", options: ["To check the exhaust colour", "To ensure the vehicle's exhaust emissions are within legal limits", "To test the engine power", "To check the fuel type"], correctAnswer: 1, explanation: "The MOT emissions test checks that your vehicle's exhaust emissions are within legal limits to help reduce air pollution.", category: "Environmental Issues" },
  { id: 277, question: "How can you reduce your vehicle's environmental impact?", options: ["Drive faster to spend less time on the road", "Walk or cycle for short journeys", "Always drive alone", "Use the highest gear from standstill"], correctAnswer: 1, explanation: "Walking, cycling, or using public transport for short journeys significantly reduces your environmental impact.", category: "Environmental Issues" },
  { id: 278, question: "What happens to fuel consumption at higher speeds?", options: ["It decreases", "It stays the same", "It increases significantly", "It depends on the colour of the car"], correctAnswer: 2, explanation: "Fuel consumption increases significantly at higher speeds due to greater air resistance. Driving at 70 mph uses up to 30% more fuel than at 50 mph.", category: "Environmental Issues" },

  // ===== ADDITIONAL DRINK DRIVING & DRUGS (279–310) =====
  { id: 279, question: "What is the penalty for causing death by dangerous driving while under the influence?", options: ["6 months imprisonment", "2 years imprisonment", "Up to 14 years imprisonment", "Community service"], correctAnswer: 2, explanation: "Causing death by dangerous driving or while under the influence of drink or drugs can lead to up to 14 years imprisonment.", category: "Drink Driving" },
  { id: 280, question: "Can prescribed medication affect your driving?", options: ["No, it is prescribed by a doctor", "Yes, some medicines can cause drowsiness or impaired judgement", "Only if you take more than prescribed", "Never"], correctAnswer: 1, explanation: "Many prescribed medicines can affect your driving. Always check the label and ask your doctor or pharmacist.", category: "Drink Driving" },
  { id: 281, question: "What should you do if you need to drive and are taking medication?", options: ["Drive anyway", "Check with your doctor or pharmacist if it's safe to drive", "Only drive short distances", "Take less than prescribed"], correctAnswer: 1, explanation: "Always check with your doctor or pharmacist whether your medication could affect your ability to drive safely.", category: "Drink Driving" },
  { id: 282, question: "How can illegal drugs affect your driving?", options: ["They improve concentration", "They can severely impair judgement, reaction times, and coordination", "They have no effect", "Only if taken in large doses"], correctAnswer: 1, explanation: "Illegal drugs can severely impair your ability to drive. It is an offence to drive while impaired by drugs.", category: "Drink Driving" },
  { id: 283, question: "Is it illegal to drive with any amount of illegal drugs in your system?", options: ["No, small amounts are fine", "Yes, there is a zero-tolerance approach for most illegal drugs", "Only if you appear impaired", "Only for Class A drugs"], correctAnswer: 1, explanation: "The UK has a near-zero tolerance approach for illegal drugs while driving. Even small amounts can lead to prosecution.", category: "Drink Driving" },

  // ===== ADDITIONAL OVERTAKING & JUNCTIONS (284–320) =====
  { id: 284, question: "What should you check before overtaking on a two-lane road?", options: ["Only the road ahead is clear", "Mirrors, the road ahead, and that no one is overtaking you", "Just the left mirror", "Only that the vehicle ahead is slow"], correctAnswer: 1, explanation: "Before overtaking, check mirrors, ensure the road ahead is clear, check no one behind is already overtaking you, and signal.", category: "Overtaking" },
  { id: 285, question: "When should you NOT overtake on the left?", options: ["On a one-way street", "On a motorway when traffic in the right lane is moving slowly", "In normal driving conditions on a two-way road", "In a traffic queue"], correctAnswer: 2, explanation: "You should not normally overtake on the left (undertake) on a two-way road. Exceptions include one-way streets and slow-moving queues.", category: "Overtaking" },
  { id: 286, question: "What is the correct procedure at a crossroads where you have no priority?", options: ["Speed up to cross quickly", "Stop and give way to traffic on the major road", "Sound your horn and proceed", "Flash your lights and proceed"], correctAnswer: 1, explanation: "At a crossroads with no priority, stop and give way to traffic on the major road. Look in all directions before proceeding.", category: "Roundabouts" },
  { id: 287, question: "When approaching a mini-roundabout, which direction should you go around it?", options: ["Either direction", "Clockwise", "The shortest route", "It depends on your destination"], correctAnswer: 1, explanation: "You must pass around a mini-roundabout in a clockwise direction, giving way to traffic from the right.", category: "Roundabouts" },
  { id: 288, question: "What should you do when emerging from a T-junction?", options: ["Pull out quickly to avoid holding up traffic", "Look both ways and only emerge when it is safe", "Sound your horn to alert others", "Flash your headlights"], correctAnswer: 1, explanation: "At a T-junction, look both ways carefully and only emerge when there is a safe gap in traffic.", category: "Roundabouts" },

  // ===== ADDITIONAL LIGHTING (289–310) =====
  { id: 289, question: "When are you allowed to use your horn in a built-up area at night?", options: ["Between 11:30pm and 7am only if a vehicle is moving and poses a danger", "At any time", "Never", "Only before midnight"], correctAnswer: 0, explanation: "In a built-up area between 11:30pm and 7am, you must not use your horn when stationary. You may only use it when another moving vehicle poses a danger.", category: "Signalling" },
  { id: 290, question: "What are daytime running lights?", options: ["Headlights that must be on during the day", "Low-intensity lights that switch on automatically", "Fog lights used in daylight", "Indicator lights"], correctAnswer: 1, explanation: "Daytime running lights are low-intensity lights that switch on automatically when the engine is running, making you more visible.", category: "Lighting" },
  { id: 291, question: "When should you use rear fog lights?", options: ["In heavy rain", "When visibility is below 100 metres", "At night on unlit roads", "At all times in winter"], correctAnswer: 1, explanation: "Only use rear fog lights when visibility drops below 100 metres. Switch them off when visibility improves to avoid dazzling following drivers.", category: "Lighting" },
  { id: 292, question: "What lights should you use in a well-lit built-up area at night?", options: ["Full beam headlights", "Dipped headlights", "Sidelights only", "No lights needed"], correctAnswer: 1, explanation: "Use dipped headlights in built-up areas at night. Full beam can dazzle other drivers and pedestrians.", category: "Lighting" },

  // ===== ADDITIONAL ENVIRONMENTAL & SAFETY (293–340) =====
  { id: 293, question: "What is the 'lifesaver' check in driving?", options: ["Checking your seatbelt", "A final look over your shoulder into the blind spot", "Checking the first aid kit", "Looking in the rear-view mirror"], correctAnswer: 1, explanation: "The 'lifesaver' is a final check over your shoulder into the blind spot before changing direction or moving off.", category: "Alertness" },
  { id: 294, question: "What should you do if you see an elderly person with a stick waiting to cross?", options: ["Sound your horn to let them know you've seen them", "Drive on as they will wait", "Stop and give them time to cross", "Flash your headlights"], correctAnswer: 2, explanation: "Be patient with elderly pedestrians. Stop and give them plenty of time to cross the road safely.", category: "Vulnerable Road Users" },
  { id: 295, question: "What does an orange badge on a vehicle windscreen indicate?", options: ["A disabled driver or passenger", "A doctor", "A delivery driver", "A driving instructor"], correctAnswer: 0, explanation: "A Blue Badge (previously orange) indicates the vehicle is used by or for a disabled person, allowing special parking concessions.", category: "Vulnerable Road Users" },
  { id: 296, question: "What should you do when passing animals on the road?", options: ["Sound your horn to alert them", "Drive slowly and give them plenty of room", "Flash your headlights", "Accelerate past quickly"], correctAnswer: 1, explanation: "Drive slowly and quietly when passing animals. Sudden noise or fast movement can frighten them.", category: "Vulnerable Road Users" },
  { id: 297, question: "What does a triangular sign with a cow on it mean?", options: ["Farm shop ahead", "Cattle grid ahead", "Cattle or farm animals likely on the road", "No animals allowed"], correctAnswer: 2, explanation: "This warning sign indicates that cattle or farm animals may be on or crossing the road ahead.", category: "Traffic Signs" },
  { id: 298, question: "What is the purpose of a rumble strip?", options: ["To slow you down", "To alert you that you are approaching a hazard or leaving the carriageway", "To mark parking spaces", "To improve drainage"], correctAnswer: 1, explanation: "Rumble strips alert you through vibration and noise that you may be approaching a hazard or drifting off the carriageway.", category: "Safety Margins" },
  { id: 299, question: "What should you do if you are involved in an accident with an animal?", options: ["Drive on if the animal runs away", "Stop and report it to the police", "Only stop if another vehicle is involved", "Call the RSPCA only"], correctAnswer: 1, explanation: "If you hit a dog, horse, cattle, pig, goat, sheep, donkey, or mule, you must report it to the police.", category: "Accidents" },
  { id: 300, question: "What is the correct sequence for dealing with an accident scene?", options: ["Call police, move vehicles, exchange details", "Danger, Response, Airway, Breathing, Circulation (DR ABC)", "Take photos, call insurance, leave the scene", "Move casualties, call ambulance, direct traffic"], correctAnswer: 1, explanation: "DR ABC is the correct first-aid priority: check for Danger, Response, Airway, Breathing, and Circulation.", category: "Accidents" },

  // ===== ADDITIONAL MIXED TOPICS (301–400) =====
  { id: 301, question: "What is the minimum eyesight requirement for driving?", options: ["Read a number plate at 10 metres", "Read a number plate at 20 metres (20.5m for new-style plates)", "Read a sign at 50 metres", "There is no test"], correctAnswer: 1, explanation: "You must be able to read a number plate from 20 metres (20.5 metres for new-style plates). If you need glasses, you must wear them while driving.", category: "Documents" },
  { id: 302, question: "What is the thinking distance at 30 mph?", options: ["6 metres", "9 metres", "14 metres", "21 metres"], correctAnswer: 1, explanation: "At 30 mph, thinking distance is approximately 9 metres (30 feet). This is the distance travelled before you apply the brakes.", category: "Safety Margins" },
  { id: 303, question: "What is the braking distance at 30 mph in dry conditions?", options: ["6 metres", "9 metres", "14 metres", "21 metres"], correctAnswer: 2, explanation: "At 30 mph, braking distance in dry conditions is approximately 14 metres (45 feet).", category: "Safety Margins" },
  { id: 304, question: "What is the overall stopping distance at 20 mph?", options: ["6 metres", "12 metres (40 feet)", "23 metres", "36 metres"], correctAnswer: 1, explanation: "At 20 mph, the overall stopping distance is 12 metres (40 feet) — 6m thinking + 6m braking.", category: "Safety Margins" },
  { id: 305, question: "What is the overall stopping distance at 40 mph?", options: ["23 metres", "36 metres (120 feet)", "53 metres", "73 metres"], correctAnswer: 1, explanation: "At 40 mph, the overall stopping distance is 36 metres (120 feet) — 12m thinking + 24m braking.", category: "Safety Margins" },
  { id: 306, question: "What is the overall stopping distance at 50 mph?", options: ["36 metres", "53 metres (175 feet)", "73 metres", "96 metres"], correctAnswer: 1, explanation: "At 50 mph, the overall stopping distance is 53 metres (175 feet) — 15m thinking + 38m braking.", category: "Safety Margins" },
  { id: 307, question: "What does 'COAST' stand for in eco-driving?", options: ["Concentrate, Observe, Accelerate, Steer, Turn", "No specific meaning", "Concentration, Observation, Anticipation, Space, Time", "Coast whenever possible"], correctAnswer: 2, explanation: "COAST stands for Concentration, Observation, Anticipation, Space, and Time — key elements of safe, fuel-efficient driving.", category: "Environmental Issues" },
  { id: 308, question: "What is the maximum speed limit for a car on a road with street lights?", options: ["20 mph", "30 mph unless signs say otherwise", "40 mph", "60 mph"], correctAnswer: 1, explanation: "Street lights generally indicate a 30 mph speed limit unless signs show a different limit.", category: "Speed Limits" },
  { id: 309, question: "What colour are motorway emergency telephones?", options: ["Red", "Blue", "Orange", "Green"], correctAnswer: 2, explanation: "Motorway emergency telephones are orange. They connect directly to the Highways Agency control centre.", category: "Motorway Rules" },
  { id: 310, question: "How far apart are motorway emergency telephones?", options: ["500 metres", "1 mile", "2 miles", "5 miles"], correctAnswer: 1, explanation: "Emergency telephones are located every mile on motorways. Marker posts with arrows point to the nearest one.", category: "Motorway Rules" },
  { id: 311, question: "What should you do if you see a pedestrian with a dog near the road?", options: ["Sound your horn to alert the dog", "Be prepared for the dog to run into the road", "Speed up to pass quickly", "Flash your headlights"], correctAnswer: 1, explanation: "Dogs can be unpredictable. Be prepared for the dog to run into the road or for the lead to stretch across your path.", category: "Vulnerable Road Users" },
  { id: 312, question: "What is the correct procedure for parallel parking?", options: ["Drive in forwards at speed", "Pull alongside the car in front, reverse back turning the wheel", "Just park anywhere", "Always park on the right"], correctAnswer: 1, explanation: "Pull up alongside the car in front, check mirrors and blind spots, then reverse slowly, turning the steering wheel appropriately.", category: "Vehicle Handling" },
  { id: 313, question: "What should you do before reversing your vehicle?", options: ["Just use mirrors", "Check all around, including blind spots, before and during the manoeuvre", "Sound your horn", "Switch on hazard lights"], correctAnswer: 1, explanation: "Before reversing, check all around your vehicle including blind spots. Continue to check as you reverse.", category: "Vehicle Handling" },
  { id: 314, question: "What is the purpose of the MOT test?", options: ["To check the vehicle's age", "To ensure the vehicle meets minimum safety and environmental standards", "To value the vehicle", "To check insurance validity"], correctAnswer: 1, explanation: "The MOT test checks that your vehicle meets minimum safety and environmental standards required by law.", category: "Documents" },
  { id: 315, question: "When is it acceptable to use hazard warning lights while driving?", options: ["When double-parked", "On a motorway or unrestricted dual carriageway to warn traffic behind of a hazard ahead", "When lost", "When collecting someone"], correctAnswer: 1, explanation: "You may use hazard lights briefly while driving on a motorway or unrestricted dual carriageway to warn traffic behind of a hazard ahead.", category: "Signalling" },
  { id: 316, question: "What should you do if your steering suddenly feels very heavy?", options: ["Continue driving to a garage", "Stop safely — power steering may have failed", "Turn the steering wheel harder", "Drive faster to lighten the steering"], correctAnswer: 1, explanation: "Heavy steering may indicate power steering failure. Stop safely and have the vehicle checked before driving further.", category: "Vehicle Safety" },
  { id: 317, question: "What is the safest way to carry items in your car?", options: ["On the back seat loose", "In the boot or secured properly", "On the dashboard", "On the front passenger seat"], correctAnswer: 1, explanation: "Loose items can become dangerous projectiles in a collision. Store items in the boot or secure them properly.", category: "Vehicle Safety" },
  { id: 318, question: "What should you do if you notice a strange noise from your vehicle?", options: ["Ignore it if the car still drives", "Turn up the radio", "Have it investigated as soon as possible", "Only worry if a warning light appears"], correctAnswer: 2, explanation: "Unusual noises could indicate a mechanical problem. Have it checked promptly to prevent a potential breakdown or accident.", category: "Vehicle Safety" },
  { id: 319, question: "When should you use your sidelights?", options: ["In fog", "When parked on a road at night with a speed limit of 30 mph or less", "At all times when driving", "In bright sunshine"], correctAnswer: 1, explanation: "You may park using sidelights only on roads with a 30 mph speed limit or less. Above 30 mph, parking lights must be on.", category: "Lighting" },
  { id: 320, question: "What is block changing gears?", options: ["Changing up one gear at a time", "Missing out intermediate gears when changing", "Changing down rapidly", "Using only first and top gear"], correctAnswer: 1, explanation: "Block gear changing means changing directly to the gear you need (e.g., 4th to 2nd) without going through every intermediate gear.", category: "Vehicle Handling" },

  // ===== REMAINING QUESTIONS TO 700 (321–700) =====
  { id: 321, question: "What is the 'Dutch reach' technique?", options: ["A steering technique", "Opening the car door with the hand furthest from it to check for cyclists", "A braking method", "A parking technique"], correctAnswer: 1, explanation: "The Dutch reach involves opening your car door with the hand furthest from it, which naturally turns your body to check for cyclists.", category: "Vulnerable Road Users" },
  { id: 322, question: "What does a white 'H' sign on a blue background indicate?", options: ["Hotel ahead", "Hospital ahead", "Helicopter landing site", "Historic building"], correctAnswer: 1, explanation: "A white H on a blue background indicates the direction to the nearest hospital with an Accident and Emergency department.", category: "Traffic Signs" },
  { id: 323, question: "What should you do if you see a red triangle warning sign showing deer?", options: ["Speed up to avoid them", "Be alert for wild animals on or near the road", "Only worry at night", "Ignore it in summer"], correctAnswer: 1, explanation: "Wild animal warning signs mean animals may be on or crossing the road. Be alert and ready to slow down, especially at dawn and dusk.", category: "Hazard Perception" },
  { id: 324, question: "When must you use your headlights?", options: ["Only at night", "Only in fog", "Between sunset and sunrise, and in seriously reduced visibility", "Only on unlit roads"], correctAnswer: 2, explanation: "You must use headlights between sunset and sunrise and at any time when visibility is seriously reduced.", category: "Lighting" },
  { id: 325, question: "What is the maximum penalty for driving while disqualified?", options: ["£1,000 fine", "6 months imprisonment", "Community service", "A warning"], correctAnswer: 1, explanation: "Driving while disqualified can result in up to 6 months imprisonment, an unlimited fine, and further disqualification.", category: "Documents" },
  { id: 326, question: "What should you do when driving on a country road with no pavement?", options: ["Drive at the speed limit", "Watch for pedestrians walking in the road", "Use full beam at all times", "Drive in the middle of the road"], correctAnswer: 1, explanation: "On roads without pavements, pedestrians may walk in the road. Drive carefully and be prepared for them around bends.", category: "Hazard Perception" },
  { id: 327, question: "What is the purpose of a pelican crossing?", options: ["For cyclists only", "A signal-controlled crossing for pedestrians", "For horses only", "An uncontrolled crossing"], correctAnswer: 1, explanation: "A pelican crossing is a signal-controlled pedestrian crossing where pedestrians press a button to stop traffic.", category: "Pedestrian Crossings" },
  { id: 328, question: "How does the puffin crossing differ from a pelican crossing?", options: ["It has no sensors", "It uses sensors to detect pedestrians and holds the red light until they've crossed", "It allows cyclists too", "There is no difference"], correctAnswer: 1, explanation: "Puffin crossings use sensors to detect pedestrians on the crossing, holding the red light for traffic until they've finished crossing.", category: "Pedestrian Crossings" },
  { id: 329, question: "At a toucan crossing, who can cross?", options: ["Only pedestrians", "Only cyclists", "Both pedestrians and cyclists", "Only horse riders"], correctAnswer: 2, explanation: "Toucan crossings are designed for both pedestrians and cyclists to use together. The name comes from 'two can' cross.", category: "Pedestrian Crossings" },
  { id: 330, question: "What is a Pegasus crossing?", options: ["A crossing for large vehicles", "A crossing that can be used by horse riders", "A crossing for emergency vehicles", "A crossing with flashing lights"], correctAnswer: 1, explanation: "A Pegasus crossing (also called an equestrian crossing) has special controls for horse riders mounted higher up.", category: "Pedestrian Crossings" },

  { id: 331, question: "What should you do if your brakes fail while driving?", options: ["Switch off the engine immediately", "Pump the brake pedal and use a lower gear", "Pull the handbrake sharply", "Open the door and drag your foot"], correctAnswer: 1, explanation: "If brakes fail, pump the brake pedal rapidly to build pressure. Change to a lower gear and use the handbrake gently if needed.", category: "Vehicle Handling" },
  { id: 332, question: "What is 'defensive driving'?", options: ["Driving aggressively to protect yourself", "Driving with awareness, anticipation, and planning for potential hazards", "Driving slowly at all times", "Only driving on quiet roads"], correctAnswer: 1, explanation: "Defensive driving means being aware of potential dangers, anticipating the actions of other road users, and planning ahead.", category: "Attitude" },
  { id: 333, question: "Why should you keep a safe distance from the vehicle ahead?", options: ["To see road signs better", "To have time to react if it stops suddenly", "To save fuel", "Because it's the law"], correctAnswer: 1, explanation: "Keeping a safe distance gives you time to see and react to any changes in the traffic situation ahead.", category: "Safety Margins" },
  { id: 334, question: "What does 'mirror, signal, manoeuvre' mean in practice?", options: ["Check mirrors, signal your intention, then make the manoeuvre", "Signal first, then check mirrors, then manoeuvre", "Manoeuvre first, then signal", "Only use mirrors on motorways"], correctAnswer: 0, explanation: "Always check your mirrors first to assess the situation, signal to inform others, then carry out the manoeuvre when safe.", category: "Alertness" },
  { id: 335, question: "What is the purpose of hatched markings on the road?", options: ["Parking areas", "To separate traffic flows or protect turning traffic", "Bus lanes", "Cycle paths"], correctAnswer: 1, explanation: "Hatched markings separate traffic flows or protect traffic turning right. You should not enter the area unless it's safe and necessary.", category: "Traffic Signs" },
  { id: 336, question: "What does a sign showing two arrows pointing up and one pointing down mean?", options: ["Three lanes ahead", "Give priority to vehicles coming towards you", "Priority over oncoming vehicles", "No overtaking"], correctAnswer: 2, explanation: "This sign means you have priority over oncoming traffic in a narrow section of road.", category: "Traffic Signs" },
  { id: 337, question: "What does a sign with one large arrow pointing down and one small arrow pointing up mean?", options: ["You have priority", "Give priority to oncoming vehicles", "One-way street", "Hill ahead"], correctAnswer: 1, explanation: "This sign means you must give priority to vehicles coming from the opposite direction.", category: "Traffic Signs" },
  { id: 338, question: "What should you do when traffic lights are out of order?", options: ["Treat it as a give-way junction", "Treat the junction as an uncontrolled junction and proceed with caution", "Stop and wait for them to be fixed", "Sound your horn and drive through"], correctAnswer: 1, explanation: "When traffic lights are out of order, treat the junction as unmarked. No one has priority — proceed with great caution.", category: "Traffic Signs" },
  { id: 339, question: "What does an Advisory speed limit sign look like?", options: ["A red circle with a number", "A blue circle with a number", "A rectangular sign showing a speed", "A triangular sign"], correctAnswer: 2, explanation: "Advisory speed limits are shown on rectangular signs. They suggest a safe speed but are not legally enforceable.", category: "Speed Limits" },
  { id: 340, question: "What is the speed limit for cars on a dual carriageway?", options: ["50 mph", "60 mph", "70 mph", "80 mph"], correctAnswer: 2, explanation: "The national speed limit for cars on dual carriageways is 70 mph unless signs show otherwise.", category: "Speed Limits" },

  { id: 341, question: "What should you do if you are blinded by the sun?", options: ["Close your eyes briefly", "Slow down and use your sun visor", "Speed up to get past the area", "Stop in the road"], correctAnswer: 1, explanation: "If dazzled by the sun, slow down, use your sun visor, and wear sunglasses if needed. Be extra cautious.", category: "Alertness" },
  { id: 342, question: "When should you signal before a roundabout?", options: ["Only when turning right", "Always signal your intention on approach and exit", "Never, it's optional", "Only when other vehicles are present"], correctAnswer: 1, explanation: "Signal your intention on approach to help other road users anticipate your movement, and signal left when exiting.", category: "Roundabouts" },
  { id: 343, question: "What lane should you be in for turning left at a roundabout?", options: ["Right lane", "Left lane", "Either lane", "Middle lane"], correctAnswer: 1, explanation: "For turning left (first exit) or going straight ahead, approach in the left lane unless road markings indicate otherwise.", category: "Roundabouts" },
  { id: 344, question: "What lane should you be in for turning right at a roundabout?", options: ["Left lane", "Right lane", "Either lane", "Centre lane"], correctAnswer: 1, explanation: "For turning right (third exit or later), approach in the right lane unless road markings indicate otherwise.", category: "Roundabouts" },
  { id: 345, question: "What should you do if a vehicle in front stops at a level crossing?", options: ["Overtake it", "Wait behind it and don't park on the crossing", "Sound your horn", "Turn around"], correctAnswer: 1, explanation: "Wait patiently behind the vehicle. Never park on or close to a level crossing as this could be extremely dangerous.", category: "Hazard Perception" },
  { id: 346, question: "What does a white line along the edge of a road mean?", options: ["No parking", "The edge of the carriageway", "Bus stop", "Cycle lane"], correctAnswer: 1, explanation: "A white line along the edge of the road marks the boundary of the carriageway.", category: "Traffic Signs" },
  { id: 347, question: "What does 'steering into a skid' mean?", options: ["Turning the wheel in the opposite direction to the skid", "Turning the wheel in the direction the rear of the car is sliding", "Letting go of the steering wheel", "Turning sharply left"], correctAnswer: 1, explanation: "Steer in the direction the rear of the car is sliding. This helps to straighten the car and regain control.", category: "Vehicle Handling" },
  { id: 348, question: "Why should you always wear a seatbelt?", options: ["To avoid a fine", "It significantly reduces the risk of death or serious injury in a crash", "It's only important on long journeys", "Only the driver needs one"], correctAnswer: 1, explanation: "Wearing a seatbelt can reduce the risk of death by up to 50%. It is a legal requirement for all occupants.", category: "Vehicle Safety" },
  { id: 349, question: "Who is responsible for ensuring children under 14 wear seatbelts?", options: ["The child themselves", "The driver", "The front passenger", "No one, it's optional"], correctAnswer: 1, explanation: "The driver is legally responsible for ensuring all passengers under 14 years of age are wearing seatbelts or using appropriate child restraints.", category: "Vehicle Safety" },
  { id: 350, question: "When can a child sit in the front seat of a car?", options: ["Never", "At any age with a seatbelt", "Only if appropriate child restraint is used", "Only from age 12"], correctAnswer: 2, explanation: "Children can sit in the front seat if the correct child restraint is used. It's safer for them to sit in the rear.", category: "Vehicle Safety" },

  { id: 351, question: "What is the correct procedure for a hill start?", options: ["Rev the engine and release the handbrake quickly", "Find the biting point, check mirrors and blind spot, release the handbrake smoothly", "Start in a high gear", "Release the clutch quickly"], correctAnswer: 1, explanation: "Set the gas, find the clutch biting point, check mirrors and blind spot, signal if needed, then smoothly release the handbrake.", category: "Vehicle Handling" },
  { id: 352, question: "What should you check when buying a used car?", options: ["Only the colour", "Valid MOT, service history, and HPI check for outstanding finance or theft", "Just the mileage", "Nothing if the price is right"], correctAnswer: 1, explanation: "Check MOT history, service records, do an HPI check for finance/theft, and inspect the car's overall condition.", category: "Documents" },
  { id: 353, question: "What is a contraflow system on a motorway?", options: ["A new lane opening", "Traffic travels in the opposite direction to normal on a section of the motorway", "A diversion route", "A bus lane on a motorway"], correctAnswer: 1, explanation: "Contraflow systems move traffic to the other carriageway during roadworks. Follow signs and keep to the speed limit.", category: "Motorway Rules" },
  { id: 354, question: "What should you do if you see a motorway information sign showing 'Fog'?", options: ["Maintain your speed", "Slow down and be prepared for poor visibility", "Put on full beam", "Stop on the hard shoulder"], correctAnswer: 1, explanation: "Motorway signals warning of fog mean you should slow down, increase following distance, and use appropriate lights.", category: "Motorway Rules" },
  { id: 355, question: "What is a refuge island?", options: ["A motorway rest area", "A raised area in the middle of the road where pedestrians can wait", "A traffic island for parking", "An emergency stopping area"], correctAnswer: 1, explanation: "A refuge island provides a safe place in the middle of the road where pedestrians can wait when crossing wide roads.", category: "Pedestrian Crossings" },
  { id: 356, question: "What should you do if you notice a vehicle weaving across lanes on a motorway?", options: ["Overtake it quickly", "Keep well back as the driver may be drowsy or impaired", "Sound your horn repeatedly", "Flash your headlights"], correctAnswer: 1, explanation: "A vehicle weaving may indicate a tired or impaired driver. Keep your distance and consider reporting it to the police.", category: "Hazard Perception" },
  { id: 357, question: "What is the safe rule for following a vehicle in fog?", options: ["Keep close to see their lights", "Be able to stop within your range of visibility", "Follow at normal distance", "Use full beam to see further"], correctAnswer: 1, explanation: "In fog, you must be able to stop within the distance you can see clearly. Increase your following distance significantly.", category: "Safety Margins" },
  { id: 358, question: "What is progressive braking?", options: ["Braking harder and harder", "Gradually increasing brake pressure then easing off before stopping", "Only using engine braking", "Pumping the brake pedal"], correctAnswer: 1, explanation: "Progressive braking means gradually increasing pressure on the brake pedal, then easing off slightly just before the vehicle stops for a smooth halt.", category: "Vehicle Handling" },
  { id: 359, question: "What does POWDER stand for in fire extinguisher checks?", options: ["A type of extinguisher", "Pull pin, Operate handle, Wipe, Direct, Extinguish, Review", "Nothing specific", "Pressure, Operation, Weight, Date, Expiry, Recharge"], correctAnswer: 0, explanation: "POWDER is a mnemonic for using a fire extinguisher: Pull pin, Operate handle, aim at base of fire. Check regularly.", category: "Accidents" },
  { id: 360, question: "What gear should you normally be in when turning left from a major road?", options: ["4th", "3rd", "2nd", "1st"], correctAnswer: 2, explanation: "Usually slow down and select 2nd gear for a left turn, though this depends on the specific junction and speed.", category: "Vehicle Handling" },

  { id: 361, question: "What is the correct procedure for bay parking?", options: ["Drive straight in at speed", "Observe, select your bay, position your car correctly, and reverse in checking all around", "Always drive in forwards", "Park in any available space"], correctAnswer: 1, explanation: "Check mirrors and blind spots, select your bay, position the car correctly, and reverse in slowly while checking all around.", category: "Vehicle Handling" },
  { id: 362, question: "When should you use cruise control?", options: ["In heavy traffic", "On open roads with a steady speed and light traffic", "In town centres", "In poor weather conditions"], correctAnswer: 1, explanation: "Cruise control is best used on open, quiet roads where you can maintain a steady speed. Avoid in heavy traffic or poor conditions.", category: "Vehicle Handling" },
  { id: 363, question: "What does ESC (Electronic Stability Control) do?", options: ["Controls the radio", "Helps prevent skidding by automatically applying brakes to individual wheels", "Adjusts the seat position", "Controls engine temperature"], correctAnswer: 1, explanation: "ESC detects when the car is starting to skid and automatically applies brakes to individual wheels to help maintain control.", category: "Vehicle Safety" },
  { id: 364, question: "What is the purpose of the dipstick in your engine?", options: ["To check coolant level", "To check engine oil level", "To check brake fluid", "To check power steering fluid"], correctAnswer: 1, explanation: "The dipstick is used to check the engine oil level. Check it regularly when the engine is cold on level ground.", category: "Vehicle Safety" },
  { id: 365, question: "What colour is the engine oil warning light?", options: ["Blue", "Green", "Red", "Amber"], correctAnswer: 2, explanation: "The engine oil warning light is red. If it comes on while driving, stop as soon as it is safe and check oil level.", category: "Vehicle Safety" },
  { id: 366, question: "Why should you avoid resting your foot on the clutch pedal while driving?", options: ["It doesn't matter", "It can cause premature clutch wear", "It improves fuel economy", "It helps with gear changes"], correctAnswer: 1, explanation: "Resting your foot on the clutch causes unnecessary wear on the clutch plate, known as 'riding the clutch'.", category: "Vehicle Handling" },
  { id: 367, question: "What is the correct hand position on the steering wheel?", options: ["10 and 2 or 9 and 3 o'clock", "12 o'clock with one hand", "One hand at 6 o'clock", "Anywhere comfortable"], correctAnswer: 0, explanation: "The recommended hand positions are either 10 and 2 or 9 and 3 on the steering wheel for maximum control.", category: "Vehicle Handling" },
  { id: 368, question: "What happens to your car insurance if you modify your vehicle?", options: ["Nothing", "You must inform your insurer as it may affect your premium", "It becomes invalid automatically", "Only body modifications matter"], correctAnswer: 1, explanation: "Any modifications must be declared to your insurer. Failure to do so could invalidate your insurance.", category: "Documents" },
  { id: 369, question: "What is an Emergency Refuge Area on a smart motorway?", options: ["A car park", "A safe place to stop in an emergency when there is no hard shoulder", "A picnic area", "A toll booth"], correctAnswer: 1, explanation: "Emergency Refuge Areas (ERAs) are safe places to stop on smart motorways with no hard shoulder. They have an SOS phone.", category: "Motorway Rules" },
  { id: 370, question: "What should you do if your accelerator pedal sticks?", options: ["Turn off the engine immediately", "Try to free it with your foot, shift to neutral, and brake", "Jump out of the car", "Ignore it"], correctAnswer: 1, explanation: "Try to free the pedal. If it stays stuck, shift to neutral, brake carefully, and pull over safely. Don't turn off the engine.", category: "Vehicle Handling" },

  { id: 371, question: "What is the main cause of accidents at junctions?", options: ["Poor road surface", "Failure to look properly", "Traffic light failure", "Bad weather"], correctAnswer: 1, explanation: "The most common cause of accidents at junctions is drivers failing to look properly before proceeding.", category: "Hazard Perception" },
  { id: 372, question: "When should you use the pull-push steering method?", options: ["Only when parking", "For all normal steering", "Only at high speeds", "Only when turning left"], correctAnswer: 1, explanation: "The pull-push (or push-pull) method maintains both hands on the wheel and provides smooth, controlled steering.", category: "Vehicle Handling" },
  { id: 373, question: "What should you check before driving in snow?", options: ["Your car colour is visible", "All windows and mirrors are clear, lights are clean, and you have enough fuel", "Only the windscreen", "Nothing special"], correctAnswer: 1, explanation: "Clear all windows, mirrors, and lights of snow and ice. Ensure adequate fuel and consider whether the journey is necessary.", category: "Vehicle Safety" },
  { id: 374, question: "What is the legal requirement for child car seats?", options: ["Optional for short journeys", "Children must use an appropriate child restraint until 12 years old or 135cm tall", "Only needed on motorways", "Only for children under 3"], correctAnswer: 1, explanation: "Children must use an appropriate child car seat or booster until they are 12 years old or 135cm (4ft 5in) tall, whichever comes first.", category: "Vehicle Safety" },
  { id: 375, question: "What is 'LADA' in the context of motorcycles and junctions?", options: ["A car manufacturer", "Look, Assess, Decide, Act", "Left, Advance, Drive, Accelerate", "Lane, Approach, Direction, Action"], correctAnswer: 1, explanation: "LADA (Look, Assess, Decide, Act) helps you systematically check for motorcycles at junctions, which are harder to spot.", category: "Vulnerable Road Users" },
  { id: 376, question: "What should you do if you drop something while driving?", options: ["Reach down and pick it up", "Leave it until you have stopped safely", "Ask a passenger to get it", "Stop immediately"], correctAnswer: 1, explanation: "Never try to pick up a dropped item while driving. Wait until you have stopped in a safe place.", category: "Alertness" },
  { id: 377, question: "What is the recommended gap between you and the vehicle ahead on a motorway?", options: ["One car length per 10 mph", "At least two seconds in good conditions", "One second", "Five car lengths"], correctAnswer: 1, explanation: "Maintain at least a two-second gap from the vehicle ahead. Double this in wet conditions and increase further in ice.", category: "Safety Margins" },
  { id: 378, question: "Why are contraflow systems on motorways dangerous?", options: ["Because they are well lit", "Because lanes are narrower and traffic travels in both directions close together", "Because speed limits are higher", "They are not dangerous"], correctAnswer: 1, explanation: "Contraflow systems are dangerous because of narrow lanes, proximity to oncoming traffic, and frequent lane changes.", category: "Motorway Rules" },
  { id: 379, question: "What does an amber traffic light mean when shown alone?", options: ["Prepare to go", "Stop at the stop line (unless unsafe to do so)", "Go if the junction is clear", "Speed up"], correctAnswer: 1, explanation: "Amber alone means stop. You may only proceed if you have already crossed the stop line or stopping would cause an accident.", category: "Traffic Signs" },
  { id: 380, question: "What does red and amber shown together at traffic lights mean?", options: ["Stop", "Prepare to go — wait for green", "Go", "Caution"], correctAnswer: 1, explanation: "Red and amber together means the lights are about to change to green. Wait for the green light before moving off.", category: "Traffic Signs" },

  { id: 381, question: "What is the speed limit for goods vehicles over 7.5 tonnes on a motorway?", options: ["50 mph", "56 mph", "60 mph", "70 mph"], correctAnswer: 2, explanation: "Goods vehicles over 7.5 tonnes are limited to 60 mph on motorways.", category: "Speed Limits" },
  { id: 382, question: "What should you do before entering a tunnel?", options: ["Switch off your lights", "Remove sunglasses, switch on headlights, tune to the tunnel radio station if shown", "Speed up to get through quickly", "Close all windows"], correctAnswer: 1, explanation: "Remove sunglasses, turn on dipped headlights, and note the radio frequency displayed for traffic information.", category: "Hazard Perception" },
  { id: 383, question: "What should you do if your vehicle catches fire in a tunnel?", options: ["Stay in your vehicle", "Drive out of the tunnel", "Switch off the engine, leave the vehicle, and use the emergency exits", "Sound your horn"], correctAnswer: 2, explanation: "Switch off the engine, leave the keys, and exit via the emergency exits. Do not try to drive out.", category: "Accidents" },
  { id: 384, question: "What is the purpose of anti-lock brakes (ABS)?", options: ["To lock the wheels for faster stopping", "To prevent wheels from locking so you can still steer under heavy braking", "To apply brakes automatically", "To reduce tyre wear"], correctAnswer: 1, explanation: "ABS prevents wheel lock-up during hard braking, maintaining steering control so you can steer around hazards.", category: "Vehicle Safety" },
  { id: 385, question: "When are you legally required to use your headlights?", options: ["Only on motorways", "Between sunset and sunrise", "Only in rain", "Only when other cars have theirs on"], correctAnswer: 1, explanation: "You must use headlights between sunset and sunrise and at any time when visibility is seriously reduced.", category: "Lighting" },
  { id: 386, question: "What does TPMS stand for?", options: ["Total Performance Monitoring System", "Tyre Pressure Monitoring System", "Traffic Performance Management System", "Thermal Protection Monitoring System"], correctAnswer: 1, explanation: "TPMS monitors tyre pressures and warns you if a tyre is significantly under-inflated.", category: "Vehicle Safety" },
  { id: 387, question: "What is the legal tread depth across the central three-quarters of the tyre?", options: ["1.0 mm", "1.6 mm", "2.0 mm", "3.0 mm"], correctAnswer: 1, explanation: "The legal minimum tread depth for car tyres is 1.6 mm across the central three-quarters of the breadth and around the entire circumference.", category: "Vehicle Safety" },
  { id: 388, question: "What should you do if you aquaplane in heavy rain?", options: ["Steer sharply", "Brake hard", "Ease off the accelerator and don't brake until control returns", "Speed up to regain grip"], correctAnswer: 2, explanation: "If you aquaplane, ease off the accelerator and avoid braking or steering until your tyres regain grip.", category: "Safety Margins" },
  { id: 389, question: "What is the purpose of a chevron board at a sharp bend?", options: ["Speed limit change ahead", "Sharp deviation in the road direction", "Parking ahead", "Junction ahead"], correctAnswer: 1, explanation: "Chevron boards mark sharp bends or changes in road direction. The arrows point in the direction you should pass.", category: "Traffic Signs" },
  { id: 390, question: "What is meant by the term 'blind summit'?", options: ["A junction with no signs", "A hill crest where you cannot see the road beyond", "A summit with no lighting", "A mountain pass"], correctAnswer: 1, explanation: "A blind summit is where the road goes over a hill and you cannot see the road or any hazards on the other side.", category: "Hazard Perception" },

  { id: 391, question: "When should you check your tyre pressures?", options: ["Only when they look flat", "At least once a week and before long journeys", "Once a year", "Only at MOT time"], correctAnswer: 1, explanation: "Check tyre pressures at least once a week when the tyres are cold. Also check before long journeys.", category: "Vehicle Safety" },
  { id: 392, question: "What can happen if your tyre pressures are too high?", options: ["Better grip", "Uneven tyre wear and reduced grip", "Improved fuel economy", "No effect"], correctAnswer: 1, explanation: "Over-inflated tyres have a smaller contact patch with the road, resulting in reduced grip and uneven tyre wear.", category: "Vehicle Safety" },
  { id: 393, question: "What should you do if you witness an accident but cannot stop?", options: ["Drive on and forget about it", "Call 999 when safe to do so", "Post about it on social media", "Call your friend"], correctAnswer: 1, explanation: "If you cannot stop safely, call 999 as soon as it is safe to do so to report the accident.", category: "Accidents" },
  { id: 394, question: "What is meant by 'limit point analysis'?", options: ["The speed limit on a road", "Judging the severity of a bend by where the road edges appear to meet", "The maximum brake pressure", "The petrol gauge limit"], correctAnswer: 1, explanation: "Limit point analysis helps you judge the severity of a bend by observing where the two sides of the road appear to meet.", category: "Vehicle Handling" },
  { id: 395, question: "What is the purpose of lane markings approaching a roundabout?", options: ["To indicate parking areas", "To guide you into the correct lane for your exit", "To indicate speed limits", "To mark cycle lanes"], correctAnswer: 1, explanation: "Lane markings on the approach to roundabouts guide you into the correct lane for your intended exit.", category: "Roundabouts" },
  { id: 396, question: "What does 'observation links' mean in driving?", options: ["Looking at road signs only", "Connecting what you see to what action you need to take", "Checking mirrors only", "Looking at the speedometer"], correctAnswer: 1, explanation: "Observation links mean connecting your observations to your actions — seeing a hazard and adjusting your driving accordingly.", category: "Alertness" },
  { id: 397, question: "When is it legal to reverse onto a main road from a side road?", options: ["At any time if it's safe", "Never — always reverse into the side road, not out of it", "Only during daylight hours", "Only if no traffic is coming"], correctAnswer: 1, explanation: "You should not reverse from a side road onto a main road. If needed, reverse into the side road and drive out forwards.", category: "Vehicle Handling" },
  { id: 398, question: "What should you do when approaching traffic lights that have been green for some time?", options: ["Speed up to get through", "Be prepared for them to change", "No need to change your driving", "Flash your headlights"], correctAnswer: 1, explanation: "If lights have been green for a while, be prepared for them to change. Ease off the accelerator and be ready to stop.", category: "Alertness" },
  { id: 399, question: "What is the correct action if your bonnet flies open while driving?", options: ["Try to close it while driving", "Slow down and look through the gap beneath the bonnet or out of the side window", "Stop immediately in the road", "Close your eyes"], correctAnswer: 1, explanation: "If your bonnet opens, try to look through any gap below it or out of the side window. Slow down and stop safely.", category: "Vehicle Handling" },
  { id: 400, question: "What is the purpose of a green reflective stud on a motorway?", options: ["Marks the edge of the main carriageway", "Marks the junction slip road", "Marks the central reservation", "Marks the hard shoulder"], correctAnswer: 1, explanation: "Green studs mark the edge of the main carriageway at junctions and slip roads.", category: "Motorway Rules" },

  // Continue with more questions across all categories
  { id: 401, question: "What colour are the reflective studs between the carriageway and the hard shoulder?", options: ["White", "Red", "Amber", "Green"], correctAnswer: 1, explanation: "Red studs mark the left edge of the carriageway (between the carriageway and the hard shoulder).", category: "Motorway Rules" },
  { id: 402, question: "What colour are the reflective studs between lanes on a motorway?", options: ["Red", "Green", "White", "Amber"], correctAnswer: 2, explanation: "White studs separate the lanes or mark the middle of the road.", category: "Motorway Rules" },
  { id: 403, question: "What colour are the reflective studs on the central reservation of a motorway?", options: ["White", "Red", "Amber", "Green"], correctAnswer: 2, explanation: "Amber studs mark the central reservation (the edge between the carriageway and the central reservation).", category: "Motorway Rules" },
  { id: 404, question: "What is the maximum fine for not wearing a seatbelt?", options: ["£100", "£500", "£1,000", "£2,500"], correctAnswer: 1, explanation: "The maximum fine for not wearing a seatbelt is £500.", category: "Documents" },
  { id: 405, question: "When is it acceptable to not wear a seatbelt?", options: ["On short journeys", "When making a local delivery (reversing or driving forward for deliveries)", "When driving slowly", "When parked with the engine running"], correctAnswer: 1, explanation: "Exemptions include local delivery drivers while making deliveries, drivers reversing, and those with medical exemption certificates.", category: "Documents" },
  { id: 406, question: "How should you dispose of old engine oil?", options: ["Pour it down the drain", "Put it in the household rubbish", "Take it to a local authority recycling site", "Leave it on the street"], correctAnswer: 2, explanation: "Old engine oil must be disposed of properly at a recycling centre. It is illegal to pour it into drains or the ground.", category: "Environmental Issues" },
  { id: 407, question: "What should you do to reduce your carbon footprint when driving?", options: ["Drive everywhere in first gear", "Plan efficient routes and combine journeys", "Leave the engine running when parked", "Drive with under-inflated tyres"], correctAnswer: 1, explanation: "Planning efficient routes and combining multiple short trips into one journey reduces fuel consumption and emissions.", category: "Environmental Issues" },
  { id: 408, question: "What is regenerative braking?", options: ["A type of engine braking", "A system that recovers energy during braking in electric/hybrid vehicles", "Emergency braking", "Using both foot and hand brake"], correctAnswer: 1, explanation: "Regenerative braking captures the kinetic energy during braking and converts it to electrical energy to recharge the battery.", category: "Environmental Issues" },
  { id: 409, question: "What is a ULEZ?", options: ["Ultra Low Emission Zone", "Universal Lane Entry Zone", "Urban Load Entry Zone", "Unlimited Lane Extension Zone"], correctAnswer: 0, explanation: "ULEZ stands for Ultra Low Emission Zone. Vehicles that don't meet emission standards must pay a daily charge to drive in the zone.", category: "Environmental Issues" },
  { id: 410, question: "What is the benefit of eco-start/stop technology?", options: ["It makes the car go faster", "It automatically switches off the engine when stationary to save fuel and reduce emissions", "It charges the battery", "It cleans the exhaust"], correctAnswer: 1, explanation: "Start/stop technology turns off the engine when the car is stationary in traffic, reducing fuel use and emissions.", category: "Environmental Issues" },

  { id: 411, question: "What should you do if you meet an oncoming vehicle on a narrow road?", options: ["Force your way through", "Pull into a passing place on your left or wait opposite one on the right", "Sound your horn and continue", "Reverse back to a wider section"], correctAnswer: 1, explanation: "If there's a passing place on your left, pull into it. If it's on the right, wait opposite it to let the other vehicle pass.", category: "Attitude" },
  { id: 412, question: "What is a 20 mph zone?", options: ["An area where you can drive at any speed", "An area with a 20 mph speed limit, usually near schools or residential areas", "A motorway slip road", "A zone for electric vehicles"], correctAnswer: 1, explanation: "20 mph zones are typically found in residential areas and near schools to improve safety for pedestrians.", category: "Speed Limits" },
  { id: 413, question: "What is 'scanning' in driving?", options: ["Looking at your phone", "Continuously looking around for potential hazards", "Checking for speed cameras", "Reading road signs only"], correctAnswer: 1, explanation: "Scanning means continuously looking well ahead, to the sides, and checking mirrors to identify potential hazards early.", category: "Alertness" },
  { id: 414, question: "What should you do if a large vehicle is reversing towards you?", options: ["Sound your horn and stay put", "Drive around it quickly", "Stop and give it room — the driver may not be able to see you", "Flash your headlights and wait"], correctAnswer: 2, explanation: "Large vehicles have significant blind spots. Stop well back, give them room, and be patient.", category: "Other Vehicles" },
  { id: 415, question: "What does the term 'filtering' mean for motorcyclists?", options: ["Using an oil filter", "Moving between slow-moving or stationary traffic", "Riding on the pavement", "Using a cycle lane"], correctAnswer: 1, explanation: "Filtering is when motorcyclists move between slow-moving or stationary traffic. Be aware of this — check mirrors before changing lanes.", category: "Vulnerable Road Users" },
  { id: 416, question: "How can you improve fuel efficiency when approaching a red traffic light?", options: ["Maintain speed until the last moment", "Take your foot off the accelerator early and coast to the light", "Keep in a low gear", "Use the brakes hard at the last moment"], correctAnswer: 1, explanation: "Lifting off the accelerator early and coasting to the red light saves fuel and reduces brake wear.", category: "Environmental Issues" },
  { id: 417, question: "What does a red 'X' above a motorway lane mean?", options: ["Lane is open", "Lane is closed — do not drive in it", "Speed limit applies", "Hard shoulder is available"], correctAnswer: 1, explanation: "A red X means the lane is closed. You must not drive in a lane with a red X displayed above it.", category: "Motorway Rules" },
  { id: 418, question: "What is the correct position for driving on a single-track road?", options: ["The centre of the road", "Close to the left edge", "The right side", "It doesn't matter"], correctAnswer: 1, explanation: "On single-track roads, keep close to the left and use passing places. Be prepared to give way to oncoming vehicles.", category: "Vehicle Handling" },
  { id: 419, question: "What is the Highway Code?", options: ["A book of driving test answers", "Official guidance on road laws and best practices for all road users", "A list of speed limits only", "Insurance regulations"], correctAnswer: 1, explanation: "The Highway Code is official guidance for all road users, covering rules, regulations, and advice for safe road use.", category: "Documents" },
  { id: 420, question: "What is the meaning of 'SLOW' painted on the road?", options: ["You must stop", "Reduce speed — a hazard may be ahead", "Slow vehicles only lane", "No parking"], correctAnswer: 1, explanation: "SLOW painted on the road warns you to reduce speed because there may be a hazard ahead such as a bend or junction.", category: "Traffic Signs" },

  { id: 421, question: "What is the safe procedure for turning right from a main road?", options: ["Signal, position to the right, wait for a safe gap", "Signal and turn immediately", "Stop in the middle and wait", "No special procedure needed"], correctAnswer: 0, explanation: "Signal right, position just left of the centre line (or in the right lane), wait for a safe gap in oncoming traffic, then turn.", category: "Vehicle Handling" },
  { id: 422, question: "Why is it dangerous to drive too close to the vehicle ahead?", options: ["You'll use more fuel", "You won't have time to stop if they brake suddenly", "It's only dangerous in wet weather", "It's not dangerous"], correctAnswer: 1, explanation: "Tailgating greatly reduces your reaction and braking distance, making a collision far more likely if the vehicle ahead stops suddenly.", category: "Safety Margins" },
  { id: 423, question: "What is the correct procedure at a zebra crossing?", options: ["Drive through if no one is crossing", "Stop and give way to pedestrians waiting to cross or already crossing", "Only stop if a pedestrian waves", "Sound your horn to warn pedestrians"], correctAnswer: 1, explanation: "You must give way to pedestrians at a zebra crossing. If someone is waiting to cross, you should stop.", category: "Pedestrian Crossings" },
  { id: 424, question: "What does adaptive cruise control do differently from standard cruise control?", options: ["Nothing different", "It automatically adjusts speed to maintain a safe distance from the vehicle ahead", "It steers the car", "It changes gears"], correctAnswer: 1, explanation: "Adaptive cruise control uses sensors to maintain a set following distance from the vehicle ahead, automatically adjusting speed.", category: "Vehicle Safety" },
  { id: 425, question: "What should you do before opening your car door?", options: ["Nothing", "Check mirrors and look behind for cyclists or other road users", "Just open it quickly", "Sound the horn"], correctAnswer: 1, explanation: "Always check your mirrors and look behind before opening your door to avoid hitting cyclists, pedestrians, or other vehicles.", category: "Alertness" },
  { id: 426, question: "What is the 'cascade' effect in multi-vehicle motorway pile-ups?", options: ["A type of braking", "Each vehicle hitting the one in front because of insufficient following distance", "Water cascading on the windscreen", "Changing lanes quickly"], correctAnswer: 1, explanation: "The cascade effect occurs when vehicles following too closely cannot stop in time, each hitting the one in front in chain reaction.", category: "Safety Margins" },
  { id: 427, question: "What should you do if you see a flashing red light at a level crossing?", options: ["Cross quickly if the road is clear", "Stop and wait — a train is approaching", "Slow down and proceed with caution", "Sound your horn"], correctAnswer: 1, explanation: "A flashing red light at a level crossing means STOP. A train is approaching or the crossing is not clear.", category: "Traffic Signs" },
  { id: 428, question: "What should you do when driving past roadworks on a motorway?", options: ["Speed up to clear the area", "Follow speed limits, stay in your lane, and be aware of workers", "Ignore the cones", "Move to the right lane"], correctAnswer: 1, explanation: "Obey all speed limits and signs at roadworks. Stay in your lane and be aware of road workers and sudden lane changes.", category: "Motorway Rules" },
  { id: 429, question: "When should you avoid making a U-turn?", options: ["On a one-way street", "Where there are double white lines in the centre", "Where visibility is limited", "All of these"], correctAnswer: 3, explanation: "Never make a U-turn on one-way streets, where prohibited by signs or road markings, or where visibility is restricted.", category: "Vehicle Handling" },
  { id: 430, question: "What is the purpose of a traffic-calming measure like a speed bump?", options: ["To damage vehicles", "To slow traffic down in residential areas for safety", "To prevent parking", "To redirect traffic"], correctAnswer: 1, explanation: "Traffic calming measures like speed bumps are designed to reduce vehicle speeds in areas where pedestrian safety is important.", category: "Speed Limits" },

  { id: 431, question: "What percentage of road accidents involve drivers aged 17-25?", options: ["About 5%", "About 25%", "About 50%", "About 75%"], correctAnswer: 1, explanation: "Young and inexperienced drivers are disproportionately involved in road accidents, accounting for about a quarter of all collisions.", category: "Attitude" },
  { id: 432, question: "What is the legal drink-drive limit in Scotland?", options: ["Same as England", "22 micrograms per 100ml of breath — lower than England", "Zero tolerance", "50 micrograms per 100ml of breath"], correctAnswer: 1, explanation: "Scotland has a lower drink-drive limit than England and Wales — 22 micrograms of alcohol per 100ml of breath.", category: "Drink Driving" },
  { id: 433, question: "What effect does fatigue have on your driving?", options: ["It makes you drive more carefully", "It slows your reaction time and impairs concentration", "No effect if you're used to it", "It only affects night driving"], correctAnswer: 1, explanation: "Fatigue significantly slows reaction times, reduces concentration, and can lead to microsleeps — brief involuntary naps.", category: "Alertness" },
  { id: 434, question: "How often should you take breaks on a long journey?", options: ["Every 4 hours", "At least every 2 hours", "Only when you feel tired", "At every service station"], correctAnswer: 1, explanation: "Take a break of at least 15 minutes every 2 hours on a long journey. Stop sooner if you feel tired.", category: "Alertness" },
  { id: 435, question: "What type of road has the highest risk of head-on collisions?", options: ["Motorways", "Single carriageway roads", "Dual carriageways", "Urban roads"], correctAnswer: 1, explanation: "Single carriageway roads have the highest risk of head-on collisions because oncoming traffic is separated only by road markings.", category: "Safety Margins" },
  { id: 436, question: "What should you check before setting off after a vehicle has been parked for a while?", options: ["Only fuel level", "Under the vehicle for animals or children, oil leaks, tyre condition", "Just the mirrors", "Nothing special"], correctAnswer: 1, explanation: "Check under and around the vehicle for children, animals, or leaks. Also check tyres, mirrors, and seat adjustment.", category: "Vehicle Safety" },
  { id: 437, question: "What does the 'Green Cross Code' teach?", options: ["How to drive in green areas", "A safe way for pedestrians to cross roads", "Traffic light procedures", "How to recycle"], correctAnswer: 1, explanation: "The Green Cross Code teaches pedestrians to STOP, LOOK, LISTEN, and THINK before crossing a road safely.", category: "Vulnerable Road Users" },
  { id: 438, question: "Why might you see temporary traffic lights at roadworks?", options: ["To test new signals", "To control traffic flow safely where the road is narrowed", "To slow everyone down", "They are optional"], correctAnswer: 1, explanation: "Temporary traffic lights control traffic where the road is reduced to one lane during roadworks.", category: "Traffic Signs" },
  { id: 439, question: "What is the recommended technique for driving on snow-covered roads?", options: ["Use high revs in a low gear", "Drive in a higher gear with gentle acceleration", "Brake frequently", "Drive as fast as possible"], correctAnswer: 1, explanation: "In snow, use a higher gear with gentle acceleration to reduce wheel spin. Brake gently and in a straight line.", category: "Vehicle Handling" },
  { id: 440, question: "What should you do if your car gets stuck in snow?", options: ["Rev the engine hard", "Use a low gear and gently rock the car backwards and forwards", "Abandon the car immediately", "Wait for it to melt"], correctAnswer: 1, explanation: "Try a low gear, gentle acceleration, and rocking the car. Place mats or sacking under the driven wheels for grip.", category: "Vehicle Handling" },

  { id: 441, question: "What is the correct procedure for a three-point turn?", options: ["Turn around in one go", "Full lock left, reverse full lock right, drive forward", "Drive forward, check mirrors and blind spots, steer full lock right, reverse full lock left, drive forward", "Any turn that gets you facing the other direction"], correctAnswer: 2, explanation: "Check all around first. Turn full lock to one side, reverse full lock to the other, then drive forward. Check carefully at each stage.", category: "Vehicle Handling" },
  { id: 442, question: "When might you need to use hazard warning lights while stationary?", options: ["When parked illegally", "When temporarily obstructing traffic, broken down, or on a dual carriageway warning of a hazard", "At all times when parked", "Only in car parks"], correctAnswer: 1, explanation: "Use hazard lights when your vehicle is stationary and temporarily obstructing traffic, or if broken down on the road.", category: "Signalling" },
  { id: 443, question: "What should you do if you skid on a wet manhole cover?", options: ["Brake hard", "Stay calm, ease off the accelerator and steer gently", "Accelerate", "Turn the steering wheel sharply"], correctAnswer: 1, explanation: "Wet manhole covers are very slippery. If you skid, stay calm, ease off the accelerator, and make gentle steering corrections.", category: "Vehicle Handling" },
  { id: 444, question: "What should you be aware of when driving near a playground?", options: ["Speed cameras", "Children who may run into the road unexpectedly", "Nothing special", "Parking restrictions only"], correctAnswer: 1, explanation: "Near playgrounds, children may chase balls or each other into the road without looking. Reduce speed and stay alert.", category: "Vulnerable Road Users" },
  { id: 445, question: "What is 'planned observation' in driving?", options: ["Checking your sat nav", "Looking well ahead and systematically scanning for hazards", "Only looking at road signs", "Checking your mirrors occasionally"], correctAnswer: 1, explanation: "Planned observation involves systematically scanning far ahead, the middle distance, and near the vehicle for potential hazards.", category: "Alertness" },
  { id: 446, question: "Why should you avoid coasting downhill?", options: ["It's faster", "You lose engine braking and have less control", "It saves fuel", "It wears the clutch"], correctAnswer: 1, explanation: "Coasting (driving in neutral or with the clutch down) removes engine braking, giving you less control over the vehicle.", category: "Vehicle Handling" },
  { id: 447, question: "What is a catalytic converter theft and why does it happen?", options: ["Theft of the engine", "Theft of the exhaust component containing precious metals", "Theft of the battery", "Theft of wheels"], correctAnswer: 1, explanation: "Catalytic converters contain precious metals (platinum, palladium, rhodium) making them targets for thieves.", category: "Vehicle Safety" },
  { id: 448, question: "What is the correct gap to leave when following a motorcycle?", options: ["Closer than for a car", "The same as for a car", "More than for a car — they can stop more quickly", "It doesn't matter"], correctAnswer: 2, explanation: "Leave more space than normal when following a motorcycle as they can stop more quickly than cars and are more vulnerable.", category: "Vulnerable Road Users" },
  { id: 449, question: "What is the purpose of Vehicle Excise Duty (road tax)?", options: ["To pay for road maintenance", "To contribute to general taxation and emissions-based charges", "To pay for your insurance", "To fund driving tests"], correctAnswer: 1, explanation: "Vehicle Excise Duty is a tax based on the vehicle's emissions. It contributes to general government revenue.", category: "Documents" },
  { id: 450, question: "What is an ANPR camera?", options: ["A speed camera", "Automatic Number Plate Recognition — reads and checks vehicle plates", "An accident camera", "A parking camera"], correctAnswer: 1, explanation: "ANPR cameras automatically read number plates and can check for untaxed, uninsured, or wanted vehicles.", category: "Documents" },

  // Additional questions 451-600 covering remaining gaps
  { id: 451, question: "What should you do if a tyre bursts while driving on a motorway?", options: ["Brake sharply", "Grip the steering wheel firmly, gently ease off the accelerator, and pull over", "Swerve to the hard shoulder", "Accelerate briefly"], correctAnswer: 1, explanation: "Keep a firm grip on the steering wheel, don't brake suddenly. Gently slow down and pull over to a safe place.", category: "Vehicle Handling" },
  { id: 452, question: "What is understeer?", options: ["The car turns more than expected", "The car turns less than expected despite steering input", "The car goes straight", "The car reverses unexpectedly"], correctAnswer: 1, explanation: "Understeer occurs when the front wheels lose grip and the car doesn't turn as much as you steer. Ease off the accelerator.", category: "Vehicle Handling" },
  { id: 453, question: "What is oversteer?", options: ["The car turns less than expected", "The rear of the car swings out causing the car to turn more than intended", "The car goes straight", "Too much use of the steering wheel"], correctAnswer: 1, explanation: "Oversteer occurs when the rear wheels lose grip and the back of the car swings out. Steer into the skid and ease off the accelerator.", category: "Vehicle Handling" },
  { id: 454, question: "What is the purpose of a parking sensor?", options: ["To find parking spaces", "To alert you to obstacles when parking by emitting beeps", "To park the car automatically", "To lock the car"], correctAnswer: 1, explanation: "Parking sensors detect obstacles behind or around the vehicle and emit beeps that increase in frequency as you get closer.", category: "Vehicle Safety" },
  { id: 455, question: "What is lane-keeping assist?", options: ["A GPS system", "A system that gently steers the car back if it starts to drift out of lane", "A mirror system", "A cruise control feature"], correctAnswer: 1, explanation: "Lane-keeping assist uses cameras to detect lane markings and gently steers the car back if it starts to drift.", category: "Vehicle Safety" },
  { id: 456, question: "How should you drive when approaching a pedestrian crossing with a central island?", options: ["Treat it as one crossing", "Treat each half as a separate crossing", "Ignore the island", "Speed up through it"], correctAnswer: 1, explanation: "Where a pedestrian crossing has a central island, treat each half as a separate crossing.", category: "Pedestrian Crossings" },
  { id: 457, question: "What is a staggered junction?", options: ["A junction with speed bumps", "A junction where side roads are not directly opposite each other", "A junction with no markings", "A roundabout"], correctAnswer: 1, explanation: "A staggered junction is where side roads are offset from each other. Take extra care as visibility may be restricted.", category: "Hazard Perception" },
  { id: 458, question: "Why should you avoid stopping on the zigzag lines near a school crossing?", options: ["It's a loading zone", "It blocks the view between drivers and children", "It's a cycle lane", "There's no reason to avoid it"], correctAnswer: 1, explanation: "Zigzag lines keep the area clear so that children and drivers can see each other clearly at the crossing.", category: "Vulnerable Road Users" },
  { id: 459, question: "What is a Variable Message Sign (VMS) on a motorway?", options: ["A permanent sign", "An electronic sign displaying current warnings, speed limits, or information", "A direction sign", "An advertising board"], correctAnswer: 1, explanation: "VMS are electronic signs that display real-time information about speed limits, lane closures, or hazards ahead.", category: "Motorway Rules" },
  { id: 460, question: "What should you do when being overtaken by another vehicle?", options: ["Speed up to prevent them", "Maintain your speed and keep to the left", "Brake sharply", "Move to the right"], correctAnswer: 1, explanation: "When being overtaken, maintain your speed and keep to the left. Don't speed up or try to prevent the overtake.", category: "Overtaking" },

  { id: 461, question: "Why should you not park facing against the flow of traffic at night?", options: ["It's only illegal on motorways", "Other drivers may be dazzled by your headlight reflectors", "It uses more fuel", "It makes no difference"], correctAnswer: 1, explanation: "Parking facing against the traffic flow means your headlight reflectors face approaching vehicles, potentially dazzling drivers.", category: "Lighting" },
  { id: 462, question: "What does 'IPSGA' stand for in advanced driving?", options: ["Information, Position, Speed, Gear, Accelerate", "Indicate, Park, Stop, Go, Accelerate", "Intersection, Proceed, Signal, Gear, Act", "None of these"], correctAnswer: 0, explanation: "IPSGA is the system of car control: Information, Position, Speed, Gear, Accelerate — used for every hazard.", category: "Vehicle Handling" },
  { id: 463, question: "What should you do when approaching a single-track road with passing places?", options: ["Speed up to reach the next passing place", "Drive slowly, be prepared to give way, and use passing places", "Sound your horn continuously", "Drive in the middle"], correctAnswer: 1, explanation: "On single-track roads, drive carefully, use passing places to let oncoming traffic pass, and give way to vehicles behind you.", category: "Vehicle Handling" },
  { id: 464, question: "What is the penalty for using a handheld mobile phone while driving?", options: ["A verbal warning", "6 points and £200 fine", "3 points and £100 fine", "No penalty"], correctAnswer: 1, explanation: "Using a handheld phone while driving results in 6 penalty points and a £200 fine. New drivers could lose their licence.", category: "Documents" },
  { id: 465, question: "What is the purpose of a chevron road marking?", options: ["To indicate parking", "To increase the distance between vehicles or separate traffic", "To mark bus lanes", "To indicate speed bumps"], correctAnswer: 1, explanation: "Chevron markings are used to separate traffic lanes or increase the gap between vehicles, often on approach to hazards.", category: "Traffic Signs" },
  { id: 466, question: "Why should you dip your headlights when following another vehicle?", options: ["To save battery", "To avoid dazzling the driver ahead through their mirrors", "It's only a suggestion", "To see the road better"], correctAnswer: 1, explanation: "Full beam headlights reflecting in the mirrors of the vehicle ahead can dazzle and distract the driver.", category: "Lighting" },
  { id: 467, question: "What precautions should you take when driving in autumn?", options: ["None needed", "Watch for wet leaves, low sun, early darkness, and frost", "Drive faster before dark", "Only check tyres"], correctAnswer: 1, explanation: "Autumn brings wet leaves (slippery), low sun (dazzle), early darkness, frost, and fog. Adjust your driving accordingly.", category: "Safety Margins" },
  { id: 468, question: "What is an advisory speed plate?", options: ["A speed limit you must follow", "A recommended safe speed for a hazard, usually shown under a warning sign", "A minimum speed requirement", "A speed camera warning"], correctAnswer: 1, explanation: "Advisory speed plates suggest a safe speed for approaching a hazard. They're rectangular and usually below a warning sign.", category: "Traffic Signs" },
  { id: 469, question: "How do you know if your anti-lock brakes are working?", options: ["The brakes feel normal", "You may feel the brake pedal pulsate when braking heavily", "A green light appears on the dashboard", "You can hear a clicking sound"], correctAnswer: 1, explanation: "When ABS activates, you may feel the brake pedal pulsate or vibrate. This is normal — keep pressing firmly.", category: "Vehicle Safety" },
  { id: 470, question: "What should you do before entering a one-way street?", options: ["Check it's safe and look for the correct entry sign", "Enter from any direction", "Sound your horn", "Flash your headlights"], correctAnswer: 0, explanation: "Check for the one-way street sign (a blue rectangle with a white arrow) and make sure you enter from the correct end.", category: "Traffic Signs" },

  { id: 471, question: "When can a learner driver legally drive on a motorway?", options: ["Never", "When accompanied by an approved driving instructor in a dual-control car", "After passing the theory test", "At any time with a supervising driver"], correctAnswer: 1, explanation: "Since 2018, learner drivers can drive on motorways when accompanied by an approved driving instructor in a dual-control car.", category: "Motorway Rules" },
  { id: 472, question: "What does a triangular sign showing two children mean?", options: ["Playground ahead", "School ahead — reduce speed and watch for children", "No children allowed", "Child crossing only"], correctAnswer: 1, explanation: "This warning sign indicates a school or children's area ahead. Reduce speed and be extremely cautious.", category: "Vulnerable Road Users" },
  { id: 473, question: "What should you do if you approach a flooded road?", options: ["Drive through at speed", "Assess the depth — don't enter if too deep, or drive slowly in a low gear", "Reverse away", "Wait for the water to recede"], correctAnswer: 1, explanation: "Assess if it's safe. If shallow enough, drive slowly in first gear. If too deep (above wheel centre), find another route.", category: "Safety Margins" },
  { id: 474, question: "What does a white arrow on the road pointing left mean?", options: ["Turn left only", "Keep left", "Left-hand lane", "Cycle lane"], correctAnswer: 0, explanation: "A white arrow on the road indicates the direction of traffic flow or a mandatory turn direction.", category: "Traffic Signs" },
  { id: 475, question: "What is the stopping distance formula?", options: ["Speed x 2", "Thinking distance + braking distance = overall stopping distance", "Speed x time", "Weight x speed"], correctAnswer: 1, explanation: "Overall stopping distance = thinking distance (reaction time x speed) + braking distance.", category: "Safety Margins" },
  { id: 476, question: "What colour reflective jacket should you wear if you break down on a motorway?", options: ["Red", "Blue", "High-visibility yellow or orange", "Any colour"], correctAnswer: 2, explanation: "Wear a high-visibility jacket so other road users can see you. This is especially important on motorways.", category: "Motorway Rules" },
  { id: 477, question: "What happens to stopping distances on a wet road?", options: ["They decrease", "They can at least double", "They stay the same", "They slightly increase"], correctAnswer: 1, explanation: "On wet roads, stopping distances can at least double because there is less grip between the tyres and the road.", category: "Safety Margins" },
  { id: 478, question: "What is 'POWDERY' driving conditions an acronym for?", options: ["Nothing specific", "A reminder to be cautious in cold weather", "Position, Observation, Weather, Direction, Everyone, Road surface, Your vehicle", "Proceed Only When Driving Easily Remains Yours"], correctAnswer: 2, explanation: "POWDERY reminds you to consider all factors affecting driving in poor conditions.", category: "Safety Margins" },
  { id: 479, question: "What should you do if a pedestrian steps onto a pelican crossing as the lights change to green?", options: ["Drive on as you have priority", "Give way — the pedestrian has the right to finish crossing", "Sound your horn", "Flash your headlights"], correctAnswer: 1, explanation: "Always give way to pedestrians who are still crossing, even if the lights have changed in your favour.", category: "Pedestrian Crossings" },
  { id: 480, question: "Why should you not reverse for longer than necessary?", options: ["It uses more fuel", "Reversing is more difficult to control and you have limited visibility", "It wears the tyres", "It doesn't matter how long you reverse"], correctAnswer: 1, explanation: "Reversing is inherently more dangerous — you have less control and limited visibility. Only reverse as far as necessary.", category: "Vehicle Handling" },

  // Final batch 481-600
  { id: 481, question: "What does the term 'road furniture' mean?", options: ["Roadside benches", "All fixed objects at the roadside including signs, bollards, and barriers", "Traffic cones only", "Bus shelters"], correctAnswer: 1, explanation: "Road furniture refers to all permanent features alongside the road — signs, barriers, bollards, lamp posts, etc.", category: "Traffic Signs" },
  { id: 482, question: "What is the most common cause of skidding?", options: ["Mechanical failure", "Driver error — too much speed, harsh braking, or acceleration", "Road surface", "Weather"], correctAnswer: 1, explanation: "Most skids are caused by the driver asking too much of the vehicle — excessive speed, harsh braking, or aggressive steering.", category: "Vehicle Handling" },
  { id: 483, question: "What should you do when following a gritting lorry?", options: ["Overtake it immediately", "Stay well behind as grit can be thrown up", "Drive close behind for benefit of the treated road", "Flash your headlights"], correctAnswer: 1, explanation: "Stay well behind a gritting lorry. Grit can hit your windscreen and the salt solution can reduce visibility.", category: "Other Vehicles" },
  { id: 484, question: "What is the difference between a filter lane and a slip road?", options: ["They are the same", "A filter lane is for turning at a junction; a slip road joins/leaves a motorway", "Filter lanes are only for buses", "Slip roads are for parking"], correctAnswer: 1, explanation: "Filter lanes allow traffic to turn at junctions without stopping main traffic. Slip roads are for joining/leaving motorways.", category: "Traffic Signs" },
  { id: 485, question: "Why is it important to dim your dashboard lights at night?", options: ["To save battery", "To reduce reflections and glare that can affect your night vision", "It makes no difference", "To look better"], correctAnswer: 1, explanation: "Bright dashboard lights can cause reflections on the windscreen and reduce your ability to see outside the vehicle at night.", category: "Lighting" },
  { id: 486, question: "What is the main danger when driving in strong winds on an exposed road?", options: ["Reduced fuel economy", "Being blown off course, especially high-sided vehicles", "Road surface damage", "Noise distraction"], correctAnswer: 1, explanation: "Strong crosswinds can push your vehicle off course, especially when driving on exposed bridges, hills, or past gaps in hedges.", category: "Safety Margins" },
  { id: 487, question: "What should you do if your engine overheats?", options: ["Pour cold water on the engine", "Stop safely, let it cool, then check coolant level", "Drive faster to cool it with airflow", "Ignore the warning light"], correctAnswer: 1, explanation: "Stop safely and let the engine cool down. Don't remove the radiator cap while hot. Check the coolant level once cool.", category: "Vehicle Safety" },
  { id: 488, question: "What is the difference between 'stopping' and 'parking'?", options: ["There is no difference", "Stopping is brief and the driver stays with the vehicle; parking means leaving the vehicle", "Parking is only in car parks", "Stopping is only at traffic lights"], correctAnswer: 1, explanation: "Stopping is a brief halt where you remain with the vehicle. Parking means leaving the vehicle, even for a short time.", category: "Traffic Signs" },
  { id: 489, question: "What are the risks of driving with worn shock absorbers?", options: ["No risks", "Reduced stability, longer stopping distances, and uneven tyre wear", "Better comfort", "Improved handling"], correctAnswer: 1, explanation: "Worn shock absorbers reduce vehicle stability, increase stopping distances, and cause uneven tyre wear, especially on bumpy roads.", category: "Vehicle Safety" },
  { id: 490, question: "What should you do when meeting oncoming vehicles on a narrow mountain road?", options: ["The vehicle going downhill should give way", "The vehicle going uphill should give way", "Neither needs to give way", "The larger vehicle has priority"], correctAnswer: 0, explanation: "Generally, the vehicle going downhill should give way to vehicles going uphill, as it's easier to stop and harder to restart on a hill.", category: "Attitude" },

  { id: 491, question: "What does a countdown marker with 3 diagonal bars mean?", options: ["Speed limit 30", "300 metres to the next motorway exit or level crossing", "3 miles to services", "3rd lane closing"], correctAnswer: 1, explanation: "Three diagonal bars indicate you are approximately 300 yards (about 270 metres) from a motorway exit or level crossing.", category: "Traffic Signs" },
  { id: 492, question: "What is the correct position for your mirrors before driving?", options: ["It doesn't matter", "Adjusted to give maximum view behind and to the sides with minimal head movement", "Pointing straight back", "Angled towards the road surface"], correctAnswer: 1, explanation: "Adjust all mirrors before driving so you have the best possible view behind and to the sides of your vehicle.", category: "Alertness" },
  { id: 493, question: "When should you cancel a signal?", options: ["Never", "As soon as you have completed the manoeuvre", "Only when turning right", "After 10 seconds"], correctAnswer: 1, explanation: "Cancel your signal as soon as you have completed the manoeuvre. A misleading signal is dangerous to other road users.", category: "Signalling" },
  { id: 494, question: "What is the purpose of road humps?", options: ["To test suspension", "To reduce vehicle speeds in residential areas", "To drain water", "To mark parking areas"], correctAnswer: 1, explanation: "Road humps are traffic calming measures designed to reduce vehicle speeds, particularly in residential areas near schools.", category: "Speed Limits" },
  { id: 495, question: "What should you do if your headlights fail while driving at night?", options: ["Continue driving using sidelights", "Stop in a safe place as soon as possible", "Use your fog lights instead", "Drive faster to reach your destination"], correctAnswer: 1, explanation: "If your headlights fail at night, slow down, use whatever lights you have, and stop in a safe place as soon as possible.", category: "Lighting" },
  { id: 496, question: "Why is it important to secure a child's car seat correctly?", options: ["To keep the car tidy", "An incorrectly fitted seat won't protect the child in a crash", "It's optional", "To prevent the child moving around"], correctAnswer: 1, explanation: "An incorrectly fitted child seat may not protect the child in an accident. Always follow the manufacturer's instructions carefully.", category: "Vehicle Safety" },
  { id: 497, question: "What is the correct way to adjust your seat before driving?", options: ["As far back as possible", "So you can reach all controls comfortably while being properly supported", "As close to the steering wheel as possible", "It doesn't matter"], correctAnswer: 1, explanation: "Adjust your seat so you can reach all controls comfortably, see clearly over the steering wheel, and your arms are slightly bent.", category: "Vehicle Safety" },
  { id: 498, question: "What does a 'shared space' road scheme mean?", options: ["Cars and buses share a lane", "An area designed to be shared equally between vehicles and pedestrians with minimal signage", "Carpooling lanes", "A pedestrian-only zone"], correctAnswer: 1, explanation: "Shared space schemes remove traditional barriers between vehicles and pedestrians, encouraging all users to share the road considerately.", category: "Attitude" },
  { id: 499, question: "What is the 'last safe moment' to cancel an overtake?", options: ["When you are alongside the other vehicle", "Before you have committed to moving into the opposite lane", "After you have passed them", "There is no last moment"], correctAnswer: 1, explanation: "The last safe moment to abort an overtake is before you have fully committed to the opposite lane. After that, continuing may be safer.", category: "Overtaking" },
  { id: 500, question: "What does a speed camera partnership sign look like?", options: ["A red circle", "A rectangular sign showing a camera symbol", "A triangular warning sign", "A blue square"], correctAnswer: 1, explanation: "Speed camera warning signs are rectangular and show a camera symbol. They warn that cameras may be operating in the area.", category: "Speed Limits" },

  // Final 100 questions (501-600)
  { id: 501, question: "What should you do when a police officer signals you to stop?", options: ["Ignore them if you're in a hurry", "Stop safely and follow their instructions", "Speed up", "Sound your horn"], correctAnswer: 1, explanation: "You must obey signals from police officers. Pull over safely and follow their instructions.", category: "Attitude" },
  { id: 502, question: "What is the benefit of eco-friendly driving?", options: ["It's slower", "It saves money on fuel, reduces emissions, and can reduce accident risk", "It wears the engine out", "No benefit"], correctAnswer: 1, explanation: "Eco-driving saves money, reduces harmful emissions, and the smoother driving style can actually reduce accident risk.", category: "Environmental Issues" },
  { id: 503, question: "How should you signal at a spiral roundabout?", options: ["No signal needed", "Follow the road markings and signal according to which exit you're taking", "Signal left at all times", "Signal right at all times"], correctAnswer: 1, explanation: "On spiral roundabouts, follow the lane markings. Signal appropriately for your exit — left to leave, right to stay on.", category: "Roundabouts" },
  { id: 504, question: "What is the correct procedure at a Give Way sign?", options: ["You must stop completely", "Slow down and give way to traffic on the main road", "You have priority", "Sound your horn and proceed"], correctAnswer: 1, explanation: "At a Give Way sign, slow down and be prepared to stop. Give way to traffic on the road you're joining.", category: "Traffic Signs" },
  { id: 505, question: "What is the meaning of a flashing blue light without a siren?", options: ["No urgency", "Emergency vehicle approaching — still give way", "Police vehicle only", "Breakdown truck"], correctAnswer: 1, explanation: "An emergency vehicle may use blue lights without a siren (e.g., near hospitals). You should still give way.", category: "Hazard Perception" },
  { id: 506, question: "When is it legal to drive on the pavement?", options: ["When the road is blocked", "To access a driveway", "Never — unless accessing private property with proper vehicle access", "At any time in an emergency"], correctAnswer: 2, explanation: "Driving on the pavement is generally illegal. The exception is to access a proper vehicle crossing to reach private property.", category: "Attitude" },
  { id: 507, question: "What should you do if you see a mobility scooter on the road?", options: ["Sound your horn", "Treat it as a slow-moving vehicle — overtake carefully", "Ignore it", "Flash your headlights"], correctAnswer: 1, explanation: "Mobility scooters can legally use the road. Be patient, give them room, and overtake only when safe.", category: "Vulnerable Road Users" },
  { id: 508, question: "What is the main risk of using cruise control in wet conditions?", options: ["It makes the car go faster", "You may not react quickly enough if the car aquaplanes", "It doesn't work in rain", "No risk"], correctAnswer: 1, explanation: "On wet roads, cruise control can delay your reaction to aquaplaning. It's safer to control your speed manually.", category: "Vehicle Handling" },
  { id: 509, question: "What is the correct procedure for a left reverse around a corner?", options: ["Speed in reverse", "Check all around, reverse slowly, keep close to the kerb, check mirrors and blind spots throughout", "No checks needed", "Signal right while reversing left"], correctAnswer: 1, explanation: "Observe all around before starting. Reverse slowly, keeping reasonably close to the kerb, and continue checking mirrors and blind spots.", category: "Vehicle Handling" },
  { id: 510, question: "What should you do if you witness a road rage incident?", options: ["Get involved", "Note the details and report to the police safely", "Ignore it completely", "Film it while driving"], correctAnswer: 1, explanation: "Don't get involved. Note vehicle details, time, and location, and report it to the police when safe to do so.", category: "Attitude" },

  { id: 511, question: "What is a contraflow bus lane?", options: ["A bus lane going the same direction as traffic", "A bus lane flowing in the opposite direction to other traffic", "A cycle lane", "A bus stop"], correctAnswer: 1, explanation: "A contraflow bus lane runs in the opposite direction to the general traffic flow. Watch out for buses coming towards you.", category: "Traffic Signs" },
  { id: 512, question: "What should you do when turning right at traffic lights with a green filter arrow pointing right?", options: ["Wait for the main green light", "You may proceed in the direction of the arrow", "Give way to oncoming traffic", "Stop"], correctAnswer: 1, explanation: "A green filter arrow means you can proceed in that direction regardless of other traffic signals.", category: "Traffic Signs" },
  { id: 513, question: "How does driving with correctly inflated tyres help the environment?", options: ["It doesn't help", "Correctly inflated tyres reduce rolling resistance, using less fuel and producing fewer emissions", "Only winter tyres matter", "It only helps tyre life"], correctAnswer: 1, explanation: "Correct tyre pressures reduce rolling resistance, improving fuel efficiency and therefore reducing CO2 emissions.", category: "Environmental Issues" },
  { id: 514, question: "What should you be aware of when driving near a cycling event?", options: ["Nothing special", "Large groups of cyclists may be on the road — give them plenty of room", "They should be on cycle paths", "Sound your horn to warn them"], correctAnswer: 1, explanation: "During cycling events, large groups of riders may use the road. Be patient, slow down, and give them plenty of room.", category: "Vulnerable Road Users" },
  { id: 515, question: "What does the 'dead man's curve' refer to in driving?", options: ["A type of road surface", "A particularly dangerous bend where accidents frequently occur", "A racing technique", "A driving test manoeuvre"], correctAnswer: 1, explanation: "This term refers to bends known to be accident hotspots, often due to excessive speed or poor visibility.", category: "Hazard Perception" },
  { id: 516, question: "Why should you avoid driving with headphones on?", options: ["It's uncomfortable", "They prevent you from hearing sirens, horns, and other important sounds", "They make your ears cold", "No reason to avoid it"], correctAnswer: 1, explanation: "Wearing headphones while driving prevents you from hearing emergency vehicles, horns, and other audible warnings.", category: "Alertness" },
  { id: 517, question: "What is the purpose of a pedestrian guardrail?", options: ["To stop cars", "To guide pedestrians to safe crossing points", "To support road signs", "To mark parking spaces"], correctAnswer: 1, explanation: "Pedestrian guardrails direct pedestrians to designated crossing points, preventing them from crossing at dangerous locations.", category: "Vulnerable Road Users" },
  { id: 518, question: "What does 'defensive positioning' mean on the road?", options: ["Driving aggressively", "Positioning your vehicle to maximise visibility and safety margins", "Parking defensively", "Driving in the centre of the road"], correctAnswer: 1, explanation: "Defensive positioning means placing your vehicle where you have the best view, are most visible, and have the greatest safety margins.", category: "Attitude" },
  { id: 519, question: "When should you check your brake lights?", options: ["Never", "Regularly — have someone watch while you press the brake pedal", "Only at MOT time", "They are maintenance-free"], correctAnswer: 1, explanation: "Check brake lights regularly by having someone watch from behind while you press the brake pedal, or check the reflection.", category: "Vehicle Safety" },
  { id: 520, question: "What is the main advantage of driving an electric vehicle?", options: ["Higher speed", "Zero tailpipe emissions and lower running costs", "Better sound system", "More boot space"], correctAnswer: 1, explanation: "Electric vehicles produce zero tailpipe emissions, have lower fuel costs, and generally have lower maintenance costs.", category: "Environmental Issues" },

  { id: 521, question: "What is a pelican crossing's unique feature compared to other crossings?", options: ["It has no lights", "It has a flashing amber phase where you give way to pedestrians still crossing", "It detects cyclists", "It has barriers"], correctAnswer: 1, explanation: "The pelican crossing is unique in having a flashing amber phase between red and green, where you must give way to pedestrians still crossing.", category: "Pedestrian Crossings" },
  { id: 522, question: "Why is it important not to overload your vehicle?", options: ["It scratches the paint", "It affects handling, braking, and is illegal if over the permitted weight", "It uses less fuel", "It only matters for commercial vehicles"], correctAnswer: 1, explanation: "Overloading affects braking, steering, stability, and can cause tyre failure. It's also illegal if you exceed the vehicle's weight limit.", category: "Vehicle Safety" },
  { id: 523, question: "What should you do when approaching a sign showing 'Road narrows on both sides'?", options: ["Speed up to get through", "Slow down and be prepared to give way", "Sound your horn", "Move to the centre of the road"], correctAnswer: 1, explanation: "Slow down and be prepared to give way to oncoming vehicles. The road is narrowing and there may not be room for two vehicles.", category: "Traffic Signs" },
  { id: 524, question: "What is the maximum permitted blood alcohol level in England and Wales?", options: ["50 mg per 100 ml", "80 mg per 100 ml", "100 mg per 100 ml", "Zero"], correctAnswer: 1, explanation: "The maximum blood alcohol level in England and Wales is 80 milligrams of alcohol per 100 millilitres of blood.", category: "Drink Driving" },
  { id: 525, question: "What should you do if you see a vehicle with an amber rotating beacon?", options: ["Give way immediately", "Be aware it's a slow-moving or potentially hazardous vehicle", "Ignore it", "Overtake immediately"], correctAnswer: 1, explanation: "Amber beacons indicate slow-moving, stationary, or potentially hazardous vehicles. Be cautious when passing.", category: "Other Vehicles" },
  { id: 526, question: "What is the safest way to carry a surfboard on your car?", options: ["Sticking out of the window", "Securely strapped to a roof rack with a warning flag if overhanging", "Tied to the door handle", "On the front seat"], correctAnswer: 1, explanation: "Use a proper roof rack with secure straps. If the load overhangs, attach a bright warning flag visible from behind.", category: "Vehicle Safety" },
  { id: 527, question: "What does a road sign with a white circle and red border containing '30' mean?", options: ["Minimum speed 30 mph", "Maximum speed 30 mph", "Recommended speed 30 mph", "Average speed 30 mph"], correctAnswer: 1, explanation: "A white circle with a red border and the number 30 means the maximum speed limit is 30 mph.", category: "Speed Limits" },
  { id: 528, question: "When is it acceptable to exceed the speed limit?", options: ["In an emergency", "When overtaking", "Never", "When following an emergency vehicle"], correctAnswer: 2, explanation: "It is never acceptable to exceed the speed limit. Even emergency situations do not legally permit speeding.", category: "Speed Limits" },
  { id: 529, question: "What does the 'freeze, flight, or fight' response mean for pedestrians?", options: ["A crossing type", "People may freeze in the road, run unpredictably, or try to dodge — be prepared for all", "A traffic light sequence", "A parking manoeuvre"], correctAnswer: 1, explanation: "When startled, pedestrians may freeze in place, run unpredictably, or try to dodge your vehicle. Be prepared for all reactions.", category: "Vulnerable Road Users" },
  { id: 530, question: "What should you do if your sat nav tells you to make an illegal turn?", options: ["Follow the sat nav", "Ignore the sat nav and follow road signs and rules", "Stop and wait", "Turn when no one is watching"], correctAnswer: 1, explanation: "Road signs and traffic laws always take priority over sat nav instructions. If the sat nav gives an illegal direction, ignore it.", category: "Alertness" },

  { id: 531, question: "What is the purpose of chevrons painted on the road in a tunnel?", options: ["To show parking areas", "To help maintain safe following distance", "To mark emergency exits", "To show speed limits"], correctAnswer: 1, explanation: "Chevrons in tunnels help you maintain a safe following distance. Keep at least two chevrons between you and the vehicle ahead.", category: "Safety Margins" },
  { id: 532, question: "What should you do if you need to use a hand-held phone urgently while driving?", options: ["Use it quickly", "Pull over safely and stop before using the phone", "Use it at traffic lights", "Have a passenger call for you"], correctAnswer: 1, explanation: "You must find a safe place to stop before using a hand-held phone. Using it while driving is illegal and dangerous.", category: "Alertness" },
  { id: 533, question: "What does a sign showing an airplane mean?", options: ["Airport ahead", "Low-flying aircraft — beware of sudden noise", "Helicopter landing", "Aviation fuel available"], correctAnswer: 0, explanation: "This sign indicates the direction to an airport.", category: "Traffic Signs" },
  { id: 534, question: "What should you do if you're on a motorway and realise you are going the wrong way?", options: ["Do a U-turn", "Reverse on the hard shoulder", "Continue to the next junction and find an alternative route", "Stop and check your map"], correctAnswer: 2, explanation: "Never reverse, do U-turns, or stop on a motorway. Continue to the next junction and use it to correct your route.", category: "Motorway Rules" },
  { id: 535, question: "Why should you not accelerate harshly when moving off?", options: ["It sounds bad", "It wastes fuel, wears tyres, and can be dangerous in slippery conditions", "It doesn't matter", "It's only a problem for new drivers"], correctAnswer: 1, explanation: "Harsh acceleration wastes fuel, causes excessive tyre wear, and can cause wheel spin, especially in wet or icy conditions.", category: "Environmental Issues" },
  { id: 536, question: "What is the purpose of a vehicle immobiliser?", options: ["To improve fuel economy", "To prevent the vehicle from being started without the correct key or fob", "To limit speed", "To record mileage"], correctAnswer: 1, explanation: "An immobiliser is an electronic security device that prevents the engine from starting without the correct key or fob.", category: "Vehicle Safety" },
  { id: 537, question: "What should you do when approaching a bridge with a weight limit sign?", options: ["Cross if your vehicle looks light enough", "Check your vehicle's weight against the limit — do not cross if you exceed it", "Ignore the sign for cars", "Only applies to lorries"], correctAnswer: 1, explanation: "Weight limit signs apply to all vehicles. Check your vehicle's weight including load and don't cross if you exceed the limit.", category: "Traffic Signs" },
  { id: 538, question: "When driving in a convoy, what should you do?", options: ["Stay close together", "Leave enough space for other vehicles to overtake and join safely", "Match the leader's speed exactly", "Use hazard lights"], correctAnswer: 1, explanation: "When driving in a group, leave enough space between vehicles for others to overtake safely and join the road.", category: "Attitude" },
  { id: 539, question: "What is the benefit of advanced stop lines for cyclists at traffic lights?", options: ["They slow down traffic", "They give cyclists a head start and make them more visible to drivers", "They are for buses", "They have no purpose"], correctAnswer: 1, explanation: "Advanced stop lines give cyclists a safe waiting area ahead of traffic, making them more visible and giving them a head start.", category: "Vulnerable Road Users" },
  { id: 540, question: "What is the main difference between a dual carriageway and a motorway?", options: ["Speed limits", "Motorways have restricted access and no roundabouts, crossroads, or traffic lights", "Road surface", "Number of lanes"], correctAnswer: 1, explanation: "Motorways have restricted access (no roundabouts, crossroads, or slow vehicles), whereas dual carriageways may have these features.", category: "Motorway Rules" },

  { id: 541, question: "How can you check your power steering is working before driving?", options: ["Rev the engine", "Turn the steering wheel slightly with the engine running — it should feel light", "Check the fluid level only", "Push the car to see if it moves"], correctAnswer: 1, explanation: "With the engine running, the steering should feel light and easy to turn. Heavy steering may indicate a power steering problem.", category: "Vehicle Safety" },
  { id: 542, question: "What should you do if an ambulance is behind you with blue lights flashing?", options: ["Speed up", "Stop immediately", "Pull over safely when you can, without endangering others", "Ignore it on dual carriageways"], correctAnswer: 2, explanation: "Check mirrors, signal left, and pull over safely when there is room. Don't mount the kerb, run red lights, or panic.", category: "Attitude" },
  { id: 543, question: "What is the danger of driving too slowly on a motorway?", options: ["No danger", "You could cause an obstruction and other vehicles to brake or swerve", "It saves fuel", "It's safer"], correctAnswer: 1, explanation: "Driving significantly below the flow of traffic can be dangerous, causing other vehicles to brake suddenly or make unsafe lane changes.", category: "Motorway Rules" },
  { id: 544, question: "Why should you not fill your fuel tank when a tanker is delivering fuel?", options: ["The fuel is contaminated", "Sediment may be stirred up from the bottom of the tank, which could enter your vehicle", "The prices are higher", "It's illegal"], correctAnswer: 1, explanation: "When fuel is being delivered, sediment from the bottom of the underground tank can be disturbed, potentially blocking your fuel filter.", category: "Vehicle Safety" },
  { id: 545, question: "What does 'mechanical sympathy' mean in driving?", options: ["Feeling sorry for your car", "Driving smoothly to reduce wear on vehicle components", "Only driving new cars", "Using premium fuel"], correctAnswer: 1, explanation: "Mechanical sympathy means driving in a way that minimises wear and stress on the vehicle — smooth gear changes, gentle braking, etc.", category: "Vehicle Handling" },
  { id: 546, question: "What is the correct gap when stopping behind another vehicle in traffic?", options: ["As close as possible", "Far enough to see the bottom of their rear tyres touching the road", "One car length", "Any distance"], correctAnswer: 1, explanation: "The 'tyres and tarmac' rule: stop far enough back to see where the tyres of the vehicle ahead meet the road. This gives room to move if needed.", category: "Safety Margins" },
  { id: 547, question: "When should you check your mirror twice before changing lanes?", options: ["Never", "Always — double-check to catch any vehicle that may have moved into your blind spot", "Only on motorways", "Only when turning right"], correctAnswer: 1, explanation: "Always check mirrors twice before changing lanes. A vehicle could have moved into your blind spot between your first and second check.", category: "Alertness" },
  { id: 548, question: "What is the correct way to handle a car with rear-wheel drive on icy roads?", options: ["Same as any car", "Be extra cautious as the rear can slide out more easily under acceleration", "Drive only in first gear", "Use the handbrake frequently"], correctAnswer: 1, explanation: "Rear-wheel drive vehicles can be more prone to oversteer on icy roads. Accelerate gently and steer smoothly.", category: "Vehicle Handling" },
  { id: 549, question: "What should you do before making a U-turn?", options: ["Signal right and go", "Check it's legal, check all mirrors and blind spots, and ensure the road is clear in both directions", "Sound your horn", "Only check the left mirror"], correctAnswer: 1, explanation: "Ensure U-turns are legal, check all mirrors and blind spots, and only proceed when the road is completely clear in both directions.", category: "Vehicle Handling" },
  { id: 550, question: "What is the purpose of an Automatic Emergency Braking system?", options: ["To park the car", "To detect potential collisions and apply the brakes automatically if the driver doesn't react", "To maintain speed", "To change gears"], correctAnswer: 1, explanation: "AEB systems detect potential collisions and automatically apply the brakes if the driver fails to react, reducing impact severity.", category: "Vehicle Safety" },

  { id: 551, question: "What should you do if your windscreen wipers stop working in heavy rain?", options: ["Continue driving carefully", "Stop in a safe place as soon as possible", "Lean out of the window", "Use your hands to clear the screen"], correctAnswer: 1, explanation: "Without working wipers in rain, your visibility is dangerously reduced. Stop safely and don't continue until they're fixed.", category: "Vehicle Safety" },
  { id: 552, question: "What is the correct procedure for driving through an automated car wash?", options: ["Leave the engine running in gear", "Put the car in neutral, keep the engine running, and follow instructions", "Turn the engine off", "Leave the windows open"], correctAnswer: 1, explanation: "Follow the car wash instructions. Usually put in neutral with the engine running, and keep windows and sunroof closed.", category: "Vehicle Safety" },
  { id: 553, question: "When approaching a herd of cattle on the road, what should you do?", options: ["Sound your horn to move them", "Stop, be patient, and wait for them to pass", "Drive through slowly", "Reverse and find another route"], correctAnswer: 1, explanation: "Stop and wait for the cattle to pass. Do not sound your horn or rev your engine as this may frighten them.", category: "Vulnerable Road Users" },
  { id: 554, question: "What is 'planned driving'?", options: ["Only driving to planned destinations", "Thinking and planning ahead to deal with hazards before they become emergencies", "Following a sat nav", "Planning your route in advance"], correctAnswer: 1, explanation: "Planned driving means thinking ahead, anticipating hazards, and having a plan to deal with situations before they become critical.", category: "Attitude" },
  { id: 555, question: "What is the legal requirement for mirrors on a car?", options: ["One interior mirror only", "At least one exterior mirror and one interior mirror", "Two exterior mirrors", "At least two mirrors providing an adequate view to the rear"], correctAnswer: 3, explanation: "A vehicle must have at least two mirrors providing an adequate view of the road behind. Usually one interior and one exterior.", category: "Vehicle Safety" },
  { id: 556, question: "What effect does a dirty windscreen have on driving?", options: ["No effect", "It can cause dazzle from sun or headlights and reduce visibility", "It only affects appearance", "It makes wipers work better"], correctAnswer: 1, explanation: "A dirty windscreen causes glare from sunlight and headlights, reduces visibility, and makes it harder to spot hazards.", category: "Vehicle Safety" },
  { id: 557, question: "Why should you be cautious when driving near parked ice cream vans?", options: ["The music is distracting", "Children may run into the road excitedly", "They block your view", "They slow traffic"], correctAnswer: 1, explanation: "Children are often excited around ice cream vans and may run across the road without looking. Slow down and be very alert.", category: "Vulnerable Road Users" },
  { id: 558, question: "What is the best approach when reversing into a parking space?", options: ["Reverse quickly before someone takes the space", "Observe carefully, reverse slowly, and be prepared to stop at any time", "Reverse without looking if the space is clear", "Ask someone to guide you every time"], correctAnswer: 1, explanation: "Always observe carefully before and during reversing. Go slowly and be prepared to stop if a pedestrian or vehicle appears.", category: "Vehicle Handling" },
  { id: 559, question: "What is the legal requirement for vehicle registration plates?", options: ["Any colour is acceptable", "White at the front, yellow at the rear, with the correct format", "Both plates the same colour", "Only one plate is required"], correctAnswer: 1, explanation: "UK vehicles must display a white front plate and yellow rear plate with the registration in the correct format.", category: "Documents" },
  { id: 560, question: "What should you do if your exhaust system is blowing?", options: ["Ignore it", "Have it repaired as it increases noise pollution and may affect emissions", "Only fix it at MOT time", "It improves performance"], correctAnswer: 1, explanation: "A blowing exhaust increases noise pollution, can increase harmful emissions, and may fail the MOT. Have it repaired promptly.", category: "Environmental Issues" },

  { id: 561, question: "What is the purpose of 'traffic calming' in residential areas?", options: ["To annoy drivers", "To reduce vehicle speeds and improve safety for residents", "To create traffic jams", "To prevent parking"], correctAnswer: 1, explanation: "Traffic calming measures like humps, chicanes, and 20 mph zones are designed to reduce speeds and make areas safer.", category: "Speed Limits" },
  { id: 562, question: "When should you use the handbrake during normal driving?", options: ["At all traffic lights", "When stopped for more than a few moments, especially on hills", "Only when parking", "Never while driving"], correctAnswer: 1, explanation: "Use the handbrake when you expect to be stationary for more than a moment, especially on hills, to prevent rolling.", category: "Vehicle Handling" },
  { id: 563, question: "What is the benefit of a hands-free phone kit while driving?", options: ["It is completely safe", "It is legal but still distracting — you should minimise use", "It is as dangerous as hand-held", "There is no benefit"], correctAnswer: 1, explanation: "While legal, hands-free phones are still distracting. The conversation itself takes attention from driving. Keep calls brief.", category: "Alertness" },
  { id: 564, question: "Why is tailgating particularly dangerous on wet roads?", options: ["It's only dangerous on dry roads", "Stopping distances at least double in wet conditions, leaving no room to stop", "It improves visibility in spray", "It reduces fuel consumption"], correctAnswer: 1, explanation: "On wet roads, stopping distances at least double. Tailgating means you have no chance of stopping if the vehicle ahead brakes.", category: "Safety Margins" },
  { id: 565, question: "What should you do if you feel car sick while driving?", options: ["Continue driving", "Stop safely, get fresh air, and don't drive until you feel well", "Drive faster", "Open the window and continue"], correctAnswer: 1, explanation: "If you feel unwell, stop safely. Driving while feeling sick can impair your concentration and reaction times.", category: "Alertness" },
  { id: 566, question: "What is the risk of parking your car on soft ground?", options: ["No risk", "The car may sink and become stuck, and could roll if on a slope", "It improves grip", "It's better for the tyres"], correctAnswer: 1, explanation: "Soft ground can cause your vehicle to sink and become stuck. On slopes, it may not provide adequate grip to prevent rolling.", category: "Vehicle Handling" },
  { id: 567, question: "What is the correct action when you see a green arrow traffic filter light?", options: ["You must wait for the main green light", "You can proceed in the direction of the arrow if it's safe", "It means stop", "It's for pedestrians only"], correctAnswer: 1, explanation: "A green filter arrow means you may proceed in the direction shown, even if the main light is red, provided it's safe.", category: "Traffic Signs" },
  { id: 568, question: "How should you approach a tunnel while driving?", options: ["Speed up to get through quickly", "Remove sunglasses, turn on headlights, and obey the speed limit", "Turn off all lights", "Close all windows and air vents"], correctAnswer: 1, explanation: "Remove sunglasses, switch on dipped headlights, observe the speed limit, and maintain a safe following distance.", category: "Hazard Perception" },
  { id: 569, question: "What does 'pass plus' involve?", options: ["An advanced driving test", "Additional training for new drivers covering motorways, night driving, and more", "A type of car insurance", "A parking course"], correctAnswer: 1, explanation: "Pass Plus is a voluntary scheme for new drivers that provides experience in motorway driving, night driving, bad weather, and more.", category: "Documents" },
  { id: 570, question: "What should you do if a warning light you don't recognise comes on?", options: ["Ignore it", "Check your vehicle handbook and seek advice if necessary", "Keep driving and hope it goes off", "Cover it with tape"], correctAnswer: 1, explanation: "Refer to your vehicle's handbook to identify the warning light. If you're unsure, have the vehicle checked by a professional.", category: "Vehicle Safety" },

  { id: 571, question: "What is the purpose of variable speed limits on smart motorways?", options: ["To catch speeding drivers", "To manage traffic flow and reduce congestion and accidents", "To test new speed cameras", "They are optional"], correctAnswer: 1, explanation: "Variable speed limits smooth traffic flow, reduce stop-start driving, and decrease the chance of congestion and accidents.", category: "Motorway Rules" },
  { id: 572, question: "What precautions should you take when parking on a hill facing uphill?", options: ["Leave in neutral", "Turn wheels away from the kerb, engage handbrake and put in a forward gear", "Leave in reverse gear", "No special precautions"], correctAnswer: 1, explanation: "Turn wheels away from the kerb (so the car rolls into it if it moves), engage handbrake, and leave in first gear.", category: "Vehicle Handling" },
  { id: 573, question: "What precautions should you take when parking on a hill facing downhill?", options: ["Leave in neutral", "Turn wheels towards the kerb, engage handbrake and put in reverse gear", "No special precautions", "Leave in first gear"], correctAnswer: 1, explanation: "Turn wheels towards the kerb (so the car rolls into it if it moves), engage handbrake, and leave in reverse gear.", category: "Vehicle Handling" },
  { id: 574, question: "Why should you check the weather forecast before a long journey?", options: ["To decide what to wear", "To prepare for adverse conditions and consider if the journey is necessary", "It makes no difference to driving", "Only in winter"], correctAnswer: 1, explanation: "Checking the weather helps you prepare for conditions, adjust your route or timing, and decide if the journey is essential.", category: "Safety Margins" },
  { id: 575, question: "What is the main purpose of a driving licence?", options: ["To prove your identity", "To show you have passed the required tests and are legally permitted to drive", "To avoid fines", "To get car insurance"], correctAnswer: 1, explanation: "A driving licence proves you have met the legal requirements (age, tests, health) to drive on public roads.", category: "Documents" },
  { id: 576, question: "What should you do if your fuel gauge shows nearly empty on a motorway?", options: ["Drive faster to reach the next services", "Exit at the next junction or services — don't risk running out", "Turn off the engine and coast", "Pull over on the hard shoulder"], correctAnswer: 1, explanation: "Leave the motorway at the next exit or pull into services. Running out of fuel on a motorway is dangerous.", category: "Motorway Rules" },
  { id: 577, question: "Why might a cyclist look over their right shoulder?", options: ["They're lost", "They may be about to turn right or change position — be prepared for them to move", "They want to chat", "No particular reason"], correctAnswer: 1, explanation: "A cyclist looking over their right shoulder is likely preparing to turn right or move to a different position in the road. Be prepared.", category: "Vulnerable Road Users" },
  { id: 578, question: "When is the road surface most slippery in winter?", options: ["Midday", "In early morning and late evening when frost forms", "In strong wind", "Only in snow"], correctAnswer: 1, explanation: "Road surfaces are most slippery in early morning and late evening when temperatures drop and frost or ice forms.", category: "Safety Margins" },
  { id: 579, question: "What does 'secondary safety' mean in vehicle design?", options: ["Backup brakes", "Features that protect occupants during a crash (airbags, crumple zones)", "Spare tyre", "Second seatbelt"], correctAnswer: 1, explanation: "Secondary safety features (passive safety) protect occupants during a collision — airbags, crumple zones, seatbelt pretensioners.", category: "Vehicle Safety" },
  { id: 580, question: "What is the main danger of parking opposite another parked vehicle on a narrow road?", options: ["It looks untidy", "It narrows the road and may prevent other vehicles from passing", "It's only a problem at night", "No danger"], correctAnswer: 1, explanation: "Parking opposite another vehicle on a narrow road can create a gap too narrow for traffic to pass safely.", category: "Attitude" },

  { id: 581, question: "What does a road sign with a picture of a car and motorbike side by side with a red X mean?", options: ["No motorcycles", "No motor vehicles", "No overtaking", "No entry"], correctAnswer: 1, explanation: "This sign means no motor vehicles are allowed on this road.", category: "Traffic Signs" },
  { id: 582, question: "What should you do if your anti-lock brakes activate?", options: ["Release the brake immediately", "Keep pressing the brake pedal firmly and steer as needed", "Pump the brake pedal", "Turn off the engine"], correctAnswer: 1, explanation: "When ABS activates, keep firm pressure on the brake pedal. You may feel pulsation — this is normal. Steer to avoid the hazard.", category: "Vehicle Safety" },
  { id: 583, question: "What is the main benefit of electric power steering over hydraulic?", options: ["More feedback", "It is more fuel-efficient as it only uses energy when steering", "It is heavier", "It provides better grip"], correctAnswer: 1, explanation: "Electric power steering only uses energy when you turn the wheel, improving fuel efficiency compared to hydraulic systems.", category: "Environmental Issues" },
  { id: 584, question: "When approaching a zebra crossing with no one waiting, should you still be prepared to stop?", options: ["No, drive at normal speed", "Yes — a pedestrian could step onto it at any time", "Only if you see children nearby", "Only in school hours"], correctAnswer: 1, explanation: "Always be prepared to stop at a zebra crossing. Pedestrians can step onto it at any time and you must give way.", category: "Pedestrian Crossings" },
  { id: 585, question: "What should you do if you find yourself in the wrong lane at a roundabout?", options: ["Cut across other traffic", "Continue in your lane and take the next exit, then go around again", "Stop and wait", "Reverse back"], correctAnswer: 1, explanation: "If in the wrong lane, don't suddenly change lanes. Continue safely, take the next exit, and go around the roundabout again.", category: "Roundabouts" },
  { id: 586, question: "What is the risk of leaving your engine running when stationary?", options: ["No risk", "Unnecessary emissions, fuel waste, and potential theft risk", "It keeps the battery charged", "It's better for the engine"], correctAnswer: 1, explanation: "Idling wastes fuel, produces unnecessary emissions, and makes your vehicle a theft target. Switch off if stationary for long.", category: "Environmental Issues" },
  { id: 587, question: "What should you do if you arrive at a railway level crossing and the barriers are coming down?", options: ["Try to drive through quickly", "Stop and wait at the barrier", "Reverse onto the crossing", "Sound your horn"], correctAnswer: 1, explanation: "Stop well before the barrier and wait. Never try to drive around or under barriers at a level crossing.", category: "Hazard Perception" },
  { id: 588, question: "How do speed humps affect emergency vehicles?", options: ["They don't affect them", "They slow emergency response times and can damage vehicles", "They speed them up", "Emergency vehicles can ignore them"], correctAnswer: 1, explanation: "Speed humps can slow emergency vehicles and cause damage. However, they are placed where the safety benefit outweighs this concern.", category: "Speed Limits" },
  { id: 589, question: "What is the proper way to check your blind spot?", options: ["Just use mirrors", "Briefly turn your head to look over your shoulder in the direction you plan to move", "Lean out of the window", "Use a rear-view camera only"], correctAnswer: 1, explanation: "Briefly turn your head to look over the relevant shoulder. This checks the area your mirrors cannot cover.", category: "Alertness" },
  { id: 590, question: "What is 'creep and peep' at a junction?", options: ["A dance move", "Slowly moving forward to improve your view when vision is blocked", "Driving through without looking", "A reversing technique"], correctAnswer: 1, explanation: "When your view at a junction is blocked, slowly edge forward (creep) while looking carefully (peep) until you can see clearly.", category: "Vehicle Handling" },

  { id: 591, question: "What is the legal requirement for carrying a warning triangle in the UK?", options: ["Mandatory", "Not legally required but recommended", "Only on motorways", "Only for commercial vehicles"], correctAnswer: 1, explanation: "A warning triangle is not a legal requirement in the UK, but it is strongly recommended. Never use one on a motorway.", category: "Vehicle Safety" },
  { id: 592, question: "What should you do if you accidentally enter a one-way street the wrong way?", options: ["Continue and hope for the best", "Stop safely and reverse out if it's safe to do so", "Speed through", "Sound your horn continuously"], correctAnswer: 1, explanation: "Stop safely and carefully reverse out if it's safe, or find a safe place to turn around. Do not continue the wrong way.", category: "Vehicle Handling" },
  { id: 593, question: "Why should you allow extra room when passing a bin lorry?", options: ["They smell", "Workers may step into the road, and the vehicle stops frequently", "They drive fast", "No reason"], correctAnswer: 1, explanation: "Refuse collectors may step into the road and the lorry makes frequent stops. Allow extra room and be prepared to slow down.", category: "Other Vehicles" },
  { id: 594, question: "What does a triangular sign with a red border showing two bumps mean?", options: ["Rumble strip", "Speed bumps ahead", "Road surface change", "Uneven road"], correctAnswer: 3, explanation: "This sign warns of an uneven road surface ahead. Slow down and be prepared for the vehicle to bounce.", category: "Traffic Signs" },
  { id: 595, question: "What is the benefit of using cruise control on a motorway?", options: ["You don't need to watch the road", "It helps maintain a steady speed, reducing fuel consumption", "It allows you to sleep", "There is no benefit"], correctAnswer: 1, explanation: "Cruise control helps maintain a steady speed on open roads, which can improve fuel efficiency. Don't use in heavy traffic or poor conditions.", category: "Vehicle Handling" },
  { id: 596, question: "What should you do if a front tyre bursts?", options: ["Brake sharply", "Hold the steering firmly, slow down gradually, and stop safely", "Accelerate to stay in control", "Turn the engine off"], correctAnswer: 1, explanation: "Hold the steering wheel firmly as the car may pull to one side. Slow down gradually without harsh braking and pull over safely.", category: "Vehicle Handling" },
  { id: 597, question: "Why should you slow down when driving past a bus stop where a bus has stopped?", options: ["The bus might pull out", "Passengers may cross the road after getting off the bus", "Both of these", "Neither of these"], correctAnswer: 2, explanation: "Watch for the bus pulling out and for passengers, especially children, crossing the road from behind the bus.", category: "Vulnerable Road Users" },
  { id: 598, question: "What is the purpose of road camber?", options: ["To make driving more difficult", "To help water drain off the road surface", "To slow vehicles down", "To improve tyre grip"], correctAnswer: 1, explanation: "Road camber is the slight slope of the road surface from the centre to the edges, designed to help water drain off the road.", category: "Safety Margins" },
  { id: 599, question: "What should you do if your vehicle breaks down in a tunnel?", options: ["Wait in your car", "Switch off the engine, use hazard lights, leave the vehicle, and use emergency exits", "Try to push the car out", "Rev the engine"], correctAnswer: 1, explanation: "Switch off the engine to reduce fumes, turn on hazard lights, leave the vehicle, and head for an emergency exit.", category: "Accidents" },
  { id: 600, question: "What is the key principle of the Highway Code for all road users?", options: ["Drive as fast as possible", "Be considerate and show courtesy and respect to all other road users", "Only follow the rules when convenient", "Priority goes to the fastest vehicle"], correctAnswer: 1, explanation: "The Highway Code is based on the principle that all road users should be considerate, courteous, and respectful to one another.", category: "Attitude" },
  // ===== ADDITIONAL QUESTIONS (601–700) =====
  { id: 601, question: "What is the national speed limit on a single carriageway for a car?", options: ["50 mph", "60 mph", "70 mph", "40 mph"], correctAnswer: 1, explanation: "The national speed limit for cars on a single carriageway is 60 mph, unless signs indicate otherwise.", category: "Speed Limits" },
  { id: 602, question: "When should you use your hazard warning lights while driving?", options: ["When parking on double yellow lines", "To warn traffic behind of a hazard ahead on a motorway", "When you're lost", "To thank other drivers"], correctAnswer: 1, explanation: "On motorways you may briefly use hazard lights to warn following traffic of a hazard or sudden slow traffic ahead.", category: "Motorway Rules" },
  { id: 603, question: "What does a solid white line along the centre of the road mean?", options: ["You can overtake at any time", "You must not cross or straddle it unless it is safe and you can see clearly ahead", "The road is closed", "Parking is allowed"], correctAnswer: 1, explanation: "A solid white centre line means you must not cross or straddle it unless it is safe and necessary to access premises or pass a stationary vehicle.", category: "Road Markings" },
  { id: 604, question: "What is the minimum tread depth for car tyres by law?", options: ["1 mm", "1.6 mm", "2 mm", "3 mm"], correctAnswer: 1, explanation: "The legal minimum tyre tread depth for cars is 1.6 mm across the central three-quarters of the tyre.", category: "Vehicle Safety" },
  { id: 605, question: "What should you do if you see a horse rider on the road?", options: ["Sound your horn to let them know you're there", "Pass slowly and give plenty of room", "Flash your lights and speed past", "Drive close behind them"], correctAnswer: 1, explanation: "Pass horse riders slowly with plenty of room. Sudden noises or close passing can frighten horses.", category: "Vulnerable Road Users" },
  { id: 606, question: "When must you notify the DVLA about your vehicle?", options: ["Only when selling it", "When the vehicle details change, such as colour or registered keeper", "Only if it fails its MOT", "Never"], correctAnswer: 1, explanation: "You must notify the DVLA when there are changes to your vehicle such as colour, keeper, or if it is scrapped.", category: "Documents" },
  { id: 607, question: "What is the purpose of ABS (Anti-lock Braking System)?", options: ["To stop the car faster", "To prevent the wheels from locking so you can still steer under heavy braking", "To reduce fuel consumption", "To increase engine power"], correctAnswer: 1, explanation: "ABS prevents wheels from locking during heavy braking, allowing you to maintain steering control.", category: "Vehicle Safety" },
  { id: 608, question: "What should you do at a pelican crossing when the amber light is flashing?", options: ["Accelerate to clear the crossing", "Give way to pedestrians still on the crossing", "Sound your horn", "Stop and wait for green"], correctAnswer: 1, explanation: "A flashing amber light at a pelican crossing means you must give way to pedestrians still on the crossing, but may proceed if clear.", category: "Pedestrian Crossings" },
  { id: 609, question: "How does alcohol affect your driving?", options: ["It improves reaction time", "It gives a false sense of confidence and reduces coordination and judgement", "It has no effect in small amounts", "It only affects night driving"], correctAnswer: 1, explanation: "Alcohol impairs judgement, coordination, and reaction times. It gives a false sense of confidence, making you a danger on the road.", category: "Alertness" },
  { id: 610, question: "What does a flashing green light at a Puffin crossing mean?", options: ["Speed up", "The crossing has sensors and there is no flashing green; it changes like normal traffic lights", "Pedestrians are crossing", "Give way"], correctAnswer: 1, explanation: "Puffin crossings have sensors that detect pedestrians and operate like normal traffic lights with no flashing green phase.", category: "Pedestrian Crossings" },
  { id: 611, question: "What is the legal blood alcohol limit for drivers in England and Wales?", options: ["50 mg per 100 ml", "80 mg per 100 ml", "35 mg per 100 ml", "Zero"], correctAnswer: 1, explanation: "The legal limit in England and Wales is 80 mg of alcohol per 100 ml of blood. However, the safest option is not to drink at all.", category: "Safety Margins" },
  { id: 612, question: "What should you check before towing a caravan?", options: ["Only the tyre pressure of your car", "That the noseweight, mirrors, lights, and coupling are all correct", "Just the fuel level", "Nothing specific"], correctAnswer: 1, explanation: "Check the noseweight, towing mirrors, all lights, the security of the coupling, and that you don't exceed your vehicle's towing limit.", category: "Vehicle Handling" },
  { id: 613, question: "Why are motorcyclists particularly vulnerable at junctions?", options: ["They always run red lights", "They are smaller and harder to see", "They travel too slowly", "They don't use indicators"], correctAnswer: 1, explanation: "Motorcyclists are smaller and can be hidden in blind spots, making them harder to spot at junctions. Always look carefully.", category: "Vulnerable Road Users" },
  { id: 614, question: "What does a blue circular sign with a white bicycle mean?", options: ["No cycling", "Route for cyclists only", "End of cycle path", "Shared path"], correctAnswer: 1, explanation: "A blue circular sign with a white bicycle indicates a route designated for pedal cyclists only.", category: "Traffic Signs" },
  { id: 615, question: "When should you use fog lights?", options: ["Whenever it's dark", "When visibility is seriously reduced, generally below 100 metres", "In light rain", "At all times in winter"], correctAnswer: 1, explanation: "Use fog lights only when visibility is seriously reduced to below 100 metres. Switch them off when visibility improves as they can dazzle other drivers.", category: "Safety Margins" },
  { id: 616, question: "What is the stopping distance at 70 mph in dry conditions?", options: ["53 metres", "73 metres", "96 metres", "120 metres"], correctAnswer: 2, explanation: "At 70 mph the overall stopping distance is approximately 96 metres (315 feet) — 21m thinking distance plus 75m braking distance.", category: "Speed Limits" },
  { id: 617, question: "What should you do if your vehicle catches fire while driving?", options: ["Continue driving to a garage", "Stop safely, get everyone out, and call the fire brigade", "Open the bonnet to check", "Pour water on the engine"], correctAnswer: 1, explanation: "Pull over safely, get everyone out of the vehicle and well away from it, then call the emergency services.", category: "Accidents" },
  { id: 618, question: "What is 'coasting' and why is it bad?", options: ["Driving with the clutch down or in neutral, reducing control", "Driving along the coast", "Using cruise control", "Driving in first gear"], correctAnswer: 0, explanation: "Coasting means the engine is not connected to the wheels. This reduces your control of the vehicle, especially when going downhill.", category: "Vehicle Handling" },
  { id: 619, question: "What is the purpose of a catalytic converter?", options: ["To increase engine power", "To reduce harmful exhaust emissions", "To reduce fuel consumption", "To make the engine quieter"], correctAnswer: 1, explanation: "A catalytic converter reduces the harmful gases in exhaust emissions, helping to protect the environment.", category: "Environmental Issues" },
  { id: 620, question: "What should you do when driving behind a large goods vehicle on a wet road?", options: ["Drive close behind for shelter", "Drop back further to avoid spray reducing your visibility", "Overtake immediately", "Flash your lights"], correctAnswer: 1, explanation: "Large vehicles throw up a lot of spray in wet conditions. Stay well back so you can see clearly and be seen.", category: "Other Vehicles" },
  { id: 621, question: "What does a circular sign with a red border and the number 30 inside mean?", options: ["Minimum speed 30 mph", "Maximum speed 30 mph", "Distance to next junction 30 metres", "30 mph advisory speed"], correctAnswer: 1, explanation: "A circular sign with a red border and a number indicates the maximum speed limit on that road.", category: "Traffic Signs" },
  { id: 622, question: "When are you allowed to reverse from a side road into a main road?", options: ["At any time", "Never — it is too dangerous", "Only when there is no traffic", "Only during daylight"], correctAnswer: 1, explanation: "You should never reverse from a side road into a main road as it is extremely dangerous. Always reverse into the side road.", category: "Road Procedure" },
  { id: 623, question: "What does an MOT certificate confirm?", options: ["The vehicle is insured", "The vehicle met minimum safety and environmental standards at the time of the test", "The vehicle will be roadworthy for 12 months", "The vehicle doesn't need servicing"], correctAnswer: 1, explanation: "An MOT certificate confirms the vehicle met the required minimum standards at the time of the test. It does not guarantee future roadworthiness.", category: "Documents" },
  { id: 624, question: "What is the main benefit of an engine management warning light?", options: ["It tells you when to fill up", "It warns you of a problem with the engine that needs attention", "It shows your speed", "It means the engine is fine"], correctAnswer: 1, explanation: "The engine management light indicates a fault in the engine system. Have it checked as soon as possible to avoid damage or breakdown.", category: "Vehicle Safety" },
  { id: 625, question: "Why should you be particularly careful when driving near schools?", options: ["Speed limits are always lower", "Children may run into the road unexpectedly", "Teachers may direct traffic", "Schools have speed cameras"], correctAnswer: 1, explanation: "Children are unpredictable and may run into the road without looking, especially near schools. Always be extra cautious.", category: "Vulnerable Road Users" },
  { id: 626, question: "What does a brown tourist sign indicate?", options: ["Motorway services", "A tourist attraction or facility", "A hospital", "A school"], correctAnswer: 1, explanation: "Brown signs direct you to tourist attractions and facilities such as historic buildings, theme parks, and nature reserves.", category: "Traffic Signs" },
  { id: 627, question: "What should you do if you have a collision with an animal on the road?", options: ["Drive on if the animal runs away", "Stop and report it to the police if required by law", "Move the animal yourself", "Ignore it"], correctAnswer: 1, explanation: "If you hit certain animals (horse, cattle, pig, goat, sheep, dog, donkey, mule) you must report it to the police.", category: "Accidents" },
  { id: 628, question: "What is the main risk of using cruise control in heavy rain?", options: ["Using more fuel", "Wheels may aquaplane without you noticing the loss of traction", "The car will speed up", "The wipers won't work"], correctAnswer: 1, explanation: "In wet conditions, cruise control can be dangerous because you may not notice aquaplaning until it's too late. Maintain manual control.", category: "Safety Margins" },
  { id: 629, question: "What does a green arrow filter light at traffic signals mean?", options: ["Stop and wait", "You may proceed in the direction of the arrow regardless of other lights", "Give way to oncoming traffic", "Pedestrians are crossing"], correctAnswer: 1, explanation: "A green arrow filter light allows you to go in the direction shown regardless of other signals, but check it is safe first.", category: "Traffic Signs" },
  { id: 630, question: "What is tailgating?", options: ["Driving with your boot open", "Driving too close to the vehicle in front", "Driving in reverse", "Loading the rear of a van"], correctAnswer: 1, explanation: "Tailgating means driving too close to the vehicle in front. It is dangerous as it reduces your ability to stop safely.", category: "Attitude" },
  { id: 631, question: "When can you cross a double white line where the line nearest to you is solid?", options: ["To overtake a slow vehicle", "To enter premises or pass a stationary obstruction", "Whenever it's safe to do so", "At any time"], correctAnswer: 1, explanation: "You may cross a solid white line nearest to you only to enter premises, pass a stationary obstruction, or pass a road maintenance vehicle, pedal cycle, horse or slow vehicle travelling at 10 mph or less.", category: "Road Markings" },
  { id: 632, question: "What is the recommended following distance in good dry conditions?", options: ["One car length", "At least a two-second gap", "Five car lengths", "One second gap"], correctAnswer: 1, explanation: "In good dry conditions, keep at least a two-second gap behind the vehicle in front. Double this in wet conditions.", category: "Safety Margins" },
  { id: 633, question: "What does 'THINK' before you overtake mean?", options: ["Think about fuel", "Consider the safety of the manoeuvre — is it necessary, legal, and safe?", "Think about your destination", "Think about your speed only"], correctAnswer: 1, explanation: "Before overtaking, ask yourself: Is it necessary? Is it safe? Is it legal? Can I complete it without risk?", category: "Attitude" },
  { id: 634, question: "What does a red triangle on the road warn about?", options: ["Speed bump", "It's a warning triangle placed by a driver to alert others of a breakdown or accident", "Road works", "Level crossing"], correctAnswer: 1, explanation: "A red warning triangle is placed on the road by a driver to warn other road users of a hazard such as a broken-down vehicle.", category: "Accidents" },
  { id: 635, question: "Why should you check for motorcyclists before opening your car door?", options: ["They might scratch your door", "A motorcyclist could be passing and hit the door, causing serious injury", "It's not necessary", "Only check for cars"], correctAnswer: 1, explanation: "Always check your mirrors and blind spot before opening the door. The 'Dutch Reach' method (using the far hand) encourages you to look over your shoulder.", category: "Vulnerable Road Users" },
  { id: 636, question: "What is the purpose of yellow box markings at a junction?", options: ["Reserved parking", "You must not enter unless your exit is clear, except when turning right", "Speed restriction zone", "Loading zone"], correctAnswer: 1, explanation: "Yellow box junctions keep junctions clear. Don't enter unless your exit is clear, unless you're turning right and only blocked by oncoming traffic.", category: "Road Markings" },
  { id: 637, question: "What should you do if you see a school crossing patrol showing a 'STOP' sign?", options: ["Slow down and try to pass", "Stop and wait until the patrol officer signals you can go", "Sound your horn to warn children", "Flash your lights"], correctAnswer: 1, explanation: "You must stop when a school crossing patrol shows the 'STOP' sign and wait until all children have crossed and the patrol has moved aside.", category: "Vulnerable Road Users" },
  { id: 638, question: "What is regenerative braking?", options: ["Braking that damages the brakes", "A system in electric/hybrid cars that recovers energy when slowing down", "Using the handbrake while moving", "Braking with engine off"], correctAnswer: 1, explanation: "Regenerative braking recovers kinetic energy during deceleration and converts it to electricity to recharge the battery in electric and hybrid vehicles.", category: "Environmental Issues" },
  { id: 639, question: "When driving on ice, what should you do?", options: ["Brake hard to stop quickly", "Drive slowly in the highest gear possible, using gentle inputs", "Use only the handbrake", "Accelerate to maintain momentum"], correctAnswer: 1, explanation: "On ice, drive slowly in a high gear, using gentle steering, braking, and acceleration to avoid losing grip.", category: "Safety Margins" },
  { id: 640, question: "What does a sign with a white 'H' on a blue background indicate?", options: ["Hotel ahead", "Hospital ahead", "Helicopter landing site", "Historic site"], correctAnswer: 1, explanation: "A white 'H' on a blue background directs you to a hospital with accident and emergency facilities.", category: "Traffic Signs" },
  { id: 641, question: "What is the purpose of engine braking?", options: ["To wear out the engine", "To slow the vehicle by releasing the accelerator and using the engine's resistance", "To speed up the car", "To save brake pads only"], correctAnswer: 1, explanation: "Engine braking uses the resistance of the engine to slow the vehicle. It is particularly useful on long downhill stretches.", category: "Vehicle Handling" },
  { id: 642, question: "What should you do if you puncture a tyre on a motorway?", options: ["Stop on the carriageway", "Pull onto the hard shoulder or to an emergency area, then call for assistance", "Continue at a slow speed", "Change the tyre in the outside lane"], correctAnswer: 1, explanation: "Pull to the hard shoulder or emergency area. Do not attempt to change a tyre on the motorway — call for assistance.", category: "Motorway Rules" },
  { id: 643, question: "What is the danger of parking your vehicle on the pavement?", options: ["It may roll away", "It blocks pedestrians, especially those with pushchairs or wheelchairs", "It wears out the tyres", "There is no danger"], correctAnswer: 1, explanation: "Parking on the pavement forces pedestrians into the road, which is especially dangerous for those with mobility issues or pushchairs.", category: "Attitude" },
  { id: 644, question: "When should headlights be used during the day?", options: ["Always", "When visibility is poor, such as in fog, heavy rain, or snow", "Never", "Only on motorways"], correctAnswer: 1, explanation: "Use dipped headlights during the day when visibility is seriously reduced by weather conditions.", category: "Vehicle Safety" },
  { id: 645, question: "What is a contraflow system on a motorway?", options: ["A breakdown lane", "Where traffic flows in both directions on the same carriageway", "Where lorries are banned", "A bus lane"], correctAnswer: 1, explanation: "A contraflow system is used during roadworks where traffic in both directions shares one carriageway. Stay in your lane and obey reduced speed limits.", category: "Motorway Rules" },
  { id: 646, question: "What is the 'two-second rule'?", options: ["Wait two seconds before moving off", "Maintain at least a two-second gap behind the vehicle in front", "Check mirrors every two seconds", "Signal for two seconds before turning"], correctAnswer: 1, explanation: "The two-second rule helps you maintain a safe following distance. Pick a fixed point and ensure at least two seconds pass before you reach it.", category: "Safety Margins" },
  { id: 647, question: "What should you do when approaching a level crossing with flashing red lights?", options: ["Speed up to cross quickly", "Stop and wait behind the white line until the lights stop flashing", "Drive around the barriers", "Reverse away"], correctAnswer: 1, explanation: "Stop and wait when red lights flash at a level crossing. A train is approaching. Never drive around the barriers.", category: "Road Procedure" },
  { id: 648, question: "What does an orange badge (Blue Badge) displayed on a vehicle indicate?", options: ["The driver is an instructor", "The vehicle is used by a disabled person who may need extra time or space", "The vehicle is exempt from speed limits", "The vehicle is a taxi"], correctAnswer: 1, explanation: "A Blue Badge indicates the vehicle is used by or for a disabled person. They may need extra time at junctions or wider parking spaces.", category: "Vulnerable Road Users" },
  { id: 649, question: "What is the main risk when driving through a ford?", options: ["Getting the car dirty", "Water could flood the engine or cause loss of control", "The water is too deep to see the road", "Speed cameras are common at fords"], correctAnswer: 1, explanation: "Water can flood the engine, affect brakes, and cause loss of control. Drive slowly in a low gear and test your brakes afterwards.", category: "Vehicle Handling" },
  { id: 650, question: "What should you do when leaving a motorway?", options: ["Slow down on the carriageway", "Use the deceleration lane (slip road) to adjust your speed", "Stop on the hard shoulder first", "Flash your lights"], correctAnswer: 1, explanation: "Use the slip road to reduce your speed. After driving at high speeds, your perception of speed may be affected, so check your speedometer.", category: "Motorway Rules" },
  { id: 651, question: "Why are convex mirrors fitted to some vehicles?", options: ["To make objects look closer", "To give a wider field of vision, though objects appear further away", "To reduce glare", "For decoration"], correctAnswer: 1, explanation: "Convex mirrors give a wider field of view but make objects appear smaller and further away than they really are.", category: "Vehicle Safety" },
  { id: 652, question: "What should you do if you see an ambulance with flashing lights in your mirror?", options: ["Speed up to get out of the way", "Pull over safely when you can to let it pass", "Stop immediately wherever you are", "Ignore it"], correctAnswer: 1, explanation: "When you see an emergency vehicle, stay calm, check where it's coming from, and pull over when safe to let it pass. Don't brake suddenly or mount the kerb.", category: "Other Vehicles" },
  { id: 653, question: "What is the penalty for driving without insurance?", options: ["A warning letter", "A fixed penalty, points on your licence, and possible disqualification", "No penalty if you have an MOT", "Only a small fine"], correctAnswer: 1, explanation: "Driving without insurance is a serious offence. You can receive a fixed penalty of £300, 6-8 penalty points, and your vehicle may be seized.", category: "Documents" },
  { id: 654, question: "What is the correct procedure for a hill start?", options: ["Rev the engine hard and release the clutch quickly", "Apply the handbrake, find the biting point, check mirrors and blind spot, then release the handbrake as you move off", "Roll backwards first", "Start in third gear"], correctAnswer: 1, explanation: "Use the handbrake to prevent rolling, find the biting point, check it's safe, then coordinate releasing the handbrake with gentle acceleration.", category: "Vehicle Handling" },
  { id: 655, question: "What does it mean if your steering feels heavy?", options: ["The car is overloaded", "There may be a fault with the power steering, or tyre pressure may be low", "It's normal in cold weather", "The brakes are dragging"], correctAnswer: 1, explanation: "Heavy steering could indicate a power steering failure or underinflated tyres. Have it checked immediately.", category: "Vehicle Safety" },
  { id: 656, question: "Why should you avoid revving the engine excessively?", options: ["It makes the car go faster", "It wastes fuel, increases emissions, and causes unnecessary wear", "It's good for the engine", "It only affects diesel engines"], correctAnswer: 1, explanation: "Excessive revving wastes fuel, increases harmful emissions, and causes premature engine wear. Drive smoothly and change gear early.", category: "Environmental Issues" },
  { id: 657, question: "What is the legal requirement for wearing seat belts in the rear of a car?", options: ["Only children must wear them", "All passengers aged 14 and over are responsible for wearing their own seat belt", "Rear passengers don't need to", "Only on motorways"], correctAnswer: 1, explanation: "All passengers aged 14+ are legally responsible for wearing their seat belt. The driver is responsible for passengers under 14.", category: "Vehicle Safety" },
  { id: 658, question: "When should you use the left-hand lane on a motorway?", options: ["Only when joining", "Whenever possible — it is the normal driving lane", "Only for slow vehicles", "Never"], correctAnswer: 1, explanation: "The left lane is the normal driving lane on a motorway. Use the other lanes for overtaking only, then return to the left.", category: "Motorway Rules" },
  { id: 659, question: "What is the 'lifesaver' check?", options: ["Checking your fuel level", "A final look over your shoulder into the blind spot before a manoeuvre", "Checking for a first aid kit", "Looking in the rear-view mirror"], correctAnswer: 1, explanation: "The lifesaver is a final check over your shoulder into the blind spot just before changing direction to ensure no one is hidden there.", category: "Alertness" },
  { id: 660, question: "What should you do if you are the first to arrive at the scene of an accident?", options: ["Drive past quickly", "Stop safely, warn other traffic, call emergency services, and give first aid if trained", "Move the injured people", "Block the road with your car"], correctAnswer: 1, explanation: "Stop safely, use hazard lights, warn other traffic, call 999, and provide first aid if you are trained to do so. Don't move injured people unless there's immediate danger.", category: "Accidents" },
  { id: 661, question: "What does a zigzag white line near a pedestrian crossing mean?", options: ["Speed up", "No parking or overtaking on these lines", "Bus stop ahead", "You can park briefly"], correctAnswer: 1, explanation: "Zigzag lines near crossings mean you must not park or overtake the lead vehicle on the approach. This ensures visibility for pedestrians and drivers.", category: "Road Markings" },
  { id: 662, question: "Why is it important to plan your journey before setting off?", options: ["To use more fuel", "To avoid getting lost, reduce stress, and minimise unnecessary mileage", "It's not important", "Only for long journeys"], correctAnswer: 1, explanation: "Planning your route saves time, fuel, and stress. You're also less likely to make last-minute dangerous decisions.", category: "Attitude" },
  { id: 663, question: "What should you do if a tyre blows out on a motorway?", options: ["Brake immediately", "Grip the steering wheel firmly, allow the vehicle to slow gradually, and pull over safely", "Swerve to the hard shoulder", "Accelerate"], correctAnswer: 1, explanation: "Hold the steering firmly, don't brake suddenly, let the vehicle slow naturally, and pull over to the hard shoulder or emergency area.", category: "Motorway Rules" },
  { id: 664, question: "What does a flashing amber beacon on a vehicle mean?", options: ["Emergency vehicle", "A slow-moving or potentially hazardous vehicle", "Police vehicle", "Vehicle is broken down"], correctAnswer: 1, explanation: "Flashing amber beacons warn of slow-moving vehicles like road maintenance, tractors, or abnormal loads. Pass with caution.", category: "Other Vehicles" },
  { id: 665, question: "What is the purpose of head restraints?", options: ["For comfort only", "To reduce neck injury (whiplash) in a rear-end collision", "To help you see behind", "To hold headphones"], correctAnswer: 1, explanation: "Head restraints are designed to reduce whiplash injuries by preventing excessive backward movement of the head in a collision.", category: "Vehicle Safety" },
  { id: 666, question: "When should you give way to buses?", options: ["Never", "When they signal to pull out from a bus stop, give way if safe to do so", "Always, in all situations", "Only on motorways"], correctAnswer: 1, explanation: "Give way to buses when they indicate to pull out from bus stops, when you can do so safely. They carry many passengers and run to a timetable.", category: "Other Vehicles" },
  { id: 667, question: "What is the purpose of a rumble strip?", options: ["To damage your tyres", "To alert you through vibration and noise, often near hazards or the edge of a motorway", "To slow traffic in towns", "To test your suspension"], correctAnswer: 1, explanation: "Rumble strips create noise and vibration to alert drivers. They're used near hazards, at the edge of motorways, and approaching roundabouts.", category: "Road Markings" },
  { id: 668, question: "What is a toucan crossing?", options: ["A crossing with a bird symbol", "A crossing shared by pedestrians and cyclists", "A crossing near a zoo", "A crossing with no lights"], correctAnswer: 1, explanation: "A toucan crossing is shared by pedestrians and cyclists. The name comes from 'two can' cross — both pedestrians and cyclists.", category: "Pedestrian Crossings" },
  { id: 669, question: "When driving in fog, why should you keep well back from the vehicle in front?", options: ["To see their rear lights clearly", "Because stopping distances are greatly increased and visibility is poor", "To avoid getting lost", "Fog makes cars faster"], correctAnswer: 1, explanation: "In fog, visibility and reaction times are reduced. Keep well back so you have enough time and distance to stop safely.", category: "Safety Margins" },
  { id: 670, question: "What does 'defensive driving' mean?", options: ["Driving aggressively to defend yourself", "Planning ahead, anticipating hazards, and driving safely to prevent accidents", "Driving very slowly everywhere", "Only driving in daylight"], correctAnswer: 1, explanation: "Defensive driving means being aware of hazards, planning ahead, and making allowances for other road users' mistakes.", category: "Attitude" },
  { id: 671, question: "What must you do when involved in a road traffic collision?", options: ["Drive away if there's no damage", "Stop, exchange details, and report to the police within 24 hours if you didn't exchange details at the scene", "Only stop if someone is hurt", "Call your insurance only"], correctAnswer: 1, explanation: "You must stop, give your details to anyone who has reasonable grounds to ask, and report to police within 24 hours if you didn't exchange details at the scene.", category: "Accidents" },
  { id: 672, question: "Why is it dangerous to use main beam headlights in fog?", options: ["They use too much battery", "The light reflects off the fog and reduces your visibility", "It's not dangerous", "They only work in clear weather"], correctAnswer: 1, explanation: "Main beam headlights reflect off fog particles and create a 'white wall' effect that reduces your visibility. Use dipped headlights and fog lights.", category: "Safety Margins" },
  { id: 673, question: "What does a sign showing two arrows pointing in opposite directions mean?", options: ["One-way street", "Two-way traffic crosses a one-way road or straight ahead", "No overtaking", "Dual carriageway ends"], correctAnswer: 1, explanation: "This sign warns that two-way traffic lies ahead or crosses your current route. Be prepared for oncoming vehicles.", category: "Traffic Signs" },
  { id: 674, question: "What is the benefit of eco-driving?", options: ["It makes the car faster", "It reduces fuel consumption, emissions, and running costs", "It's more dangerous", "It only applies to electric cars"], correctAnswer: 1, explanation: "Eco-driving techniques like smooth acceleration, early gear changes, and maintaining steady speed reduce fuel consumption and emissions.", category: "Environmental Issues" },
  { id: 675, question: "What should you do if your brakes fail while driving?", options: ["Turn off the engine immediately", "Pump the brake pedal, use a lower gear, and use the handbrake carefully", "Jump out of the car", "Sound your horn continuously"], correctAnswer: 1, explanation: "Pump the brake pedal rapidly, shift to a lower gear for engine braking, and apply the handbrake gradually while warning other road users.", category: "Vehicle Handling" },
  { id: 676, question: "What is the effect of carrying a roof rack on your car?", options: ["It improves fuel economy", "It increases fuel consumption due to wind resistance", "It has no effect", "It improves handling"], correctAnswer: 1, explanation: "A roof rack increases wind resistance (aerodynamic drag), which increases fuel consumption. Remove it when not in use.", category: "Environmental Issues" },
  { id: 677, question: "When must you use dipped headlights?", options: ["Only in fog", "At night on lit roads, in poor visibility, and when required by law", "Only on motorways", "Only when it's raining"], correctAnswer: 1, explanation: "Use dipped headlights at night on lit roads, in poor daytime visibility, and at dusk and dawn. Use main beam only where it won't dazzle others.", category: "Vehicle Safety" },
  { id: 678, question: "What is the correct action if you miss your exit on a motorway?", options: ["Reverse back to the exit", "Continue to the next exit and find an alternative route", "Stop on the hard shoulder", "Do a U-turn"], correctAnswer: 1, explanation: "Never reverse or stop on a motorway. Continue to the next exit and find an alternative route back.", category: "Motorway Rules" },
  { id: 679, question: "What is aquaplaning?", options: ["When the car flies", "When a layer of water builds between the tyres and road surface, causing loss of grip", "When the car overheats", "Driving through a puddle"], correctAnswer: 1, explanation: "Aquaplaning occurs when water builds up between the tyres and road faster than the tread can disperse it, causing loss of steering and braking.", category: "Safety Margins" },
  { id: 680, question: "What should you do before driving through a tunnel?", options: ["Remove sunglasses, turn on dipped headlights, and tune to the tunnel radio station if available", "Speed up", "Turn off your lights", "Close all windows only"], correctAnswer: 0, explanation: "Remove sunglasses, switch on dipped headlights, and tune into the tunnel's radio frequency for safety information.", category: "Road Procedure" },
  { id: 681, question: "When can you drive in a bus lane?", options: ["Never", "During the hours shown on the sign if your vehicle type is permitted", "Anytime if it's empty", "Only taxis can use bus lanes"], correctAnswer: 1, explanation: "Some bus lanes allow other vehicles during certain hours. Check the signs for times and permitted vehicle types.", category: "Road Procedure" },
  { id: 682, question: "What is the main cause of skidding?", options: ["Faulty brakes", "The driver — through harsh braking, acceleration, or steering", "Bad road surfaces", "Cold tyres"], correctAnswer: 1, explanation: "The driver is the main cause of skidding through excessive speed, harsh braking, fierce acceleration, or sudden steering movements.", category: "Vehicle Handling" },
  { id: 683, question: "What does the Highway Code say about using the horn?", options: ["Use it whenever you want", "Only use it to warn others of your presence; never to express annoyance", "It's optional", "Only in emergencies"], correctAnswer: 1, explanation: "The horn should only be used to warn others of your presence. Never use it aggressively. Don't use it between 11:30 pm and 7:00 am in built-up areas.", category: "Attitude" },
  { id: 684, question: "What should you check when buying a used car?", options: ["Only the colour", "Valid MOT, service history, HPI check, and that the VIN matches the documents", "Only the mileage", "Only the price"], correctAnswer: 1, explanation: "Check the MOT history, service records, do an HPI check for outstanding finance or write-offs, and verify the VIN matches the V5C.", category: "Documents" },
  { id: 685, question: "What is the purpose of traffic calming measures?", options: ["To annoy drivers", "To reduce vehicle speeds in residential areas for road safety", "To increase fuel consumption", "To block roads"], correctAnswer: 1, explanation: "Traffic calming measures like speed bumps, chicanes, and narrowings are designed to reduce speeds and improve safety in residential areas.", category: "Road Procedure" },
  { id: 686, question: "When should you apply the parking brake?", options: ["While driving slowly", "Whenever the vehicle is stationary and you need to secure it", "Only on hills", "Never in an automatic car"], correctAnswer: 1, explanation: "Apply the parking brake whenever you park or stop for more than a moment to prevent the vehicle from rolling.", category: "Vehicle Handling" },
  { id: 687, question: "What should you do if you're overtaking and realise it's unsafe to complete?", options: ["Speed up and finish overtaking", "Fall back safely behind the vehicle you were overtaking", "Sound your horn", "Flash your lights at oncoming traffic"], correctAnswer: 1, explanation: "If you cannot complete an overtake safely, slow down and fall back behind the vehicle. Never force your way through.", category: "Road Procedure" },
  { id: 688, question: "What is the meaning of a white arrow on a blue background?", options: ["No entry", "A mandatory direction you must follow", "Advisory route", "Pedestrian zone"], correctAnswer: 1, explanation: "White arrows on blue circular signs are mandatory — you must follow the direction indicated.", category: "Traffic Signs" },
  { id: 689, question: "Why should you ensure your vehicle is properly maintained?", options: ["To keep it looking good", "For safety, reliability, fuel efficiency, and legal compliance", "Only for the MOT test", "It's not important"], correctAnswer: 1, explanation: "Proper maintenance ensures your vehicle is safe, reliable, fuel-efficient, and meets legal requirements.", category: "Vehicle Safety" },
  { id: 690, question: "What is the safest way to use a mobile phone in a car?", options: ["Hold it in one hand", "Use it on speakerphone", "Park safely before using it", "Use it at traffic lights"], correctAnswer: 2, explanation: "The safest way is to park safely and switch off the engine before using your phone. Even hands-free use can be distracting.", category: "Alertness" },
  { id: 691, question: "What does red and amber showing together at traffic lights mean?", options: ["Go", "Stop — the lights are about to change to green but you must wait", "Caution", "Give way"], correctAnswer: 1, explanation: "Red and amber together means stop and wait. The lights are about to change to green, but do not go until the green light shows.", category: "Traffic Signs" },
  { id: 692, question: "What is the main purpose of tread on a tyre?", options: ["To look good", "To disperse water and maintain grip on the road", "To reduce speed", "To make noise"], correctAnswer: 1, explanation: "Tyre tread disperses water from the contact patch, maintaining grip on wet roads and reducing the risk of aquaplaning.", category: "Vehicle Safety" },
  { id: 693, question: "Why are older drivers potentially more vulnerable?", options: ["They always drive slowly", "They may have reduced reaction times, vision, or mobility", "They are not vulnerable", "They don't follow rules"], correctAnswer: 1, explanation: "Older drivers may have reduced reaction times, vision, hearing, or mobility. Be patient and give them extra time.", category: "Vulnerable Road Users" },
  { id: 694, question: "What is a smart motorway?", options: ["A motorway with WiFi", "A motorway that uses technology to manage traffic flow, sometimes using the hard shoulder as a running lane", "A motorway with solar panels", "A toll motorway"], correctAnswer: 1, explanation: "Smart motorways use variable speed limits, lane signals, and sometimes the hard shoulder as a running lane to manage traffic and reduce congestion.", category: "Motorway Rules" },
  { id: 695, question: "When is it legal to drive with sidelights only?", options: ["On any road at night", "On roads with a speed limit of 30 mph or less and with street lighting", "Never", "Only in car parks"], correctAnswer: 1, explanation: "You may park with sidelights on roads with a 30 mph speed limit and street lighting. For driving at night, use dipped headlights.", category: "Vehicle Safety" },
  { id: 696, question: "What should you do if you smell petrol fumes inside your car?", options: ["Ignore it", "Stop safely and investigate — there may be a fuel leak which is a fire risk", "Open the windows and continue", "Turn up the heating"], correctAnswer: 1, explanation: "Petrol fumes indicate a possible fuel leak, which is a serious fire risk. Stop safely, investigate, and do not restart until it's fixed.", category: "Vehicle Safety" },
  { id: 697, question: "What is the safest position for a child seat?", options: ["The front passenger seat", "The rear seat, properly secured with the seat belt or ISOFIX", "On the driver's lap", "Any seat without a belt"], correctAnswer: 1, explanation: "The safest place for a child seat is in the rear of the car, properly secured with the seat belt or ISOFIX points.", category: "Vehicle Safety" },
  { id: 698, question: "What should you do when driving in strong crosswinds?", options: ["Speed up to get through quickly", "Reduce speed and keep a firm grip on the steering wheel, especially on exposed roads", "Only drive on motorways", "Close your eyes briefly"], correctAnswer: 1, explanation: "Strong crosswinds can blow your vehicle off course. Reduce speed and be extra careful on exposed roads, bridges, and when passing high-sided vehicles.", category: "Safety Margins" },
  { id: 699, question: "What is the correct sequence of traffic lights?", options: ["Green, amber, red, green", "Red, red and amber, green, amber, red", "Red, green, amber, red", "Green, red, amber, green"], correctAnswer: 1, explanation: "The sequence is: red (stop), red and amber (stop, about to change), green (go if safe), amber (stop unless unsafe to do so), then red again.", category: "Traffic Signs" },
  { id: 700, question: "What should responsible drivers do to reduce their environmental impact?", options: ["Drive faster to spend less time on the road", "Walk, cycle, or use public transport for short journeys, maintain their vehicle, and drive smoothly", "Only drive diesel cars", "Nothing — individual actions don't matter"], correctAnswer: 1, explanation: "Responsible drivers reduce their impact by using alternative transport when possible, maintaining their vehicle properly, and adopting smooth driving techniques.", category: "Environmental Issues" },
];
